-- Disposable PG17 only, as a superuser (the sessions below switch session authorization), from the repository root:
--   psql -X -v ON_ERROR_STOP=1 -d dm_refinement_image_evidence_writers -f supabase/sql/test_image_evidence_writers.sql
-- scripts/ci/run-db-contracts.sh runs it that way in the db-contracts job. It writes one scratch file under /tmp (each
-- RESULT check's output, read back with `cat`) and creates and drops its own databases.
-- Contract for 20261021221000_image_evidence_writers_and_readers.sql (M1w) on top of the deployed
-- 20261021220000_image_evidence_tables.sql (M1a), both applied from the repo AS a non-superuser owner, as postgres is
-- live, beside live-shaped stand-ins for the existing tables M1w reads and the auth server's session and factor records.
-- The design's scratch simulation (design v11) ran every scenario below and listed, statement by statement, what each
-- must print or how it must fail; this file carries those lists as assertions:
--   * the template: M1w applied TWICE (the second apply succeeds and changes no function body, ACL, config, view or
--     index), its 47 functions and 3 views as declared, M1a's er_one_answers_per_sheet dropped, 6 indexes created;
--     then every group runs on its own copy of it, so no scenario sees another's rows;
--   * a statement that must print (RESULT) prints exactly the listed output, ids, timestamps and digests normalised;
--   * a statement that must fail (REFUSED) fails with the listed SQLSTATE and message, at top level (frame-sensitive);
--   * scenario_v9.sql, scenario_v10.sql, scenario_v11.sql: already written as assertions, run as written;
--   * every agent-channel decide_evidence call the v4-v7 scenarios made is refused (42501, no EXECUTE for service_role);
--   * R-P1: 2,000 answered rows and 2,000 owner decisions, evidence_answers_to_confirm timed for the owner and the job;
--   * F4: one vehicle at 10x the pilot's volume, every vehicle read timed before and after its evidence is analyzed;
--   * (design v10) A4: 8,000 slot answer rows over 50,000 candidates, the confirmation reader timed; and the gate
--     race: his "no" to a day, still uncommitted in his own session while a pass writes that day (two real sessions
--     through dblink, ordered by the server's own lock wait);
--   * not asserted: the calls a scenario keeps in a psql variable (:PROBE, :COSTS, :SUM, ...; 78 calls) run for
--     the state later checks read, since the design's capture listed no output for them.
-- Timing bounds, each set so that CI (it runs contracts 1.6-3.2x slower than the machine these were measured on: median
-- and worst per contract, main's run of 2026-10-20; its image has JIT on, these groups set the live planner settings,
-- jit off among them) stays inside it while the defect it guards against still fails it:
--   F4 after ANALYZE under 1 s (the quadratic plan inside the reader, design v6, read one 10x vehicle in 4.4-4.5 s);
--   F4 before ANALYZE (rows just loaded, no statistics yet) under 3 s;
--   R-P1 under 2 s (the confirmation list it was raised against took 22 s);
--   A4 under 3 s (it timed out at 15 s in design v9; its load analyzes only its first batch).
-- Measured where this file was built: 3 runs: F4 vehicle reads 0.15-0.38 s after ANALYZE, 0.56-1.56 s before;
--   R-P1 0.49-0.50 s after, 0.48 s before; A4 0.78-1.22 s.
-- Ids are random (gen_random_uuid() or replaced literals); names, ledger lines, files and messages are synthetic.
-- ALLOW_RAW_TESTIMONY_WRITE: the INSERTs below write synthetic fixture rows into the stand-in tables of the disposable
-- databases this file creates and drops; never a live database.
-- The owner channel reads auth.sessions / auth.mfa_factors / auth.mfa_amr_claims: each owner session the scenarios use
-- is seeded there (a verified totp factor enrolled 30 days ago, verified now); the negative sessions as the design
-- sim seeds them (a factor enrolled today, a verification an hour old, an aal1 session).
\set ON_ERROR_STOP on
\set QUIET on
\pset pager off
DO $$ BEGIN
  IF current_database() NOT LIKE 'dm_%' OR current_setting('server_version_num')::int / 10000 <> 17
    OR to_regclass('public.evidence_runs') IS NOT NULL OR to_regclass('public.vehicle_images') IS NOT NULL THEN
    RAISE EXCEPTION 'Empty disposable PG17 database required';
  END IF;
  IF NOT (SELECT rolsuper FROM pg_roles WHERE rolname = current_user) THEN
    RAISE EXCEPTION 'Run as a superuser: the sessions below switch session authorization and create databases';
  END IF;
END $$;
SELECT current_database() AS main_db, left(current_database(), 48) || '_tmpl' AS tmpl_db,
       '/tmp/' || current_database() || '_' || pg_backend_pid() || '.out' AS outf, 0 AS passed_total \gset
DO $$ BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'anon') THEN CREATE ROLE anon NOLOGIN; END IF;
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'authenticated') THEN CREATE ROLE authenticated NOLOGIN; END IF;
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'service_role') THEN CREATE ROLE service_role NOLOGIN BYPASSRLS; END IF;
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'authenticator') THEN CREATE ROLE authenticator LOGIN NOINHERIT; END IF;
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'dm_contract_evidence_owner') THEN
    CREATE ROLE dm_contract_evidence_owner NOLOGIN NOSUPERUSER CREATEROLE BYPASSRLS;
  END IF;
END $$;
GRANT anon, authenticated, service_role TO authenticator;
GRANT anon, authenticated, service_role, authenticator TO dm_contract_evidence_owner;


-- ================================================================================================ the template database
-- ICU en-US collation (the design sim's ordering; the CI image's libc collation sorts '_' and case differently)
-- Every database this file makes is named <main database, first 48 characters>_<suffix>: any such database a stopped
-- earlier run left behind is dropped first (the runner's reset drops them after a failed run as well)
SELECT format('DROP DATABASE IF EXISTS %I WITH (FORCE)', datname) FROM pg_database
 WHERE left(datname, length(left(:'main_db', 48)) + 1) = left(:'main_db', 48) || '_' AND datname <> :'main_db' \gexec
DROP DATABASE IF EXISTS :"tmpl_db" WITH (FORCE);
CREATE DATABASE :"tmpl_db" TEMPLATE template0 OWNER dm_contract_evidence_owner LOCALE_PROVIDER icu ICU_LOCALE 'en-US' LOCALE 'C';
\c :tmpl_db
SET TimeZone = 'America/Los_Angeles'; SET DateStyle = 'ISO, MDY';
ALTER SCHEMA public OWNER TO dm_contract_evidence_owner;
-- auth.uid() and auth.role() as live defines them; auth.jwt() as live: request.jwt.claim, else request.jwt.claims.
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT coalesce(nullif(current_setting('request.jwt.claim.sub', true), ''),
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub'))::uuid $$;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql STABLE AS $$
  SELECT coalesce(nullif(current_setting('request.jwt.claim.role', true), ''),
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role'))::text $$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS $$
  SELECT coalesce(nullif(current_setting('request.jwt.claim', true), ''),
    nullif(current_setting('request.jwt.claims', true), ''))::jsonb $$;
-- the auth server's records the owner channel reads (live columns and enum types; only these columns are read)
CREATE TYPE auth.aal_level AS ENUM ('aal1', 'aal2', 'aal3');
CREATE TYPE auth.factor_type AS ENUM ('totp', 'webauthn', 'phone');
CREATE TYPE auth.factor_status AS ENUM ('unverified', 'verified');
CREATE TABLE auth.mfa_factors (id uuid PRIMARY KEY, user_id uuid NOT NULL, friendly_name text,
  factor_type auth.factor_type NOT NULL, status auth.factor_status NOT NULL, created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL);
CREATE TABLE auth.sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL, created_at timestamptz, updated_at timestamptz,
  factor_id uuid, aal auth.aal_level);
CREATE TABLE auth.mfa_amr_claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL,
  created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, authentication_method text NOT NULL,
  UNIQUE (session_id, authentication_method));
GRANT USAGE ON SCHEMA auth TO anon, authenticated, service_role, dm_contract_evidence_owner;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA auth TO anon, authenticated, service_role;
GRANT SELECT ON auth.sessions, auth.mfa_factors, auth.mfa_amr_claims TO dm_contract_evidence_owner;
-- seeds one owner session: a verified totp factor enrolled 30 days ago and verified now (kind 'young': enrolled today;
-- 'stale': verified an hour ago; 'aal1': an aal1 session with no factor)
CREATE FUNCTION auth.t_seed_session(p_session uuid, p_user uuid, p_kind text DEFAULT 'ok') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = auth, public, pg_temp AS $$
DECLARE f uuid := gen_random_uuid();
BEGIN
  IF p_kind = 'aal1' THEN
    INSERT INTO auth.sessions(id, user_id, created_at, updated_at, factor_id, aal) VALUES (p_session, p_user, now(), now(), NULL, 'aal1');
    RETURN;
  END IF;
  INSERT INTO auth.mfa_factors(id, user_id, friendly_name, factor_type, status, created_at, updated_at)
    VALUES (f, p_user, 'contract', 'totp', 'verified', CASE WHEN p_kind = 'young' THEN now() ELSE now() - interval '30 days' END, now());
  INSERT INTO auth.sessions(id, user_id, created_at, updated_at, factor_id, aal) VALUES (p_session, p_user, now(), now(), f, 'aal2');
  INSERT INTO auth.mfa_amr_claims(session_id, created_at, updated_at, authentication_method)
    VALUES (p_session, now(), CASE WHEN p_kind = 'stale' THEN now() - interval '1 hour' ELSE now() END, 'totp');
END $$;

-- assertion helpers: t_assert / t_refused as PR-1's contract (supabase/sql/test_image_evidence_tables.sql), plus
-- t_out: a RESULT check, the statement's printed rows normalised as the design sim's expected lists are
CREATE FUNCTION public.t_count() RETURNS void LANGUAGE sql AS $$
  SELECT set_config('t.passed', (coalesce(nullif(current_setting('t.passed', true), ''), '0')::int + 1)::text, false) $$;
CREATE FUNCTION public.t_assert(v boolean, label text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %', label; END IF; PERFORM public.t_count(); RAISE NOTICE 'PASS: %', label; END $$;
CREATE FUNCTION public.t_refused(label text, got_state text, got_message text, want_state text, want_like text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF got_state IS DISTINCT FROM want_state OR got_message NOT LIKE want_like THEN
    RAISE EXCEPTION 'FAIL: % (got % "%")', label, got_state, got_message;
  END IF;
  PERFORM public.t_count();
  RAISE NOTICE 'PASS: %', label;
END $$;
CREATE FUNCTION public.t_norm(s text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT regexp_replace(regexp_replace(regexp_replace(regexp_replace(s,
    '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', '<id>', 'g'),
    '\d{4}-\d\d-\d\d[ T]\d\d:\d\d:\d\d(\.\d+)?([+-]\d\d(:\d\d)?)?', '<ts>', 'g'),
    '\m[0-9a-f]{32,64}\M', '<hex>', 'g'),
    '(?<![0-9a-z])(?=[0-9a-f]{0,7}[0-9])(?=[0-9a-f]{0,7}[a-f])[0-9a-f]{8}(?![0-9a-z])', '<hex>', 'g') $$;
-- (design v10 on) a few scenarios build a VIN from their run's random tag ('VINR4' || 12 hex, '1GCEK14K8RZ' || 6 hex);
-- the capture printed one draw of it: both sides compare with the tag part written <tag>
CREATE FUNCTION public.t_tag(s text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT regexp_replace(regexp_replace(s, '\mVINR4[0-9A-F]{12}\M', 'VINR4<tag>', 'g'), '\m1GCEK14K8RZ[0-9A-F]{6}\M', '1GCEK14K8RZ<tag>', 'g') $$;
-- a printed JSON list whose items tie on everything but an id the database generated (gen_random_uuid(), printed
-- <id>) comes out in another order on another run: t_json_canon rewrites every JSON value in the text with each of its
-- arrays sorted (recursively), so two such printouts compare equal and nothing else about them is relaxed
CREATE FUNCTION public.t_canon(j jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
  IF jsonb_typeof(j) = 'array' THEN
    RETURN (SELECT coalesce(jsonb_agg(c ORDER BY c::text COLLATE "C"), '[]'::jsonb)
              FROM (SELECT public.t_canon(e) AS c FROM jsonb_array_elements(j) e) x);
  ELSIF jsonb_typeof(j) = 'object' THEN
    RETURN (SELECT coalesce(jsonb_object_agg(k, public.t_canon(v)), '{}'::jsonb) FROM jsonb_each(j) x(k, v));
  END IF;
  RETURN j;
END $$;
CREATE FUNCTION public.t_json_canon(s text) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE out text := ''; i int := 1; n int := length(s); ch text; d int; j int; instr boolean; esc boolean; parsed jsonb;
BEGIN
  WHILE i <= n LOOP
    IF substr(s, i, 1) IN ('[', '{') THEN
      d := 0; instr := false; esc := false; j := i;
      WHILE j <= n LOOP                  -- the matching close bracket, outside strings
        ch := substr(s, j, 1);
        IF instr THEN
          IF esc THEN esc := false; ELSIF ch = '\' THEN esc := true; ELSIF ch = '"' THEN instr := false; END IF;
        ELSIF ch = '"' THEN instr := true;
        ELSIF ch IN ('[', '{') THEN d := d + 1;
        ELSIF ch IN (']', '}') THEN d := d - 1; EXIT WHEN d = 0;
        END IF;
        j := j + 1;
      END LOOP;
      IF j <= n THEN
        BEGIN
          parsed := substr(s, i, j - i + 1)::jsonb;
          out := out || public.t_canon(parsed)::text;
          i := j + 1;
          CONTINUE;
        EXCEPTION WHEN others THEN NULL;   -- not JSON: keep the bracket as text
        END;
      END IF;
    END IF;
    out := out || substr(s, i, 1);
    i := i + 1;
  END LOOP;
  RETURN out;
END $$;
CREATE FUNCTION public.t_out(label text, got text, want text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE norm text;
BEGIN
  SELECT left(replace(public.t_norm(coalesce(string_agg(regexp_replace(l, '\s+$', ''), ' \n ' ORDER BY n), '')), E'\t', ' '), 2000)
    INTO norm
    FROM regexp_split_to_table(coalesce(got, ''), E'\n') WITH ORDINALITY AS x(l, n)
   WHERE btrim(l) <> '' AND l !~ '^(LOCATION|CONTEXT|DETAIL|HINT|QUERY|LINE \d+|Time):'
     AND l !~ '^\s*\^\s*$' AND l !~ '^(PL/pgSQL|SQL) (function|statement)';
  IF public.t_tag(norm) IS DISTINCT FROM public.t_tag(want) THEN
    IF public.t_json_canon(public.t_tag(norm)) = public.t_json_canon(public.t_tag(want)) THEN
      PERFORM public.t_count();
      RAISE NOTICE 'PASS (the same items in another order: generated ids break their ties): %', label;
      RETURN;
    END IF;
    RAISE EXCEPTION 'FAIL: % (got "%", want "%")', label, norm, want;
  END IF;
  PERFORM public.t_count();
  RAISE NOTICE 'PASS: %', label;
END $$;
-- t_out for a list whose order follows ids the scenario generates at run time (gen_random_uuid(): the capture's order
-- was one draw): the same text up to the list, and the same items after it in any order
CREATE FUNCTION public.t_out_unordered(label text, got text, want text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE norm text; p int; pre text;
BEGIN
  norm := public.t_norm(regexp_replace(coalesce(got, ''), '\s+$', ''));
  p := 0;      -- the longest common prefix, cut back to its last ': '
  WHILE p < least(length(norm), length(want)) AND substr(norm, p + 1, 1) = substr(want, p + 1, 1) LOOP p := p + 1; END LOOP;
  pre := substr(want, 1, p);
  p := length(pre) - strpos(reverse(pre), ' :') + 1;
  IF strpos(pre, ': ') = 0 OR substr(norm, 1, p) IS DISTINCT FROM substr(want, 1, p)
     OR (SELECT array_agg(x ORDER BY x COLLATE "C") FROM unnest(string_to_array(substr(norm, p + 1), ', ')) x)
        IS DISTINCT FROM (SELECT array_agg(x ORDER BY x COLLATE "C") FROM unnest(string_to_array(substr(want, p + 1), ', ')) x) THEN
    RAISE EXCEPTION 'FAIL: % (got "%", want "%", in any order)', label, norm, want;
  END IF;
  PERFORM public.t_count();
  RAISE NOTICE 'PASS: %', label;
END $$;
-- a psql variable copied with \set x :'y' holds y as a quoted literal; t_unq gives back y
CREATE FUNCTION public.t_unq(s text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE WHEN s ~ '^''.*''$' THEN replace(substr(s, 2, length(s) - 2), '''''', '''') ELSE s END $$;
GRANT EXECUTE ON FUNCTION public.t_count(), public.t_assert(boolean, text), public.t_refused(text, text, text, text, text),
  public.t_norm(text), public.t_out(text, text, text), public.t_unq(text) TO PUBLIC;

-- existing tables M1w reads, and the stand-ins the scenarios call, as the design sim's stubs define them (live shapes),
-- created by the owner
SET SESSION AUTHORIZATION dm_contract_evidence_owner;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON FUNCTIONS TO service_role;
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;
CREATE TABLE public.profiles (id uuid PRIMARY KEY);
CREATE TABLE public.vehicles (id uuid PRIMARY KEY, owner_id uuid, uploaded_by uuid, user_id uuid, deleted_at timestamptz,
  merged_into_vehicle_id uuid, status text, label text, is_public boolean DEFAULT false,
  vin text);   -- (v7) live vehicles.vin (text), read by evidence_places_distinct
CREATE TABLE public.vehicle_images (id uuid PRIMARY KEY, vehicle_id uuid, user_id uuid, is_superseded boolean DEFAULT false,
  taken_at timestamptz, file_hash text, is_primary boolean DEFAULT false, is_document boolean DEFAULT false,
  is_duplicate boolean DEFAULT false, is_sensitive boolean DEFAULT false, vision_gate_status text,
  is_approved boolean, approval_status text, updated_at timestamptz, merged_from_vehicle_id uuid, label text, image_url text);
CREATE UNIQUE INDEX idx_unique_vehicle_file_hash ON public.vehicle_images (vehicle_id, file_hash)
  WHERE file_hash IS NOT NULL AND vehicle_id IS NOT NULL AND coalesce(is_superseded, false) = false;
CREATE INDEX idx_vehicle_images_file_hash ON public.vehicle_images (file_hash) WHERE file_hash IS NOT NULL;
CREATE INDEX idx_vehicle_images_vehicle ON public.vehicle_images (vehicle_id);
CREATE TABLE public.receipts (id uuid PRIMARY KEY, user_id uuid);
CREATE TABLE public.work_sessions (id uuid PRIMARY KEY, user_id uuid, vehicle_id uuid, session_date date);
CREATE TABLE public.journal_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid, entity_id uuid);
CREATE TABLE public.deal_jackets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid, entity_id uuid);
CREATE TABLE public.image_observations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), image_id uuid, vehicle_id uuid, role text,
  is_active boolean DEFAULT true, confidence numeric, observed_by text, agent_version text, superseded_by uuid,
  confidence_basis jsonb DEFAULT '{}', is_high_confidence_subject boolean, observed_at timestamptz DEFAULT clock_timestamp());
CREATE TABLE public.reattribution_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), observation_type text, old_observation_id uuid,
  old_vehicle_id uuid, new_observation_id uuid, new_vehicle_id uuid, reason text, actor_user_id uuid, created_at timestamptz DEFAULT now());
CREATE TABLE public.vehicle_image_gate_changes (id bigserial PRIMARY KEY, run text, image_id uuid, vehicle_id uuid, method text, reason text,
  actor text, before_status text, after_status text, changed_at timestamptz DEFAULT clock_timestamp(), reverted_at timestamptz,
  UNIQUE (run, image_id));
CREATE TABLE public.vehicle_image_attribution_queue (image_id uuid PRIMARY KEY, queued_at timestamptz DEFAULT now(), attempts int DEFAULT 0, last_error text);
CREATE TABLE public.vehicle_merge_proposals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), primary_vehicle_id uuid, duplicate_vehicle_id uuid,
  status text, requires_approval_from uuid, detected_by text, created_at timestamptz DEFAULT now(), unmerged_at timestamptz,
  UNIQUE (primary_vehicle_id, duplicate_vehicle_id));
CREATE TABLE public.qb_transactions (id uuid PRIMARY KEY, organization_id uuid, vehicle_id uuid);
CREATE TABLE public.payment_events (id uuid PRIMARY KEY, user_id uuid);
-- v5: the image spine's appearance rows (live columns used: id, seen_by, source_type, source_identifier)
CREATE TABLE public.image_appearances (id uuid PRIMARY KEY, seen_by uuid, source_type text, source_identifier text);

CREATE FUNCTION public.user_can_edit_vehicle(p_vehicle uuid, p_user uuid) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT EXISTS (SELECT 1 FROM public.vehicles v WHERE v.id = p_vehicle AND p_user IN (v.owner_id, v.uploaded_by, v.user_id)) $$;

-- attribute_testimony: live first-filing shape (gate pending -> approved when not sensitive), hash check, audit row.
CREATE FUNCTION public.attribute_testimony(p_t text, p_id uuid, p_v uuid, p_reason text, p_actor uuid DEFAULT NULL, p_c numeric DEFAULT NULL, p_s text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM vehicles WHERE id = p_v) THEN RAISE EXCEPTION 'target vehicle % does not exist', p_v; END IF;
  IF (SELECT vehicle_id FROM vehicle_images WHERE id = p_id) IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_attributed'); END IF;
  IF EXISTS (SELECT 1 FROM vehicle_images o, vehicle_images i WHERE i.id = p_id AND i.file_hash IS NOT NULL AND o.file_hash = i.file_hash
              AND o.vehicle_id = p_v) THEN                -- v4: live counts superseded rows too
    RETURN jsonb_build_object('success', false, 'error', 'file_hash_exists_on_target'); END IF;
  UPDATE vehicle_images SET vehicle_id = p_v, is_primary = false,
         vision_gate_status = CASE WHEN vision_gate_status = 'pending' AND NOT coalesce(is_sensitive,false) THEN 'approved' ELSE vision_gate_status END
   WHERE id = p_id;
  INSERT INTO reattribution_audit(observation_type, old_observation_id, new_observation_id, new_vehicle_id, reason, actor_user_id)
  VALUES ('image', p_id, p_id, p_v, 'first_attribution: '||p_reason, p_actor);
  RETURN jsonb_build_object('success', true, 'mode', 'first_attribution');
END $$;

-- relink_testimony: live guard (refuses deleted or merged targets with a RAISE), hash check, merged_from kept, audit row.
CREATE FUNCTION public.relink_testimony(p_t text, p_id uuid, p_v uuid, p_reason text, p_actor uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE o uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM vehicles WHERE id = p_v AND deleted_at IS NULL AND status IS DISTINCT FROM 'merged') THEN
    RAISE EXCEPTION 'target vehicle % does not exist', p_v;
  END IF;
  IF EXISTS (SELECT 1 FROM vehicle_images o2, vehicle_images i WHERE i.id = p_id AND i.file_hash IS NOT NULL AND o2.file_hash = i.file_hash
              AND o2.vehicle_id = p_v AND o2.id <> p_id) THEN   -- v4: live counts superseded rows too
    RETURN jsonb_build_object('success', false, 'error', 'file_hash_exists_on_target'); END IF;
  SELECT vehicle_id INTO o FROM vehicle_images WHERE id = p_id FOR UPDATE;
  UPDATE vehicle_images SET vehicle_id = p_v, is_primary = false, merged_from_vehicle_id = coalesce(merged_from_vehicle_id, o) WHERE id = p_id;
  INSERT INTO reattribution_audit(observation_type, old_observation_id, old_vehicle_id, new_observation_id, new_vehicle_id, reason, actor_user_id)
  VALUES ('image', p_id, o, p_id, p_v, p_reason, p_actor);
  RETURN jsonb_build_object('success', true, 'mode', 'relink_in_place');
END $$;

-- ingest_image_observation: the live supersession rule for a non-protected producer (body l.615-643).
CREATE FUNCTION public.ingest_image_observation(p_image uuid, p_vehicle uuid, p_role text, p_conf numeric, p_by text, p_ver text,
  p_basis jsonb DEFAULT '{}', p_flag boolean DEFAULT NULL, p_extra jsonb DEFAULT '{}') RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE n uuid; e uuid;
BEGIN
  SELECT id INTO e FROM image_observations WHERE image_id = p_image AND observed_by = p_by AND agent_version IS NOT DISTINCT FROM p_ver AND is_active
   ORDER BY observed_at DESC, id DESC LIMIT 1 FOR UPDATE;
  IF e IS NOT NULL THEN UPDATE image_observations SET is_active = false WHERE id = e; END IF;
  INSERT INTO image_observations(image_id, vehicle_id, role, confidence, observed_by, agent_version, confidence_basis, is_high_confidence_subject)
  VALUES (p_image, p_vehicle, p_role, p_conf, p_by, p_ver, coalesce(p_basis,'{}'), p_flag) RETURNING id INTO n;
  IF e IS NOT NULL THEN UPDATE image_observations SET superseded_by = n WHERE id = e; END IF;
  RETURN n;
END $$;

-- hold / revert: the live gate filter (NULL or approved only), one change per (run, image), and the gate_changes ledger.
CREATE FUNCTION public.hold_vehicle_images_for_review(p_vehicle_id uuid, p_items jsonb, p_method text, p_reason text, p_run text, p_apply boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE v_held int := 0;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM vehicles WHERE id = p_vehicle_id) THEN RAISE EXCEPTION 'Vehicle not found'; END IF;
  IF p_apply THEN
    WITH upd AS (
      UPDATE vehicle_images vi SET vision_gate_status = 'review_needed'
        FROM jsonb_array_elements(p_items) x
       WHERE vi.id = (x->>'image_id')::uuid AND vi.vehicle_id = p_vehicle_id
         AND (vi.vision_gate_status IS NULL OR vi.vision_gate_status = 'approved')
         AND NOT EXISTS (SELECT 1 FROM vehicle_image_gate_changes c WHERE c.run = p_run AND c.image_id = vi.id)
      RETURNING vi.id, (SELECT b.vision_gate_status FROM vehicle_images b WHERE b.id = vi.id) AS before_status),
    ins AS (INSERT INTO vehicle_image_gate_changes(run, image_id, vehicle_id, method, reason, before_status, after_status)
            SELECT p_run, id, p_vehicle_id, p_method, p_reason, before_status, 'review_needed' FROM upd RETURNING 1)
    SELECT count(*) INTO v_held FROM ins;
  END IF;
  RETURN jsonb_build_object('run', p_run, 'applied', p_apply, 'held', CASE WHEN p_apply THEN v_held END);
END $$;
CREATE FUNCTION public.revert_vehicle_image_review_hold(p_run text, p_image_ids uuid[] DEFAULT NULL, p_apply boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE n int := 0;
BEGIN
  IF p_apply THEN
    WITH r AS (UPDATE vehicle_images vi SET vision_gate_status = c.before_status
                 FROM vehicle_image_gate_changes c
                WHERE c.image_id = vi.id AND c.run = p_run AND c.reverted_at IS NULL AND vi.vision_gate_status = c.after_status
                  AND (p_image_ids IS NULL OR c.image_id = ANY (p_image_ids)) RETURNING c.id),
         m AS (UPDATE vehicle_image_gate_changes c SET reverted_at = now() FROM r WHERE c.id = r.id RETURNING 1)
    SELECT count(*) INTO n FROM m;
  END IF;
  RETURN jsonb_build_object('run', p_run, 'reverted', n);
END $$;

-- The live enqueue rule on image_observations (refuter revert-race R-1).
CREATE FUNCTION public.trg_enqueue_vehicle_image_attribution() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.role = 'subject' AND NEW.vehicle_id IS NOT NULL AND NEW.confidence >= 0.85
     AND (NEW.is_active OR (TG_OP = 'UPDATE' AND OLD.is_active)) THEN
    INSERT INTO vehicle_image_attribution_queue(image_id) VALUES (NEW.image_id) ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_enqueue_vehicle_image_attribution AFTER INSERT OR UPDATE OF vehicle_id, confidence, is_active, role
  ON public.image_observations FOR EACH ROW EXECUTE FUNCTION public.trg_enqueue_vehicle_image_attribution();

-- derive_vehicle_image_attribution and its sweep: the live bodies (live-only functions, no migration holds them), as the design sim's stubs load them
CREATE OR REPLACE FUNCTION public.derive_vehicle_image_attribution(p_image_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_chosen_vehicle uuid;
  v_chosen_confidence numeric;
  v_chosen_observed_by text;
  v_current_vehicle uuid;
  v_human_override boolean;
BEGIN
  -- Pick the strongest active subject claim
  SELECT vehicle_id, confidence, observed_by
    INTO v_chosen_vehicle, v_chosen_confidence, v_chosen_observed_by
  FROM image_observations
  WHERE image_id = p_image_id
    AND role = 'subject'
    AND is_active = true
    AND vehicle_id IS NOT NULL
    AND confidence >= 0.85
  ORDER BY
    -- Humans always win
    CASE WHEN observed_by LIKE 'human:%' THEN 1 ELSE 0 END DESC,
    confidence DESC,
    observed_at DESC
  LIMIT 1;

  IF v_chosen_vehicle IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT vehicle_id INTO v_current_vehicle
  FROM vehicle_images
  WHERE id = p_image_id;

  -- Already correct → no-op
  IF v_current_vehicle IS NOT DISTINCT FROM v_chosen_vehicle THEN
    RETURN v_chosen_vehicle;
  END IF;

  -- Don't clobber a vehicle_id that came from a human in image_observations
  -- if our chosen claim isn't also a human claim.
  SELECT EXISTS (
    SELECT 1 FROM image_observations
    WHERE image_id = p_image_id
      AND role = 'subject'
      AND is_active = true
      AND vehicle_id = v_current_vehicle
      AND observed_by LIKE 'human:%'
  ) INTO v_human_override;

  IF v_human_override AND v_chosen_observed_by NOT LIKE 'human:%' THEN
    RETURN v_current_vehicle;
  END IF;

  -- Promote: write the chosen vehicle_id to vehicle_images
  UPDATE vehicle_images
  SET vehicle_id = v_chosen_vehicle,
      updated_at = now()
  WHERE id = p_image_id;

  RETURN v_chosen_vehicle;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.derive_vehicle_image_attribution_sweep(p_limit integer DEFAULT 2000)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_n int;
BEGIN
  INSERT INTO public.vehicle_image_attribution_queue (image_id)
  SELECT s.image_id
  FROM (
    SELECT DISTINCT io.image_id
    FROM public.image_observations io
    LEFT JOIN public.vehicle_images vi ON vi.id = io.image_id
    WHERE io.is_active = true
      AND io.role = 'subject'
      AND io.confidence >= 0.85
      AND io.vehicle_id IS NOT NULL
      AND (vi.vehicle_id IS NULL OR vi.vehicle_id IS DISTINCT FROM io.vehicle_id)
      -- No observed_at window on purpose (20260727190000, bug 1): a window orphans what an outage missed.
    ORDER BY io.image_id
    LIMIT p_limit
  ) s
  ON CONFLICT (image_id) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$function$
;
-- cron 499 stand-in: drain the queue through derive, one exception block per image like the live batch.
CREATE FUNCTION public.sim_cron_499() RETURNS int LANGUAGE plpgsql AS $$
DECLARE r record; n int := 0;
BEGIN
  FOR r IN DELETE FROM vehicle_image_attribution_queue RETURNING image_id LOOP
    BEGIN
      PERFORM public.derive_vehicle_image_attribution(r.image_id); n := n + 1;
    EXCEPTION WHEN unique_violation THEN NULL;            -- live batch: target already holds the hash; not retried
    END;
  END LOOP;
  RETURN n;
END $$;
-- merge_into_primary's effect on images and vehicles; it never touches image_observations (R-3), and (live rule) a
-- photo whose file_hash the primary already holds stays on the duplicate row.
CREATE FUNCTION public.sim_merge(p_from uuid, p_into uuid) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  UPDATE vehicle_images d SET merged_from_vehicle_id = p_from, vehicle_id = p_into      -- v4: live overwrites with dup_id
   WHERE d.vehicle_id = p_from
     AND NOT (d.file_hash IS NOT NULL AND NOT coalesce(d.is_superseded, false) AND EXISTS (SELECT 1 FROM vehicle_images p WHERE p.vehicle_id = p_into AND p.file_hash = d.file_hash
                                                     AND NOT coalesce(p.is_superseded, false)))
     -- merge_into_primary_batch (53252498): a hashless photo whose image_url the survivor already holds stays too
     AND NOT (d.file_hash IS NULL AND coalesce(d.image_url, '') <> '' AND EXISTS (SELECT 1 FROM vehicle_images p
                WHERE p.vehicle_id = p_into AND p.image_url = d.image_url AND NOT coalesce(p.is_superseded, false)));
  UPDATE vehicles SET merged_into_vehicle_id = p_into, deleted_at = now(), status = 'merged' WHERE id = p_from;
  INSERT INTO vehicle_merge_proposals(primary_vehicle_id, duplicate_vehicle_id, status) VALUES (p_into, p_from, 'merged')
  ON CONFLICT (primary_vehicle_id, duplicate_vehicle_id) DO UPDATE SET status = 'merged';
END $$;

-- v4: the image, vehicle and proposal parts of live unmerge_vehicle (it never touches image_observations).
CREATE FUNCTION public.sim_unmerge(p_primary uuid, p_dup uuid) RETURNS int LANGUAGE plpgsql AS $$
DECLARE n int;
BEGIN
  UPDATE vehicle_images SET vehicle_id = p_dup, merged_from_vehicle_id = NULL WHERE vehicle_id = p_primary AND merged_from_vehicle_id = p_dup;
  GET DIAGNOSTICS n = ROW_COUNT;
  UPDATE vehicles SET status = 'active', merged_into_vehicle_id = NULL, deleted_at = NULL WHERE id = p_dup;
  UPDATE vehicle_merge_proposals SET status = 'unmerged', unmerged_at = now() WHERE primary_vehicle_id = p_primary AND duplicate_vehicle_id = p_dup;
  RETURN n;
END $$;

-- v4: live public.execute_recovery_sql(text) is a postgres-owned SECURITY DEFINER function that runs caller SQL and is
-- executable by service_role (rules-violation v3, sql-apply v3). Stand-in with the same shape.
CREATE FUNCTION public.execute_recovery_sql(p_sql text) RETURNS TABLE(affected int) LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public AS $$
DECLARE n int;
BEGIN
  EXECUTE p_sql;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN QUERY SELECT n;
END $$;
REVOKE ALL ON FUNCTION public.execute_recovery_sql(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.execute_recovery_sql(text) TO service_role;
-- live attribute_image_session before M0 (body = live prosrc, md5 4dcd5577...), live ACL
ALTER TABLE public.work_sessions ADD COLUMN owner_confirmed_at timestamptz, ADD COLUMN owner_confirmed_by uuid, ADD COLUMN updated_at timestamptz;
CREATE FUNCTION public.attribute_image_session(p_image_ids uuid[], p_vehicle_id uuid, p_owner uuid DEFAULT NULL::uuid, p_reason text DEFAULT 'owner_session_confirm'::text)
 RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_owner uuid := COALESCE(auth.uid(), p_owner);
  r record;
  res jsonb;
  n int := 0;
BEGIN
  FOR r IN
    SELECT id, (taken_at)::date AS sday
    FROM vehicle_images
    WHERE id = ANY(p_image_ids)
      AND user_id = v_owner
      AND vehicle_id IS NULL
  LOOP
    res := attribute_testimony('image', r.id, p_vehicle_id, p_reason, v_owner, 1.0, 'owner_session_confirm');
    IF (res->>'success')::boolean THEN
      n := n + 1;
    ELSIF res->>'error' = 'file_hash_exists_on_target' THEN
      UPDATE vehicle_images SET is_duplicate = true, updated_at = now() WHERE id = r.id;
    END IF;
  END LOOP;

  -- Also auto-confirm any matching work_sessions rows for the dates covered by these images
  IF p_vehicle_id IS NOT NULL AND n > 0 THEN
    UPDATE public.work_sessions ws
       SET owner_confirmed_at = COALESCE(ws.owner_confirmed_at, now()),
           owner_confirmed_by = COALESCE(ws.owner_confirmed_by, v_owner),
           updated_at = now()
     WHERE ws.user_id = v_owner
       AND ws.vehicle_id = p_vehicle_id
       AND ws.owner_confirmed_at IS NULL
       AND ws.session_date IN (
         SELECT DISTINCT (vi.taken_at)::date
         FROM public.vehicle_images vi
         WHERE vi.id = ANY(p_image_ids)
           AND vi.taken_at IS NOT NULL
       );
  END IF;

  RETURN n;
END;
$function$;
REVOKE ALL ON FUNCTION public.attribute_image_session(uuid[],uuid,uuid,text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.attribute_image_session(uuid[],uuid,uuid,text) TO authenticated, service_role;
RESET SESSION AUTHORIZATION;
-- live event triggers (view_write_guard from 20261014214500, Supabase's ensure_rls), created by the superuser
CREATE OR REPLACE FUNCTION public.view_write_guard()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_views oid[];
  v_holes text;
BEGIN
  IF tg_tag = 'GRANT' THEN
    -- A GRANT names no object here. One on tables or views reads every view in public; others read none.
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_event_trigger_ddl_commands() d WHERE d.object_type = 'TABLE') THEN
      RETURN;
    END IF;
    SELECT pg_catalog.array_agg(c.oid) INTO v_views
      FROM pg_catalog.pg_class c
     WHERE c.relnamespace = 'public'::pg_catalog.regnamespace AND c.relkind = 'v';
  ELSE
    -- A rule is reported as itself; the view it belongs to is what changed. CREATE OR REPLACE reports a view twice.
    SELECT pg_catalog.array_agg(DISTINCT CASE WHEN d.classid = 'pg_catalog.pg_rewrite'::pg_catalog.regclass
                                              THEN (SELECT r.ev_class FROM pg_catalog.pg_rewrite r WHERE r.oid = d.objid)
                                              ELSE d.objid END)
      INTO v_views
      FROM pg_catalog.pg_event_trigger_ddl_commands() d
     WHERE d.classid IN ('pg_catalog.pg_class'::pg_catalog.regclass, 'pg_catalog.pg_rewrite'::pg_catalog.regclass);
  END IF;
  IF v_views IS NULL THEN
    RETURN;
  END IF;

  SELECT pg_catalog.string_agg(pg_catalog.format('public.%I', c.relname), ', ' ORDER BY c.relname)
    INTO v_holes
    FROM pg_catalog.unnest(v_views) t(oid)
    JOIN pg_catalog.pg_class c ON c.oid = t.oid
    JOIN pg_catalog.pg_roles o ON o.oid = c.relowner
   WHERE c.relnamespace = 'public'::pg_catalog.regnamespace
     AND c.relkind = 'v'
     AND c.relname <> 'geometry_columns'
     AND o.rolbypassrls
     AND NOT COALESCE((SELECT x.option_value::boolean FROM pg_catalog.pg_options_to_table(c.reloptions) x
                        WHERE x.option_name = 'security_invoker'), false)
     AND (pg_catalog.pg_relation_is_updatable(c.oid, false) & 28) > 0
     AND EXISTS (SELECT 1 FROM pg_catalog.unnest(ARRAY['anon', 'authenticated']) r(role)
                  WHERE pg_catalog.has_any_column_privilege(r.role, c.oid, 'INSERT')
                     OR pg_catalog.has_any_column_privilege(r.role, c.oid, 'UPDATE')
                     OR pg_catalog.has_table_privilege(r.role, c.oid, 'DELETE')
                     OR pg_catalog.has_table_privilege(r.role, c.oid, 'TRUNCATE'));

  IF v_holes IS NOT NULL THEN
    RAISE EXCEPTION 'view_write_guard: % leaves % writable by anon or authenticated while it runs as its owner, so a write through it skips row-level security', tg_tag, v_holes
      USING HINT = 'Create or replace the view WITH (security_invoker = true), or revoke INSERT, UPDATE, DELETE, TRUNCATE on it from anon and authenticated. supabase/migrations/20261014214500_view_write_guard.sql has the cases.';
  END IF;
END
$function$
;
CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
;
CREATE EVENT TRIGGER view_write_guard ON ddl_command_end WHEN TAG IN ('CREATE VIEW','ALTER VIEW','ALTER TABLE','CREATE RULE','GRANT') EXECUTE FUNCTION public.view_write_guard();
CREATE EVENT TRIGGER ensure_rls ON ddl_command_end WHEN TAG IN ('CREATE TABLE','CREATE TABLE AS','SELECT INTO') EXECUTE FUNCTION public.rls_auto_enable();


