-- scenario_v9.sql: one check per v9 change of block M1w (DESIGN-v9 "Changes from v8", V9-1 .. V9-20).
-- Written the way PR-1's contract test is: ON_ERROR_STOP on; every expectation is t_assert(<boolean>, label) or, after a
-- statement that must fail (run at top level between \set ON_ERROR_STOP off / on), t_refused(label, :'SQLSTATE',
-- :'LAST_ERROR_MESSAGE', <state>, <message LIKE>). A failed check stops the file with "FAIL: <label>".
-- Every id is generated here (gen_random_uuid()); every actor is a PostgREST-shaped session (session authorization
-- authenticator, SET ROLE, request.jwt.claims). Needs: stubs (or the contract's live-shaped existing tables), M1a, M1w.
-- The owner sessions carry a session id; the sim's auth stand-ins accept any session, the contract seeds auth.sessions,
-- auth.mfa_factors and auth.mfa_amr_claims for :SA and :SB (a 30-day-old verified totp factor, verified now).
\set ON_ERROR_STOP on
\pset pager off
\pset format unaligned
\pset tuples_only on
SET client_min_messages = notice;
\set VERBOSITY terse
RESET ROLE; RESET SESSION AUTHORIZATION;
-- (scenario_v9.sql defines t_assert and t_refused here; the template's, with the same signatures, are used)

-- ------------------------------------------------------------------------------------------------ actors and fixtures
SELECT replace(gen_random_uuid()::text, '-', '') AS tag \gset
SELECT gen_random_uuid() AS ua, gen_random_uuid() AS ub, gen_random_uuid() AS sa, gen_random_uuid() AS sb,
       gen_random_uuid() AS va, gen_random_uuid() AS vb2, gen_random_uuid() AS v1, gen_random_uuid() AS v3, gen_random_uuid() AS vbb \gset
SELECT auth.t_seed_session(:'sa', :'ua'), auth.t_seed_session(:'sb', :'ub');
\set JOB 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE service_role; SET request.jwt.claim.role = ''service_role''; RESET request.jwt.claim.sub; SET request.jwt.claims = ''{"role":"service_role"}'';'
\set OWNER 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; SET request.jwt.claim.sub = ''' :ua '''; SET request.jwt.claims = ''{"sub":"' :ua '","role":"authenticated","aal":"aal2","session_id":"' :sa '","amr":[{"method":"totp","timestamp":1700000100}]}'';'
\set NOSUB 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; RESET request.jwt.claim.sub; SET request.jwt.claims = ''{"role":"authenticated","aal":"aal2"}'';'
\set ADMIN 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET request.jwt.claim.role; RESET request.jwt.claim.sub; RESET request.jwt.claims;'
:ADMIN
INSERT INTO public.profiles(id) VALUES (:'ua'), (:'ub');
INSERT INTO public.vehicles(id, owner_id) VALUES (:'va', :'ua'), (:'vb2', :'ua'), (:'v1', :'ua'), (:'v3', :'ua'), (:'vbb', :'ub');
-- twelve photos of his, each on its own day in May 2024, none filed
INSERT INTO public.vehicle_images(id, vehicle_id, user_id, taken_at)
SELECT gen_random_uuid(), NULL, :'ua', ('2024-05-' || lpad(g::text, 2, '0') || ' 18:00+00')::timestamptz FROM generate_series(1, 12) g;
SELECT (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-05-01 18:00+00') AS i1,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-05-02 18:00+00') AS i2,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-05-03 18:00+00') AS i3,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-05-04 18:00+00') AS i4,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-05-05 18:00+00') AS i5,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-05-06 18:00+00') AS i6,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-05-07 18:00+00') AS i7,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-05-08 18:00+00') AS i8,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-05-09 18:00+00') AS i9 \gset
:JOB
SELECT public.evidence_open_run(:'ua','pilot','loop','script:v9','sha','{}') AS loop \gset
SELECT public.evidence_open_run(:'ua','pilot','combined','script:v9','sha','{}','{}',NULL,NULL,:'loop') AS rc \gset
SELECT public.evidence_open_run(:'ua','pilot','photos_album','script:v9','sha','{}','{}',NULL,NULL,:'loop') AS ralb \gset
SELECT public.evidence_open_run(:'ua','pilot','deal_document','script:v9','sha','{}') AS rd \gset
SELECT public.evidence_open_run(:'ua','pilot','ledger_vendor_date','script:v9','sha','{"coverage_to":"2025-12-31","covers_accounts":["bank_account:v9.main"]}') AS rl \gset
SELECT public.evidence_open_run(:'ua','pilot','account_map','script:v9','sha','{}') AS rm \gset

-- ------------------------------------------------------------------------------------------------ V9-1 (W1)
-- The Photos join dates I1; he rejects that instant; a batch-offset claim replaces it; the next Photos join proposes
-- the rejected instant again.
SELECT public.evidence_open_run(:'ua','pilot','photos_join','script:v9','sha','{}') AS rpj \gset
SELECT public.evidence_open_run(:'ua','pilot','time_offset','script:v9','sha','{}') AS rto \gset
\set PJ '[{"image_id":"' :i1 '","stored_taken_at":"2024-05-01 18:00+00","corrected_taken_at":"2024-05-01 14:00+00","offset_seconds":14400,"local_offset_minutes":-420,"captured_on":"2024-05-01","rule":"photos_exif_join","witness":{"unique_match":true},"confidence":0.99}]'
SELECT public.propose_capture_time_claims(:'rpj', :'PJ'::jsonb)->>'machine_confirmed' AS w1_conf \gset
SELECT id AS w1_claim FROM public.image_capture_time_claims WHERE image_id = :'i1' AND superseded_by IS NULL \gset
:OWNER
SELECT public.decide_evidence('capture_time_claim', ARRAY[:'w1_claim']::uuid[], 'rejected', 'not that day', 'app:v9-1', 'owner_app')->'items'->0->>'result' AS w1_no \gset
:JOB
SELECT public.propose_capture_time_claims(:'rto', ('[{"image_id":"' || :'i1' || '","stored_taken_at":"2024-05-01 18:00+00","corrected_taken_at":"2024-04-30 18:00+00","offset_seconds":86400,"captured_on":"2024-04-30","rule":"batch_offset_v1","batch_key":"b1","witness":{},"confidence":0.5}]')::jsonb)->>'proposed' AS w1_bo \gset
SELECT public.propose_capture_time_claims(:'rpj', :'PJ'::jsonb) AS w1_again \gset
SELECT t_assert(:'w1_conf' = '1' AND :'w1_no' = 'rejected' AND :'w1_bo' = '1'
                AND (:'w1_again'::jsonb->>'already_rejected') = '1' AND (:'w1_again'::jsonb->>'machine_confirmed') = '0'
                AND (:'w1_again'::jsonb->>'proposed') = '0',
  'V9-1 W1: the instant he rejected, proposed again after another claim replaced it, is already_rejected and never machine-confirmed');
SELECT t_assert((SELECT captured_on IS NULL AND time_unverified FROM public.evidence_candidates_for_images(ARRAY[:'i1']::uuid[], :'ua') LIMIT 1) IS NOT FALSE
                AND NOT EXISTS (SELECT 1 FROM public.image_capture_time_claims t JOIN public.evidence_decisions d ON d.target_id = t.id
                                 WHERE t.image_id = :'i1' AND t.superseded_by IS NULL AND d.decision = 'confirmed'),
  'V9-1 W1: no current claim of that photo is confirmed after the loop');

-- ------------------------------------------------------------------------------------------------ V9-2..V9-7 (W2)
SELECT public.propose_image_candidates(:'rc', ('[' ||
  '{"image_id":"' || :'i2' || '","vehicle_id":"' || :'va' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-05-02"},' ||
  '{"image_id":"' || :'i3' || '","vehicle_id":"' || :'va' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-05-03"},' ||
  '{"image_id":"' || :'i4' || '","vehicle_id":"' || :'va' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-05-04"}]')::jsonb)->>'proposed' AS w2_prop \gset
SELECT (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'i2' AND superseded_by IS NULL) AS c2,
       (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'i3' AND superseded_by IS NULL) AS c3,
       (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'i4' AND superseded_by IS NULL) AS c4 \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-s1','items',3,'rows',jsonb_build_object(
  '1', jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','image_candidate','id',:'c2'))),
  '2', jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','image_candidate','id',:'c3'))),
  '3', jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','image_candidate','id',:'c4')))))) AS s1 \gset
\set ON_ERROR_STOP off
SELECT public.evidence_record_answers(:'ua', :'s1', 'v9:m0-' || :'tag', '{"1":{"verbatim":"yes"}}'::jsonb, 'script:v9', 'sha', clock_timestamp());
\set ON_ERROR_STOP on
SELECT t_refused('V9-3 W2/M2: no answer is stored on a sheet that was never sent (running)', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'sheet_not_sent:%');
SELECT public.evidence_close_run(:'s1', 'done', '{"sent":true}'::jsonb);
SELECT pg_sleep(0.02);
SELECT clock_timestamp() AS m1_at \gset
SELECT public.evidence_record_answers(:'ua', :'s1', 'v9:m1-' || :'tag', '{"1":{"verbatim":"1 yes","answer":{"decision":"confirmed"}}}'::jsonb, 'script:v9', 'sha', :'m1_at') AS a1 \gset
-- between his messages a pass re-writes row 2's candidate with another meaning (a listing photo)
SELECT public.propose_image_candidates(:'rc', ('[{"image_id":"' || :'i3' || '","vehicle_id":"' || :'va' || '","verdict":"listing_evidence","image_class":"listing","join_key":"x","confidence":0.7,"evidence":[{"kind":"y"}],"pass_captured_on":"2024-05-03"}]')::jsonb)->'items'->0->>'result' AS w2_rw \gset
SELECT id AS c3b FROM public.image_vehicle_candidates WHERE image_id = :'i3' AND superseded_by IS NULL \gset
SELECT clock_timestamp() AS m2_at \gset
SELECT public.evidence_record_answers(:'ua', :'s1', 'v9:m2-' || :'tag', '{"2":{"verbatim":"2 yes thats it","answer":{"decision":"confirmed"}},"3":{"verbatim":"3 yes","answer":{"decision":"confirmed"}}}'::jsonb,
  'script:v9', 'sha', :'m2_at') AS a2 \gset
SELECT t_assert((SELECT count(*) FROM public.evidence_runs WHERE run_kind = 'review_answers' AND config->>'sheet_run' = :'s1') = 2
                AND (SELECT config->>'message_at' IS NOT NULL FROM public.evidence_runs WHERE id = :'a2'),
  'V9-2 W2: a reply in two chat messages is stored, message by message, on the sheet he was sent');
-- the runner's old retry: a copy sheet of row 2 as the passes have it now
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-copy','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','image_candidate','id',:'c3b')))))) AS scopy \gset
\set ON_ERROR_STOP off
SELECT public.evidence_record_answers(:'ua', :'scopy', 'v9:m2x-' || :'tag', '{"1":{"verbatim":"2 yes thats it","answer":{"decision":"confirmed"}}}'::jsonb, 'script:v9', 'sha', :'m2_at');
\set ON_ERROR_STOP on
SELECT t_refused('V9-3 W2: a copy sheet never sent takes no answer', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'sheet_not_sent:%');
SELECT public.evidence_close_run(:'scopy', 'done', '{}'::jsonb);
\set ON_ERROR_STOP off
SELECT public.evidence_record_answers(:'ua', :'scopy', 'v9:m2y-' || :'tag', '{"1":{"verbatim":"2 yes thats it","answer":{"decision":"confirmed"}}}'::jsonb, 'script:v9', 'sha', :'m2_at');
\set ON_ERROR_STOP on
SELECT t_refused('V9-4 W2: a sheet sent after his message cannot carry it (message_predates_sheet)', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'message_predates_sheet:%');
\set ON_ERROR_STOP off
SELECT public.evidence_record_answers(:'ua', :'s1', 'v9:m9-' || :'tag', '{"1":{"verbatim":"later"}}'::jsonb, 'script:v9', 'sha', clock_timestamp() + interval '1 hour');
\set ON_ERROR_STOP on
SELECT t_refused('V9-4 W2: a message time in the future is refused', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'message time % is in the future');
:OWNER
SELECT public.decide_evidence('image_candidate', ARRAY[:'c3b']::uuid[], 'confirmed', 'confirm what I said', 'review:' || :'s1' || '#2', 'owner_app',
  NULL, jsonb_build_object(:'c3b', NULL), NULL, NULL, 'answers:' || :'a2' || '#2')->'items'->0 AS w2_changed \gset
SELECT public.decide_evidence('image_candidate', ARRAY[:'c4']::uuid[], 'confirmed', 'confirm what I said', 'review:' || :'s1' || '#1', 'owner_app',
  NULL, jsonb_build_object(:'c4', NULL), NULL, NULL, 'answers:' || :'a1' || '#1')->'items'->0->>'result' AS w2_other \gset
SELECT public.decide_evidence('image_candidate', ARRAY[:'c2']::uuid[], 'confirmed', 'confirm what I said', 'review:' || :'s1' || '#1', 'owner_app',
  NULL, jsonb_build_object(:'c2', NULL), NULL, NULL, 'answers:' || :'a1' || '#1')->'items'->0->>'result' AS w2_own \gset
SELECT t_assert((:'w2_changed'::jsonb->>'result') = 'row_changed_since_answer' AND (:'w2_changed'::jsonb->>'asked_target') = :'c3',
  'V9-5 W2: his confirm citing his answer lands on no row re-written with another meaning (row_changed_since_answer, asked_target)');
SELECT t_assert(:'w2_other' = 'not_on_answered_row', 'V9-5 W2: his answer to one row is not confirmed on a target of another row (not_on_answered_row)');
SELECT t_assert(:'w2_own' = 'confirmed', 'V9-5 W2: his answer confirms the row''s own target');
SELECT t_assert((SELECT count(*) FROM public.evidence_decisions WHERE target_id IN (:'c3b', :'c4')) = 0,
  'V9-5 W2: nothing was written for the refused targets');
-- V9-6: a later message answering the same row replaces the earlier answer
:JOB
SELECT clock_timestamp() AS m3_at \gset
SELECT public.evidence_record_answers(:'ua', :'s1', 'v9:m3-' || :'tag', '{"3":{"verbatim":"3 no wait","answer":{"decision":"rejected"}}}'::jsonb, 'script:v9', 'sha', :'m3_at') AS a3 \gset
:OWNER
\set ON_ERROR_STOP off
SELECT public.decide_evidence('image_candidate', ARRAY[:'c4']::uuid[], 'confirmed', 'confirm what I said', 'review:' || :'s1' || '#3', 'owner_app',
  NULL, jsonb_build_object(:'c4', NULL), NULL, NULL, 'answers:' || :'a2' || '#3');
\set ON_ERROR_STOP on
SELECT t_refused('V9-6 W2: an answer a later message of his replaced is not cited', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'a later message of yours answers that row: answers:%');
SELECT public.decide_evidence('image_candidate', ARRAY[:'c4']::uuid[], 'rejected', 'as I said', 'review:' || :'s1' || '#3', 'owner_app',
  NULL, jsonb_build_object(:'c4', NULL), NULL, NULL, 'answers:' || :'a3' || '#3')->'items'->0->>'result' AS w2_latest \gset
SELECT t_assert(:'w2_latest' = 'rejected', 'V9-6 W2: his latest answer to the row is the one cited');
SELECT t_assert((SELECT count(*) FROM public.evidence_answers_to_confirm() WHERE sheet_run = :'s1' AND row_no = 3) = 2
                AND (SELECT bool_and(message_at IS NOT NULL) FROM public.evidence_answers_to_confirm()),
  'V9-6 W2: the advisory list shows both answers to row 3 with their message times');
-- V9-7: a re-ask copies the row as it was frozen
:JOB
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-reask','items',1,'rows',
  jsonb_build_object('1', jsonb_build_object('reask_of', 'review:' || :'s1' || '#2')))) AS sre \gset
SELECT t_assert((SELECT config->'rows'->'1'->'targets' = jsonb_build_array(jsonb_build_object('kind','image_candidate','id',:'c3'))
                        AND config->'rows'->'1'->>'reask_of' = 'review:' || :'s1' || '#2' AND config->'rows'->'1'->>'question' = 'image_candidate'
                   FROM public.evidence_runs WHERE id = :'sre'),
  'V9-7 W2: a re-ask row carries the original frozen target (not the re-written row)');
SELECT public.evidence_close_run(:'sre', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'sre', 'v9:m4-' || :'tag', '{"1":{"verbatim":"yes","answer":{"decision":"confirmed"}}}'::jsonb, 'script:v9', 'sha', clock_timestamp()) AS a4 \gset
:OWNER
SELECT public.decide_evidence('image_candidate', ARRAY[:'c3b']::uuid[], 'confirmed', 'confirm what I said', 'review:' || :'sre' || '#1', 'owner_app',
  NULL, jsonb_build_object(:'c3b', NULL), NULL, NULL, 'answers:' || :'a4' || '#1')->'items'->0->>'result' AS w2_reask \gset
SELECT t_assert(:'w2_reask' = 'row_changed_since_answer', 'V9-7 W2: his answer to the re-ask is checked against the row he was first asked about');
:JOB
\set ON_ERROR_STOP off
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-reask2','items',1,'rows',
  jsonb_build_object('1', jsonb_build_object('reask_of', 'review:' || :'s1' || '#2', 'targets', jsonb_build_array(jsonb_build_object('kind','image_candidate','id',:'c3b'))))));
\set ON_ERROR_STOP on
SELECT t_refused('V9-7 W2: a re-ask with other targets than the original row is refused', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'sheet row 1: a re-ask asks the original row unchanged%');
\set ON_ERROR_STOP off
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-reask3','items',1,'rows',
  jsonb_build_object('1', jsonb_build_object('reask_of', 'review:' || :'scopy' || '#7'))));
\set ON_ERROR_STOP on
SELECT t_refused('V9-7 W2: a re-ask of a row that does not exist is refused', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'sheet row 1: reask_of names no row%');

-- V9-5b: a row that names a slot (an account by its key), re-proposed with another meaning after the sheet was sent
SELECT public.propose_account_entities(:'rm', '[{"account_ref":"bank_account:v9.slot","entity_key":"owner","confidence":0.6,"evidence":[{"kind":"x"}]},{"account_ref":"bank_account:v9.slot2","entity_key":"owner","confidence":0.6,"evidence":[{"kind":"x"}]}]'::jsonb)->'ids' AS slot_ids \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-slot','items',2,'rows',jsonb_build_object(
  '1', jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','account','key','bank_account:v9.slot'))),
  '2', jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','account','key','bank_account:v9.slot2')))))) AS sslot \gset
SELECT public.evidence_close_run(:'sslot', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'sslot', 'v9:slot-' || :'tag', '{"1":{"verbatim":"thats my own account"},"2":{"verbatim":"mine too"}}'::jsonb, 'script:v9', 'sha', clock_timestamp()) AS aslot \gset
SELECT public.propose_account_entities(:'rm', '[{"account_ref":"bank_account:v9.slot","entity_key":"owner_business:shop","confidence":0.9,"evidence":[{"kind":"y"}]}]'::jsonb)->'ids'->>0 AS slot_new \gset
:OWNER
SELECT public.decide_evidence('account_entity', ARRAY[:'slot_new']::uuid[], 'confirmed', 'as I said', 'review:' || :'sslot' || '#1', 'owner_app',
  NULL, NULL, NULL, NULL, 'answers:' || :'aslot' || '#1')->'items'->0 AS slot_r1 \gset
SELECT public.decide_evidence('account_entity', ARRAY[(:'slot_ids'::jsonb->>1)::uuid], 'confirmed', 'as I said', 'review:' || :'sslot' || '#2', 'owner_app',
  NULL, NULL, NULL, NULL, 'answers:' || :'aslot' || '#2')->'items'->0->>'result' AS slot_r2 \gset
SELECT t_assert((:'slot_r1'::jsonb->>'result') = 'row_changed_since_answer' AND (:'slot_r1'::jsonb->>'asked_target') = (:'slot_ids'::jsonb->>0),
  'V9-5 W2: on a row that names a slot, a row the passes re-wrote with another meaning after the sheet was sent is not his answer');
SELECT t_assert(:'slot_r2' = 'confirmed', 'V9-5 W2: the slot''s row as it was when the sheet was sent is');
:JOB

-- ------------------------------------------------------------------------------------------------ V9-8 (M1, M3, M4, M8)
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-m','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','image_candidate','id',:'c2')))))) AS sm \gset
SELECT public.evidence_close_run(:'sm', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
\set ON_ERROR_STOP off
SELECT public.evidence_record_answers(:'ua', :'sm', 'v9:m-empty-' || :'tag', '{}'::jsonb, 'script:v9', 'sha', clock_timestamp());
\set ON_ERROR_STOP on
SELECT t_refused('V9-8 M1: an answer set with no row is refused', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'a stored answer has at least one row');
\set ON_ERROR_STOP off
SELECT public.evidence_record_answers(:'ua', :'sm', 'v9:m-big-' || :'tag', jsonb_build_object('1', jsonb_build_object('verbatim', repeat('a', 20001))), 'script:v9', 'sha', clock_timestamp());
\set ON_ERROR_STOP on
SELECT t_refused('V9-8 M4: more than 20000 characters of his words on one row is refused', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'answer row 1: at most 20000 characters%');
-- another user's sheet and message
:ADMIN
SELECT gen_random_uuid() AS ib1 \gset
INSERT INTO public.vehicle_images(id, vehicle_id, user_id, taken_at) VALUES (:'ib1', :'vbb', :'ub', '2024-05-09 18:00+00');
:JOB
SELECT public.evidence_open_run(:'ub','pilot','combined','script:v9','sha','{}') AS rcb \gset
SELECT public.propose_image_candidates(:'rcb', ('[{"image_id":"' || :'ib1' || '","vehicle_id":"' || :'vbb' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}]}]')::jsonb)->'items'->0->>'candidate_id' AS cbb \gset
SELECT public.evidence_open_run(:'ub','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-b','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','image_candidate','id',:'cbb')))))) AS sbb \gset
SELECT public.evidence_close_run(:'sbb', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ub', :'sbb', 'v9b:shared-7-' || :'tag', '{"1":{"verbatim":"ok"}}'::jsonb, 'script:v9', 'sha', clock_timestamp()) AS abb \gset
\set ON_ERROR_STOP off
SELECT public.evidence_record_answers(:'ua', :'sm', 'v9:shared-7-' || :'tag', '{"1":{"verbatim":"yes"}}'::jsonb, 'script:v9', 'sha', clock_timestamp());
\set ON_ERROR_STOP on
SELECT t_refused('V9-8 M3: a message id stored once, for any user, is refused again', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '23505', 'message v9:shared-7-% is already stored; a message is stored once');
SELECT t_assert(position(:'abb' in :'LAST_ERROR_MESSAGE') = 0, 'V9-8 M3: the refusal names no stored run (it is another user''s)');
\set ON_ERROR_STOP off
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-huge','items',51,'rows',
  (SELECT jsonb_object_agg(r::text, jsonb_build_object('targets', (SELECT jsonb_agg(jsonb_build_object('kind','image_candidate','id',
      CASE WHEN t = 1 THEN :'c2' ELSE gen_random_uuid()::text END)) FROM generate_series(1, 197) t))) FROM generate_series(1, 51) r)));
\set ON_ERROR_STOP on
SELECT t_refused('V9-8 M8: a sheet of more than 10000 targets is refused before its rows are read', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'a review sheet lists at most 10000 targets in all; split it');

-- ------------------------------------------------------------------------------------------------ V9-9..V9-10 (W3)
SELECT public.propose_evidence_links(:'rl', ('[{"vehicle_id":"' || :'va' || '","source_kind":"bank_line","external_ref":"bank:v9-0301","occurred_on":"2024-03-01","direction":"out","amount_cents":4500,"role":"payment_out","cost_category":"parts","join_key":"x","confidence":0.9,"evidence":[{"kind":"bank"}]}]')::jsonb)->'items'->0->>'link_id' AS lk \gset
SELECT public.propose_evidence_links(:'rl', ('[{"vehicle_id":"' || :'va' || '","source_kind":"ledger_line","external_ref":"ledger:v9-77","occurred_on":"2024-03-02","direction":"out","amount_cents":7000,"role":"payment_out","cost_category":"parts","join_key":"x","confidence":0.9,"evidence":[{"kind":"ledger"}]}]')::jsonb)->'items'->0->>'link_id' AS ll \gset
\set ON_ERROR_STOP off
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-wp1','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','evidence_link','id',:'lk'))))));
\set ON_ERROR_STOP on
SELECT t_refused('V9-9 W3: a who-paid row on a bank line with no key is refused', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'sheet row 1: this money is a payment source line%');
\set ON_ERROR_STOP off
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-wp2','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','evidence_link','id',:'ll'))))));
\set ON_ERROR_STOP on
SELECT t_refused('V9-9 W3: a who-paid row on a ledger line with no key is refused', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'sheet row 1: this money is a payment source line%');
-- his statement on an acquisition claim, then the purchase's bank line placed on the truck (no support row)
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'va','claim_domain','custody','kind','acquisition','occurred_from','2024-01-18',
  'occurred_to','2024-01-18','amount_cents',800000,'summary','bought','confidence',0.8), '[]'::jsonb) AS kacq \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-wp3','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','change_claim','id',:'kacq')))))) AS swp \gset
SELECT public.evidence_close_run(:'swp', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'swp', 'v9:wp-' || :'tag', '{"1":{"verbatim":"I paid it myself","answer":{"decision":"confirmed","entity_key":"owner"}}}'::jsonb, 'script:v9', 'sha', clock_timestamp()) AS awp \gset
:OWNER
SELECT public.decide_evidence('change_claim', ARRAY[:'kacq']::uuid[], 'confirmed', 'I paid', 'review:' || :'swp' || '#1', 'owner_app', NULL, NULL, NULL, NULL,
  'answers:' || :'awp' || '#1', '{"entity_key":"owner"}'::jsonb)->'items'->0 AS wp1 \gset
-- (v10: the lead's money decision) a statement is listed under 'stated', never summed
SELECT t_assert((:'wp1'::jsonb->>'result') = 'statement_recorded'
                AND NOT (public.vehicle_accounting_evidence(:'va')->'costs' ? 'confirmed')
                AND jsonb_array_length(public.vehicle_accounting_evidence(:'va')->'stated'->'statements') = 1
                AND (public.vehicle_accounting_evidence(:'va')->'stated'->'statements'->0->>'cents')::bigint = 800000
                AND NOT (public.vehicle_accounting_evidence(:'va')->'stated' ? 'cents_out'),
  'V9-10 W3 (v11 rule): his statement alone is listed under stated, never summed, never totalled');
:JOB
SELECT public.propose_evidence_links(:'rl', ('[{"vehicle_id":"' || :'va' || '","source_kind":"bank_line","external_ref":"bank:v9-0118","occurred_on":"2024-01-18","direction":"out","amount_cents":800000,"role":"payment_out","payment_key":"bank:v9-0118","cost_category":"purchase","from_account_ref":"bank_account:v9.main","join_key":"x","confidence":0.92,"evidence":[{"kind":"bank"}]}]')::jsonb)->'items'->0->>'link_id' AS lb \gset
:OWNER
SELECT public.vehicle_accounting_evidence(:'va') AS vae_b \gset
SELECT t_assert((:'vae_b'::jsonb->'stated'->'statements'->0->>'payment_key') LIKE 'owner:answers:%'
                AND (:'vae_b'::jsonb->'stated'->'statements'->0->>'cents')::bigint = 800000
                AND (:'vae_b'::jsonb->'stated'->'statements'->0->>'payer') = 'owner'
                AND (:'vae_b'::jsonb->'stated'->'statements'->0->>'covered_cents')::bigint = 800000
                AND NOT (:'vae_b'::jsonb->'costs' ? 'confirmed') AND NOT (:'vae_b'::jsonb->'costs' ? 'stated'),
  'V9-10 W3 (v10 rule): the keyed bank line of the same money is summed; his statement is listed with its payer, covered by it');
SELECT t_assert((SELECT sum((v->>'cents')::bigint) FROM jsonb_each(:'vae_b'::jsonb->'costs') x(k, v) WHERE k IN ('confirmed','high','med','low'))
                = 800000,
  'V9-10 W3: the purchase is summed once (the bank line); the statement is not summed (the keyless parts lines are listed, never summed)');
SELECT t_assert(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(:'vae_b'::jsonb->'open_questions') q WHERE q->>'q' = 'who_paid'),
  'V9-10 W3: his statement still closes who_paid');
:JOB
SELECT public.propose_claim_support(:'rd', :'kacq', jsonb_build_array(jsonb_build_object('evidence_kind','evidence_link','evidence_id',:'lb','stance','supports','about','amount'))) AS sup_n \gset
:OWNER
SELECT t_assert((SELECT sum((v->>'cents')::bigint) FROM jsonb_each(public.vehicle_accounting_evidence(:'va')->'costs') x(k, v) WHERE k IN ('confirmed','high','med','low'))
                = 800000
                AND jsonb_array_length(public.vehicle_accounting_evidence(:'va')->'stated'->'statements') = 1,
  'V9-10 W3: with the bank line also supporting the claim, still summed once');
SELECT public.decide_evidence('evidence_link', ARRAY[:'lb']::uuid[], 'rejected', 'that line is another truck', 'app:v9-10', 'owner_app')->'items'->0->>'result' AS lb_no \gset
SELECT t_assert(:'lb_no' = 'rejected'
                AND coalesce((SELECT sum((v->>'cents')::bigint) FROM jsonb_each(public.vehicle_accounting_evidence(:'va')->'costs') x(k, v)
                               WHERE k IN ('confirmed','high','med','low')), 0) = 0
                AND (public.vehicle_accounting_evidence(:'va')->'stated'->'statements'->0->>'covered_cents')::bigint = 0,
  'V9-10 W3 (v10 rule): a keyed payment he rejected covers nothing and is not summed; his statement stays listed, unsummed');

-- ------------------------------------------------------------------------------------------------ V9-11..V9-12 (W4, M7)
:JOB
\set ON_ERROR_STOP off
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'va','claim_domain','custody','kind','acquisition','occurred_from','2024-01-18',
  'occurred_to','2024-01-18','amount_cents',800000,'summary','bought (bill of sale p.2)','confidence',0.9), '[]'::jsonb, :'kacq');
\set ON_ERROR_STOP on
SELECT t_refused('V9-11 W4: a pass may not supersede the claim his who-paid statement answers', :'SQLSTATE', :'LAST_ERROR_MESSAGE', 'P0001', 'claim % carries an owner decision (his decision or his who-paid statement)%');
SELECT t_assert((SELECT superseded_by IS NULL FROM public.vehicle_change_claims WHERE id = :'kacq')
                AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(public.vehicle_accounting_evidence(:'va', NULL, NULL, :'ua')->'open_questions') q WHERE q->>'q' = 'who_paid'),
  'V9-11 W4: the claim stays current and who_paid stays closed');
-- the chain: a sale claim re-written (same meaning) BEFORE his statement; his statement on the successor; a later
-- sheet asks who received on the successor and he answers again: one current statement
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'va','claim_domain','custody','kind','sale','occurred_from','2025-02-04',
  'occurred_to','2025-02-04','amount_cents',1500000,'summary','sold','confidence',0.7), '[]'::jsonb) AS ks1 \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-wr1','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','change_claim','id',:'ks1')))))) AS swr1 \gset
SELECT public.evidence_close_run(:'swr1', 'done', '{}'::jsonb);
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'va','claim_domain','custody','kind','sale','occurred_from','2025-02-04',
  'occurred_to','2025-02-04','amount_cents',1500000,'summary','sold','confidence',0.8), '[]'::jsonb, :'ks1') AS ks2 \gset
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'swr1', 'v9:wr1-' || :'tag', '{"1":{"verbatim":"the shop got it","answer":{"decision":"confirmed","entity_key":"owner_business:shop"}}}'::jsonb, 'script:v9', 'sha', clock_timestamp()) AS awr1 \gset
:OWNER
SELECT public.decide_evidence('change_claim', ARRAY[:'ks2']::uuid[], 'confirmed', 'shop', 'review:' || :'swr1' || '#1', 'owner_app', NULL, NULL, NULL, NULL,
  'answers:' || :'awr1' || '#1', '{"entity_key":"owner_business:shop"}'::jsonb)->'items'->0 AS wr1 \gset
:JOB
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v9','sha', jsonb_build_object('sheet_sha256','v9-wr2','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','change_claim','id',:'ks2')))))) AS swr2 \gset
SELECT public.evidence_close_run(:'swr2', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'swr2', 'v9:wr2-' || :'tag', '{"1":{"verbatim":"the shop, like I said","answer":{"decision":"confirmed","entity_key":"owner_business:shop"}}}'::jsonb, 'script:v9', 'sha', clock_timestamp()) AS awr2 \gset
:OWNER
SELECT public.decide_evidence('change_claim', ARRAY[:'ks2']::uuid[], 'confirmed', 'shop', 'review:' || :'swr2' || '#1', 'owner_app', NULL, NULL, NULL, NULL,
  'answers:' || :'awr2' || '#1', '{"entity_key":"owner_business:shop"}'::jsonb)->'items'->0 AS wr2 \gset
SELECT t_assert((:'wr1'::jsonb->>'result') = 'statement_recorded' AND (:'wr2'::jsonb->>'result') = 'statement_recorded'
                AND (:'wr2'::jsonb->'superseded_statement_ids') = jsonb_build_array(:'wr1'::jsonb->>'statement_link_id')
                AND (SELECT count(*) FROM public.evidence_links WHERE user_id = :'ua' AND source_kind = 'owner_statement' AND superseded_by IS NULL
                       AND evidence @> jsonb_build_array(jsonb_build_object('kind','claim','id',:'ks2'))) = 1,
  'V9-11 W4: his newer statement supersedes the one answering the row the claim was re-written from (one current statement)');
:JOB
SELECT public.evidence_open_run(:'ub','pilot','deal_document','script:v9','sha','{}') AS rdb \gset
SELECT public.propose_change_claim(:'rdb', jsonb_build_object('vehicle_id',:'vbb','claim_domain','custody','kind','acquisition','occurred_from','2024-02-01',
  'summary','b bought','confidence',0.8), '[]'::jsonb) AS kb \gset
\set ON_ERROR_STOP off
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'va','claim_domain','custody','kind','acquisition','occurred_from','2024-01-18',
  'summary','a bought','confidence',0.5), '[]'::jsonb, :'kb');
\set ON_ERROR_STOP on
SELECT t_refused('V9-12 M7: p_supersedes naming another user''s claim is refused', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'claim % is not a current claim of this user%');
SELECT t_assert((SELECT superseded_by IS NULL FROM public.vehicle_change_claims WHERE id = :'kb')
                AND NOT EXISTS (SELECT 1 FROM public.vehicle_change_claims WHERE supersedes = :'kb'),
  'V9-12 M7: the other user''s claim is untouched and nothing records it as replaced');

-- ------------------------------------------------------------------------------------------------ V9-13 (R-T1)
SELECT public.propose_evidence_links(:'ralb', ('[{"vehicle_id":"' || :'va' || '","source_kind":"photos_album","external_ref":"photos_album:V9ALBUM","role":"context","join_key":"album name","confidence":0.9,"evidence":[{"kind":"photos_album","ref":"V9ALBUM"}]}]')::jsonb)->'items'->0->>'link_id' AS alb \gset
SELECT public.propose_image_candidates(:'rc', ('[' ||
  '{"image_id":"' || :'i5' || '","vehicle_id":"' || :'va' || '","verdict":"is_vehicle","join_key":"x","confidence":0.6,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-05-05"},' ||
  '{"image_id":"' || :'i5' || '","vehicle_id":"' || :'vb2' || '","verdict":"is_vehicle","join_key":"x","confidence":0.5,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-05-05"},' ||
  '{"image_id":"' || :'i6' || '","vehicle_id":"' || :'vb2' || '","verdict":"is_vehicle","join_key":"x","confidence":0.5,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-05-06"}]')::jsonb)->>'proposed' AS t1p \gset
SELECT (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'i5' AND vehicle_id = :'vb2' AND superseded_by IS NULL) AS c5b,
       (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'i6' AND vehicle_id = :'vb2' AND superseded_by IS NULL) AS c6b \gset
:OWNER
SELECT public.decide_evidence('album_map', ARRAY[:'alb']::uuid[], 'confirmed', 'that album is truck A', 'app:v9-13', 'owner_app')->'items'->0->>'result' AS alb_ok \gset
SELECT public.decide_evidence('image_candidate', ARRAY[:'c5b']::uuid[], 'confirmed', 'truck two', 'app:v9-13a', 'owner_app', NULL, jsonb_build_object(:'c5b', NULL))->'items'->0->>'result' AS t1a \gset
SELECT public.decide_evidence('image_candidate', ARRAY[:'c6b']::uuid[], 'confirmed', 'truck two', 'app:v9-13c', 'owner_app', NULL, jsonb_build_object(:'c6b', NULL))->'items'->0->>'result' AS t1c \gset
:JOB
SELECT public.propose_image_candidates(:'ralb', ('[' ||
  '{"image_id":"' || :'i5' || '","vehicle_id":"' || :'va' || '","verdict":"is_vehicle","join_key":"album","confidence":0.8,"evidence":[{"kind":"album"}],"pass_captured_on":"2024-05-05","album_link_id":"' || :'alb' || '"},' ||
  '{"image_id":"' || :'i6' || '","vehicle_id":"' || :'va' || '","verdict":"is_vehicle","join_key":"album","confidence":0.8,"evidence":[{"kind":"album"}],"pass_captured_on":"2024-05-06","album_link_id":"' || :'alb' || '"}]')::jsonb) AS t1alb \gset
SELECT t_assert(:'alb_ok' = 'confirmed' AND :'t1a' = 'confirmed' AND :'t1c' = 'confirmed'
                AND (:'t1alb'::jsonb->'items'->0->>'result') = 'already_rejected' AND (:'t1alb'::jsonb->'items'->1->>'result') = 'already_rejected'
                AND (:'t1alb'::jsonb->'items'->1->>'confirmed_candidate_id') = :'c6b',
  'V9-13 R-T1: an album row on a truck other than the subject he confirmed is already_rejected (with or without an earlier row on that truck)');
:OWNER
SELECT t_assert((SELECT jsonb_object_agg(vehicle_id, n) FROM (SELECT vehicle_id, count(DISTINCT image_id) n FROM public.evidence_candidates_for_images(ARRAY[:'i5',:'i6']::uuid[], :'ua')
                   WHERE status NOT IN ('rejected','proposed') OR pass = 'combined' AND status <> 'rejected' GROUP BY 1) x)
                = jsonb_build_object(:'vb2', 2),
  'V9-13 R-T1: both photos count on the truck he confirmed only');

-- ------------------------------------------------------------------------------------------------ V9-14 (R-T2)
:JOB
SELECT public.propose_image_candidates(:'rc', ('[' ||
  '{"image_id":"' || :'i7' || '","vehicle_id":"' || :'v1' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-05-07"},' ||
  '{"image_id":"' || :'i8' || '","vehicle_id":"' || :'v1' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-05-08"},' ||
  '{"image_id":"' || :'i8' || '","vehicle_id":"' || :'v3' || '","verdict":"is_vehicle","join_key":"x","confidence":0.6,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-05-08"}]')::jsonb)->>'proposed' AS t2p \gset
SELECT (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'i7' AND superseded_by IS NULL) AS c7,
       (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'i8' AND vehicle_id = :'v1' AND superseded_by IS NULL) AS c8,
       (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'i8' AND vehicle_id = :'v3' AND superseded_by IS NULL) AS c8v3 \gset
:OWNER
SELECT public.decide_evidence('image_candidate', ARRAY[:'c7', :'c8']::uuid[], 'rejected', 'not that truck', 'app:v9-14', 'owner_app', NULL,
  jsonb_build_object(:'c7', NULL, :'c8', NULL))->'items' AS t2no \gset
:ADMIN
UPDATE public.vehicles SET merged_into_vehicle_id = :'v3', deleted_at = now() WHERE id = :'v1';
:JOB
SELECT public.propose_image_candidates(:'rc', ('[' ||
  '{"image_id":"' || :'i7' || '","vehicle_id":"' || :'v1' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-05-07"},' ||
  '{"image_id":"' || :'i7' || '","vehicle_id":"' || :'v3' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-05-07"}]')::jsonb) AS t2re \gset
SELECT public.propose_image_candidates(:'ralb', ('[{"image_id":"' || :'i7' || '","vehicle_id":"' || :'v3' || '","verdict":"is_vehicle","join_key":"album","confidence":0.8,"evidence":[{"kind":"album"}],"pass_captured_on":"2024-05-07","album_link_id":"' || :'alb' || '"}]')::jsonb) AS t2alb \gset
SELECT t_assert((:'t2re'::jsonb->'items'->0->>'result') = 'already_decided' AND (:'t2re'::jsonb->'items'->1->>'result') = 'already_decided'
                AND (:'t2re'::jsonb->>'proposed') = '0',
  'V9-14 R-T2: after a merge, the pass naming the old id or the survivor finds his decided row (already_decided)');
SELECT t_assert((:'t2alb'::jsonb->'items'->0->>'result') = 'already_rejected',
  'V9-14 R-T2: another pass on the survivor is already_rejected: his "no" holds across the merge');
:OWNER
SELECT t_assert((SELECT status FROM public.evidence_candidates_for_images(ARRAY[:'i8']::uuid[], :'ua') WHERE id = :'c8v3') = 'rejected'
                AND (SELECT status FROM public.v_image_candidates_current WHERE id = :'c8v3') = 'rejected'
                AND NOT EXISTS (SELECT 1 FROM public.get_vehicle_day_records(:'v3', NULL, NULL, :'ua') WHERE own_photos > 0),
  'V9-14 R-T2: a row written before the merge on the survivor reads rejected once the trucks are one; the survivor has no photo day');

-- ------------------------------------------------------------------------------------------------ V9-15 (R-T3)
:JOB
SELECT public.propose_image_candidates(:'rc', ('[{"image_id":"' || :'i9' || '","vehicle_id":"' || :'va' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-05-09"}]')::jsonb)->'items'->0->>'candidate_id' AS c9 \gset
:OWNER
SELECT public.decide_evidence('image_candidate', ARRAY[:'c9']::uuid[], 'rejected', 'no', 'app:v9-15a', 'owner_app', NULL, jsonb_build_object(:'c9', NULL))->'items'->0->>'result' AS t3a \gset
SELECT pg_sleep(0.01);
SELECT public.decide_evidence('image_candidate', ARRAY[:'c9']::uuid[], 'confirmed', 'sorry, yes', 'app:v9-15b', 'owner_app', NULL, jsonb_build_object(:'c9', NULL))->'items'->0->>'result' AS t3b \gset
:JOB
SELECT public.propose_image_candidates(:'ralb', ('[{"image_id":"' || :'i9' || '","vehicle_id":"' || :'va' || '","verdict":"is_vehicle","join_key":"album","confidence":0.8,"evidence":[{"kind":"album"}],"pass_captured_on":"2024-05-09","album_link_id":"' || :'alb' || '"}]')::jsonb)->'items'->0->>'candidate_id' AS c9alb \gset
:OWNER
SELECT t_assert((SELECT status FROM public.evidence_candidates_for_images(ARRAY[:'i9']::uuid[], :'ua') WHERE id = :'c9alb') = 'confirmed_by_album_map'
                AND (SELECT status FROM public.v_image_candidates_current WHERE id = :'c9alb') = 'confirmed_by_album_map'
                AND public.evidence_candidate_status(:'c9alb') = 'confirmed_by_album_map',
  'V9-15 R-T3: after "no" then "yes", the day reader, the view and evidence_candidate_status agree');
:JOB
SELECT t_assert((SELECT count(*) FROM public.v_image_candidates_current v
                  WHERE v.user_id = :'ua' AND v.status IS DISTINCT FROM public.evidence_candidate_status(v.id)) = 0
                AND (SELECT count(*) FROM public.v_image_candidates_current v
                      JOIN LATERAL public.evidence_candidates_for_images(ARRAY[v.image_id], v.user_id) r ON r.id = v.id
                     WHERE v.user_id = :'ua' AND v.status IS DISTINCT FROM r.status) = 0,
  'V9-15 R-T3: every current candidate reads one status in the view, the day reader and evidence_candidate_status');

-- ------------------------------------------------------------------------------------------------ V9-16 (R-R3)
:NOSUB
\set ON_ERROR_STOP off
SELECT count(*) FROM public.evidence_answers_to_confirm(:'ua');
\set ON_ERROR_STOP on
SELECT t_refused('V9-16 R-R3: a signed-in role whose token names no user reads no one''s stored words', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '42501', 'a signed-in read needs your user id%');
\set ON_ERROR_STOP off
SELECT count(*) FROM public.get_vehicle_day_records(:'va', NULL, NULL, :'ua');
\set ON_ERROR_STOP on
SELECT t_refused('V9-16 R-R3: nor his day records', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '42501', 'a signed-in read needs your user id%');
:JOB
SELECT t_assert((SELECT count(*) FROM public.evidence_answers_to_confirm(:'ua')) > 0, 'V9-16 R-R3: the job still reads a named user');

-- ------------------------------------------------------------------------------------------------ V9-17 (M5, M6)
SELECT public.propose_account_entities(:'rm', '[{"account_ref":"bank_account:v9.main","entity_key":"owner","confidence":0.7,"evidence":[{"kind":"x"}]}]'::jsonb)->'ids'->>0 AS acct \gset
:OWNER
SELECT public.decide_evidence('account_entity', ARRAY[:'acct']::uuid[], 'confirmed', 'mine', 'app:v9-17', 'owner_app')->'items'->0->>'result' AS acct_ok \gset
:JOB
SELECT public.propose_account_entities(:'rm', '[{"account_ref":"bank_account:v9.main","entity_key":"owner_business:shop","confidence":0.9,"evidence":[{"kind":"x"}]}]'::jsonb) AS m5 \gset
SELECT t_assert((:'m5'::jsonb->>'proposed') = '0' AND (:'m5'::jsonb->>'already_decided') = '1'
                AND (:'m5'::jsonb->'skipped'->0->>'result') = 'already_decided' AND (:'m5'::jsonb->'skipped'->0->>'id') = :'acct',
  'V9-17 M5: an account row he decided is kept and reported (skipped, already_decided)');
SELECT public.propose_capture_time_claims(:'rto', ('[{"image_id":"' || :'i2' || '","stored_taken_at":"2024-05-02 18:00+00","corrected_taken_at":"2024-05-01 18:00+00","offset_seconds":86400,"captured_on":"2024-05-01","rule":"owner","witness":{},"confidence":1}]')::jsonb) AS m6 \gset
SELECT t_assert((:'m6'::jsonb->>'owner_answer_missing') = '1' AND (:'m6'::jsonb->'owner_answer_missing_ids') = jsonb_build_array(:'i2'),
  'V9-17 M6: a job''s owner time is refused and its photo is named (owner_answer_missing_ids)');

-- ------------------------------------------------------------------------------------------------ V9-18..V9-20 (shape)
:ADMIN
SELECT t_assert((SELECT count(*) FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'er_one_answers_per_sheet') = 0
                AND (SELECT NOT indisunique FROM pg_index WHERE indexrelid = 'public.er_answers_by_sheet'::regclass)
                AND (SELECT indisunique FROM pg_index WHERE indexrelid = 'public.er_one_answers_per_message'::regclass),
  'V9-18 W2: M1a''s one-answers-per-sheet index is replaced by a plain index; one answers run per message stays unique');
-- (v10) evidence_places_distinct is no API role's again (F3: evidence_answered_elsewhere answers the reader), and
-- evidence_answer_fits takes the cited reading and the decision (A2)
SELECT t_assert(has_function_privilege('authenticated', 'public.evidence_truck_key(uuid,text,uuid)', 'EXECUTE')
                AND NOT has_function_privilege('authenticated', 'public.evidence_places_distinct(text,text)', 'EXECUTE')
                AND has_function_privilege('authenticated', 'public.evidence_answered_elsewhere(uuid[],uuid)', 'EXECUTE')
                AND NOT has_function_privilege('authenticated', 'public.evidence_answer_fits(jsonb,text,uuid,uuid,timestamptz,jsonb,text)', 'EXECUTE')
                AND NOT has_function_privilege('service_role', 'public.evidence_answer_fits(jsonb,text,uuid,uuid,timestamptz,jsonb,text)', 'EXECUTE')
                AND NOT has_function_privilege('anon', 'public.evidence_truck_key(uuid,text,uuid)', 'EXECUTE')
                AND has_function_privilege('service_role', 'public.evidence_record_answers(uuid,uuid,text,jsonb,text,text,timestamptz)', 'EXECUTE')
                AND NOT has_function_privilege('authenticated', 'public.evidence_record_answers(uuid,uuid,text,jsonb,text,text,timestamptz)', 'EXECUTE')
                AND to_regprocedure('public.evidence_record_answers(uuid,uuid,text,jsonb,text,text)') IS NULL
                AND NOT has_function_privilege('service_role', 'public.decide_evidence(text,uuid[],text,text,text,text,uuid,jsonb,uuid,text,text,jsonb)', 'EXECUTE'),
  'V9-19 grants: the truck helpers are the readers''; the citation check is no API role''s; answers take the message time; decisions stay the owner''s');
SELECT t_assert((SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace
                  AND p.proname IN ('evidence_truck_key','evidence_answer_fits','evidence_answers_to_confirm','evidence_record_answers')
                  AND NOT coalesce(p.proconfig::text ~ 'search_path=public, pg_temp', false)) = 0
                AND (SELECT pg_get_function_result('public.evidence_answers_to_confirm(uuid)'::regprocedure)) LIKE '%message_at timestamp with time zone, question_key text, replaced_by text)',
  'V9-20 shape (v10): the v9 functions pin search_path; the advisory list carries message_at, then (v10) question_key and replaced_by');
SELECT t_assert((SELECT count(*) FROM public.evidence_decisions WHERE decided_by LIKE 'agent:%') = 0, 'V9 end: no agent decision exists');
\echo 'scenario_v9: all checks passed'

RESET ROLE; RESET SESSION AUTHORIZATION;
\pset format aligned
\pset tuples_only off
SELECT coalesce(nullif(current_setting('t.passed', true), ''), '0') AS g_passed \gset
SELECT t_assert(:g_passed = 54, 'group v9: every one of its 54 checks ran and passed');
\echo 'group v9: 54 checks passed'
SELECT :passed_total + :g_passed + 1 AS passed_total \gset
\c :main_db
DROP DATABASE :"grp_db" WITH (FORCE);

-- ================================================================================================ group v10
-- scenario_v10.sql: already written as assertions (t_assert / t_refused)
SELECT left(:'main_db', 48) || '_v10' AS grp_db \gset
DROP DATABASE IF EXISTS :"grp_db" WITH (FORCE);
CREATE DATABASE :"grp_db" TEMPLATE :"tmpl_db" STRATEGY FILE_COPY;   -- a file copy, not the whole template through WAL
\c :grp_db
SET TimeZone = 'America/Los_Angeles'; SET DateStyle = 'ISO, MDY';
\set ON_ERROR_STOP on
-- Local scratch only. (v11: the stated checks read the list; 'stated' carries no totals.)
-- scenario_v10.sql: one check per v10 change of block M1w (DESIGN-v10 "Changes from v9", V10-1 ..
-- V10-9), each the verify-v9 case it answers, written as PR-1's contract test is: ON_ERROR_STOP on; t_assert(<boolean>,
-- label), or after a statement that must fail (run at top level between \set ON_ERROR_STOP off / on) t_refused(label,
-- :'SQLSTATE', :'LAST_ERROR_MESSAGE', <state>, <message LIKE>). Every id is generated (gen_random_uuid()); every actor is
-- a PostgREST-shaped session; message ids carry a run tag. Needs: stubs (or the contract's live-shaped tables), M1a,
-- M1w, on a database of its own (it turns on live's vehicles SELECT policies). Fixture rows (profiles, vehicles,
-- vehicle_images, and the column changes live merge_into_primary / unmerge_vehicle make) are written by the admin
-- session. Cases: A1 answers-v9/a1_reask_latest + verify-A1/v_a1; A2 answers-v9/a2_slot_two_rows + verify-A2/v_a2;
-- A4 answers-v9/a4_*; F1 trucks-v9/t1_w1_aside + verify-F1/trucks-F1; F2 trucks-v9/t3_unmerge + verify-F2/trucks-F2
-- (both namings); F3 trucks-v9/t4_session_split; money verify-F1/f1, verify-F2 (m1_stated_band), money-ship-v9/m2, m3, m3b.
-- ALLOW_RAW_TESTIMONY_WRITE (fixture rows in the stub tables of a throwaway database)
\set ON_ERROR_STOP on
\pset pager off
\pset format unaligned
\pset tuples_only on
SET client_min_messages = notice;
\set VERBOSITY terse
RESET ROLE; RESET SESSION AUTHORIZATION;
-- (scenario_v10.sql defines t_assert and t_refused here; the template's, with the same signatures, are used)

SELECT replace(gen_random_uuid()::text, '-', '') AS tag \gset
SELECT gen_random_uuid() AS ua, gen_random_uuid() AS ub, gen_random_uuid() AS sa, gen_random_uuid() AS sb,
       gen_random_uuid() AS va, gen_random_uuid() AS vs, gen_random_uuid() AS v1, gen_random_uuid() AS v3, gen_random_uuid() AS vbp,
       gen_random_uuid() AS vm \gset
SELECT auth.t_seed_session(:'sa', :'ua'), auth.t_seed_session(:'sb', :'ub');
SELECT '1GCEK14K8RZ' || upper(substr(:'tag', 1, 6)) AS vinb, '1GCEK14K8RZ' || upper(substr(:'tag', 7, 6)) AS vinx \gset
\set JOB 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE service_role; SET request.jwt.claim.role = ''service_role''; RESET request.jwt.claim.sub; SET request.jwt.claims = ''{"role":"service_role"}'';'
\set OWNER 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; SET request.jwt.claim.sub = ''' :ua '''; SET request.jwt.claims = ''{"sub":"' :ua '","role":"authenticated","aal":"aal2","session_id":"' :sa '","amr":[{"method":"totp","timestamp":1700000100}]}'';'
\set STRANGER 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; SET request.jwt.claim.sub = ''' :ub '''; SET request.jwt.claims = ''{"sub":"' :ub '","role":"authenticated","aal":"aal2","session_id":"' :sb '","amr":[{"method":"totp","timestamp":1700000100}]}'';'
\set ADMIN 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET request.jwt.claim.role; RESET request.jwt.claim.sub; RESET request.jwt.claims;'
:ADMIN
-- live's vehicles SELECT policies (pg_policies, 2026-10-20): a private truck is visible to its owner, uploader or user only
ALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS vehicles_private_select ON public.vehicles;
DROP POLICY IF EXISTS vehicles_public_select ON public.vehicles;
CREATE POLICY vehicles_private_select ON public.vehicles FOR SELECT USING (is_public = false AND (SELECT auth.uid()) IS NOT NULL
  AND ((SELECT auth.uid()) = user_id OR (SELECT auth.uid()) = owner_id OR (SELECT auth.uid()) = uploaded_by));
CREATE POLICY vehicles_public_select ON public.vehicles FOR SELECT USING (is_public = true OR auth.role() = 'service_role');
INSERT INTO public.profiles(id) VALUES (:'ua'), (:'ub');
INSERT INTO public.vehicles(id, owner_id) VALUES (:'va', :'ua'), (:'vs', :'ua'), (:'v1', :'ua'), (:'v3', :'ua'), (:'vm', :'ua');
