       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-06-02 18:00+00') AS i2,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-06-03 18:00+00') AS i3,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-06-04 18:00+00') AS i4,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-06-05 18:00+00') AS i5,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-06-06 18:00+00') AS i6,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-06-07 18:00+00') AS i7,
       (SELECT id FROM public.vehicle_images WHERE user_id = :'ua' AND taken_at = '2024-06-08 18:00+00') AS i8 \gset
:JOB
SELECT public.evidence_open_run(:'ua','pilot','loop','script:v10','sha','{}') AS loop \gset
SELECT public.evidence_open_run(:'ua','pilot','combined','script:v10','sha','{}','{}',NULL,NULL,:'loop') AS rc \gset
SELECT public.evidence_open_run(:'ua','pilot','deal_document','script:v10','sha','{}') AS rd \gset
SELECT public.evidence_open_run(:'ua','pilot','ledger_vendor_date','script:v10','sha','{"coverage_to":"2025-12-31","covers_accounts":["bank_account:v10.main"]}') AS rl \gset
SELECT public.evidence_open_run(:'ua','pilot','account_map','script:v10','sha','{}') AS rm \gset
SELECT public.evidence_open_run(:'ua','pilot','photos_join','script:v10','sha','{}') AS rpj \gset
SELECT public.evidence_open_run(:'ua','pilot','time_offset','script:v10','sha','{}') AS rto \gset

-- ------------------------------------------------------------------------------------------------ V10-1 (A1)
-- s1 asks about c1; m1 says yes. s2 re-asks s1#1; m2 (later) says no. Citing m1 must be refused, and the answers list
-- must show m1 replaced by m2 under one question key.
SELECT public.propose_image_candidates(:'rc', ('[{"image_id":"' || :'i1' || '","vehicle_id":"' || :'va' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-01"}]')::jsonb)->'items'->0->>'candidate_id' AS c1 \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v10','sha', jsonb_build_object('sheet_sha256','v10-a1','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','image_candidate','id',:'c1')))))) AS s1 \gset
SELECT public.evidence_close_run(:'s1', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'s1', 'v10:a1m1-' || :'tag', '{"1":{"verbatim":"yes","answer":{"decision":"confirmed"}}}'::jsonb, 'script:v10', 'sha', clock_timestamp()) AS a1 \gset
-- the re-ask (a job-supplied asked_first is ignored: the first asking is the row it re-asks)
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v10','sha', jsonb_build_object('sheet_sha256','v10-a1r','items',1,'rows',
  jsonb_build_object('1', jsonb_build_object('reask_of', 'review:' || :'s1' || '#1', 'asked_first', 'review:' || gen_random_uuid() || '#9')))) AS s2 \gset
SELECT public.evidence_close_run(:'s2', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'s2', 'v10:a1m2-' || :'tag', '{"1":{"verbatim":"no, not that one","answer":{"decision":"rejected"}}}'::jsonb, 'script:v10', 'sha', clock_timestamp()) AS a2 \gset
-- a re-ask of the re-ask keeps the first asking
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v10','sha', jsonb_build_object('sheet_sha256','v10-a1rr','items',1,'rows',
  jsonb_build_object('1', jsonb_build_object('reask_of', 'review:' || :'s2' || '#1')))) AS s2b \gset
SELECT t_assert((SELECT config->'rows'->'1'->>'asked_first' FROM public.evidence_runs WHERE id = :'s2') = 'review:' || :'s1' || '#1'
                AND (SELECT config->'rows'->'1'->>'asked_first' FROM public.evidence_runs WHERE id = :'s2b') = 'review:' || :'s1' || '#1',
  'V10-1 A1: a re-ask (and a re-ask of it) keeps the question''s first asking; a job''s own asked_first is ignored');
:OWNER
\set ON_ERROR_STOP off
SELECT public.decide_evidence('image_candidate', ARRAY[:'c1']::uuid[], 'confirmed', 'as I said', 'review:' || :'s1' || '#1', 'owner_app',
  NULL, jsonb_build_object(:'c1', NULL), NULL, NULL, 'answers:' || :'a1' || '#1');
\set ON_ERROR_STOP on
SELECT t_refused('V10-1 A1: his answer replaced by a later message on a re-ask sheet is not cited', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023',
  'a later message of yours answers that row: answers:' || :'a2' || '#1 replaces this answer');
SELECT t_assert((SELECT count(*) = 2 AND count(DISTINCT question_key) = 1 AND count(*) FILTER (WHERE replaced_by IS NULL) = 1
                        AND bool_and(replaced_by IS NULL OR replaced_by = 'answers:' || :'a2' || '#1')
                   FROM public.evidence_answers_to_confirm() WHERE question_key = 'review:' || :'s1' || '#1'),
  'V10-1 A1: the answers list gives both answers one question_key and marks the older replaced_by the later');
SELECT public.decide_evidence('image_candidate', ARRAY[:'c1']::uuid[], 'rejected', 'as I said', 'review:' || :'s2' || '#1', 'owner_app',
  NULL, jsonb_build_object(:'c1', NULL), NULL, NULL, 'answers:' || :'a2' || '#1')->'items'->0->>'result' AS a1_latest \gset
SELECT t_assert(:'a1_latest' = 'rejected', 'V10-1 A1: his latest answer, on the re-ask, is the one cited');
:JOB
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v10','sha', jsonb_build_object('sheet_sha256','v10-a1f','items',1,'rows',
  jsonb_build_object('1', jsonb_build_object('question','image_candidate','asked_first','review:' || :'s1' || '#1',
                                             'targets', jsonb_build_array(jsonb_build_object('kind','image','id',:'i2')))))) AS s3 \gset
SELECT t_assert((SELECT NOT (config->'rows'->'1' ? 'asked_first') FROM public.evidence_runs WHERE id = :'s3'),
  'V10-1 A1: a fresh row cannot claim another question''s first asking');

-- ------------------------------------------------------------------------------------------------ V10-2 (A2)
-- a slot row ("which truck is this?", the photo only) with two current subject candidates: cA (truck A) and cS (truck S);
-- his answer names truck A
SELECT public.evidence_open_run(:'ua','pilot','deal_document','script:v10','sha','{}') AS rd2 \gset
SELECT public.propose_image_candidates(:'rc', ('[{"image_id":"' || :'i3' || '","vehicle_id":"' || :'va' || '","verdict":"is_vehicle","join_key":"x","confidence":0.6,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-03"}]')::jsonb)->'items'->0->>'candidate_id' AS ca \gset
SELECT public.propose_image_candidates(:'rd2', ('[{"image_id":"' || :'i3' || '","vehicle_id":"' || :'vs' || '","verdict":"is_vehicle","join_key":"y","confidence":0.6,"evidence":[{"kind":"y"}],"pass_captured_on":"2024-06-03"}]')::jsonb)->'items'->0->>'candidate_id' AS cs \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v10','sha', jsonb_build_object('sheet_sha256','v10-a2','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('question','image_candidate','targets', jsonb_build_array(jsonb_build_object('kind','image','id',:'i3')))))) AS s4 \gset
SELECT public.evidence_close_run(:'s4', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'s4', 'v10:a2m1-' || :'tag', jsonb_build_object('1', jsonb_build_object('verbatim','thats the A truck',
  'answer', jsonb_build_object('decision','confirmed','vehicle_id',:'va'))), 'script:v10', 'sha', clock_timestamp()) AS a4 \gset
:OWNER
SELECT public.decide_evidence('image_candidate', ARRAY[:'cs']::uuid[], 'confirmed', 'as I said', 'review:' || :'s4' || '#1', 'owner_app',
  NULL, jsonb_build_object(:'cs', NULL), NULL, NULL, 'answers:' || :'a4' || '#1')->'items'->0 AS a2_other \gset
SELECT t_assert((:'a2_other'::jsonb->>'result') = 'not_on_answered_row' AND (:'a2_other'::jsonb->>'answered_place') = :'va'
                AND public.evidence_candidate_status(:'ca') = 'proposed' AND public.evidence_candidate_status(:'cs') = 'proposed',
  'V10-2 A2: on a slot row, his "it is the A truck" is not confirmed on the other truck''s row, and nothing is implied');
SELECT public.decide_evidence('image_candidate', ARRAY[:'ca']::uuid[], 'confirmed', 'as I said', 'review:' || :'s4' || '#1', 'owner_app',
  NULL, jsonb_build_object(:'ca', NULL), NULL, NULL, 'answers:' || :'a4' || '#1')->'items'->0->>'result' AS a2_named \gset
SELECT t_assert(:'a2_named' = 'confirmed' AND public.evidence_candidate_status(:'cs') = 'rejected',
  'V10-2 A2: it is confirmed on the truck he named (the other row reads rejected)');
-- an account slot row: "that's my own account" on a row the passes give a business
:JOB
SELECT public.propose_account_entities(:'rm', '[{"account_ref":"bank_account:v10.slot","entity_key":"owner_business:shop","confidence":0.6,"evidence":[{"kind":"x"}]}]'::jsonb)->'ids'->>0 AS acct_b \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v10','sha', jsonb_build_object('sheet_sha256','v10-a2b','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','account','key','bank_account:v10.slot')))))) AS s5 \gset
SELECT public.evidence_close_run(:'s5', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'s5', 'v10:a2m2-' || :'tag', '{"1":{"verbatim":"thats my own account","answer":{"decision":"confirmed","entity_key":"owner"}}}'::jsonb, 'script:v10', 'sha', clock_timestamp()) AS a5 \gset
:OWNER
SELECT public.decide_evidence('account_entity', ARRAY[:'acct_b']::uuid[], 'confirmed', 'as I said', 'review:' || :'s5' || '#1', 'owner_app',
  NULL, NULL, NULL, NULL, 'answers:' || :'a5' || '#1')->'items'->0 AS a2_acct \gset
SELECT t_assert((:'a2_acct'::jsonb->>'result') = 'not_on_answered_row' AND (:'a2_acct'::jsonb->>'answered_place') = 'entity:owner'
                AND NOT EXISTS (SELECT 1 FROM public.evidence_decisions WHERE target_id = :'acct_b'),
  'V10-2 A2: an account row giving another owner than the one he said is not confirmed on his answer');
-- a payment slot row ("where does this payment go?"); his "yes, the M truck"; the slot also holds a contradiction of that
-- placement (a message saying the payment was not for M): confirming the contradiction would reject the payment on M
:JOB
SELECT public.propose_evidence_links(:'rl', ('[' ||
  '{"vehicle_id":"' || :'vm' || '","source_kind":"bank_line","external_ref":"bank:v10-slot","occurred_on":"2024-05-01","direction":"out","amount_cents":5000,"role":"payment_out","payment_key":"bank:v10-slot","cost_category":"parts","from_account_ref":"bank_account:v10.main","join_key":"x","confidence":0.7,"evidence":[{"kind":"bank"}]},' ||
  '{"vehicle_id":"' || :'vm' || '","source_kind":"message","external_ref":"msg:v10-slot","occurred_on":"2024-05-01","direction":"out","role":"contradicts","payment_key":"bank:v10-slot","join_key":"msg","confidence":0.6,"evidence":[{"kind":"msg"}]}]')::jsonb) AS ls \gset
SELECT (:'ls'::jsonb->'items'->0->>'link_id') AS l_place, (:'ls'::jsonb->'items'->1->>'link_id') AS l_contra \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v10','sha', jsonb_build_object('sheet_sha256','v10-a2c','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','payment','key','bank:v10-slot')))))) AS s6 \gset
SELECT public.evidence_close_run(:'s6', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'s6', 'v10:a2m3-' || :'tag', jsonb_build_object('1', jsonb_build_object('verbatim','that was for the M truck',
  'answer', jsonb_build_object('decision','confirmed','vehicle_id',:'vm'))), 'script:v10', 'sha', clock_timestamp()) AS a6 \gset
:OWNER
SELECT public.decide_evidence('evidence_link', ARRAY[:'l_contra']::uuid[], 'confirmed', 'as I said', 'review:' || :'s6' || '#1', 'owner_app',
  NULL, NULL, NULL, NULL, 'answers:' || :'a6' || '#1')->'items'->0->>'result' AS a2_contra \gset
SELECT public.decide_evidence('evidence_link', ARRAY[:'l_place']::uuid[], 'confirmed', 'as I said', 'review:' || :'s6' || '#1', 'owner_app',
  NULL, NULL, NULL, NULL, 'answers:' || :'a6' || '#1')->'items'->0->>'result' AS a2_place \gset
SELECT t_assert(:'a2_contra' = 'not_on_answered_row' AND :'a2_place' = 'confirmed'
                AND NOT EXISTS (SELECT 1 FROM public.evidence_decisions WHERE target_id = :'l_contra')
                AND (SELECT v->>'cents' FROM jsonb_each(public.vehicle_accounting_evidence(:'vm')->'costs') x(k, v) WHERE k = 'confirmed') = '5000',
  'V10-2 A2: on a money slot row his "yes, the M truck" confirms the placement on M, never the contradiction of it');

-- ------------------------------------------------------------------------------------------------ V10-3 (A4)
:ADMIN
SELECT t_assert((SELECT count(*) FROM pg_indexes WHERE schemaname = 'public' AND indexname IN ('ivc_user_image','el_user_payment_key','el_user_source_key')) = 3
                AND (SELECT bool_and(NOT indisunique AND indpred IS NULL) FROM pg_index
                      WHERE indexrelid IN ('public.ivc_user_image'::regclass, 'public.el_user_source_key'::regclass))
                AND (SELECT pg_get_indexdef('public.el_user_payment_key'::regclass)) LIKE '%(user_id, payment_key) WHERE (payment_key IS NOT NULL)',
  'V10-3 A4: full (not current-only) indexes for the answers list''s slot probes');

-- ------------------------------------------------------------------------------------------------ V10-4 (trucks F1)
-- the Photos join dates I4 at 18:00:00.437 (machine-confirmed); he says no to that day; the batch-offset pass writes
-- the whole-second copy (offset 0) and a 4 h offset (14:00), both on that day
:JOB
SELECT public.propose_capture_time_claims(:'rpj', ('[{"image_id":"' || :'i4' || '","stored_taken_at":"2024-06-04 18:00+00","corrected_taken_at":"2024-06-04 18:00:00.437+00","offset_seconds":0,"local_offset_minutes":-420,"captured_on":"2024-06-04","rule":"photos_exif_join","witness":{"unique_match":true},"confidence":0.99}]')::jsonb)->>'machine_confirmed' AS f1_conf \gset
SELECT id AS f1_claim FROM public.image_capture_time_claims WHERE image_id = :'i4' AND superseded_by IS NULL \gset
:OWNER
SELECT public.decide_evidence('capture_time_claim', ARRAY[:'f1_claim']::uuid[], 'rejected', 'not that day', 'app:v10-4', 'owner_app')->'items'->0->>'result' AS f1_no \gset
:JOB
SELECT public.propose_capture_time_claims(:'rto', ('[' ||
  '{"image_id":"' || :'i4' || '","stored_taken_at":"2024-06-04 18:00+00","corrected_taken_at":"2024-06-04 18:00:00+00","offset_seconds":0,"captured_on":"2024-06-04","rule":"batch_offset_v1","batch_key":"v10b0","witness":{"upload_day":"2024-06-05"},"confidence":0.6},' ||
  '{"image_id":"' || :'i4' || '","stored_taken_at":"2024-06-04 18:00+00","corrected_taken_at":"2024-06-04 14:00:00+00","offset_seconds":14400,"captured_on":"2024-06-04","rule":"batch_offset_v1","batch_key":"v10b4","witness":{"upload_day":"2024-06-05"},"confidence":0.6}]')::jsonb) AS f1_bo \gset
SELECT t_assert(:'f1_conf' = '1' AND :'f1_no' = 'rejected' AND (:'f1_bo'::jsonb->>'already_rejected') = '2' AND (:'f1_bo'::jsonb->>'proposed') = '0',
  'V10-4 F1: any other instant on the day he said no to is already_rejected');
SELECT t_assert((SELECT bool_and(captured_on IS NULL AND time_unverified) FROM public.evidence_candidates_for_images(ARRAY[:'i4']::uuid[], :'ua')) IS NOT FALSE
                AND NOT EXISTS (SELECT 1 FROM public.image_capture_time_claims t WHERE t.image_id = :'i4' AND t.superseded_by IS NULL
                                  AND public.evidence_status('capture_time_claim', t.id) = 'confirmed'),
  'V10-4 F1: the photo stays undated');
-- another day is not blocked: the batch pass dates I4 a day earlier, and the gate (a batch that agrees) confirms it
SELECT public.propose_capture_time_claims(:'rto', ('[{"image_id":"' || :'i4' || '","stored_taken_at":"2024-06-04 18:00+00","corrected_taken_at":"2024-06-03 18:00:00+00","offset_seconds":86400,"captured_on":"2024-06-03","rule":"batch_offset_v1","batch_key":"v10b24","witness":{"upload_day":"2024-06-05"},"confidence":0.6}]')::jsonb)->>'proposed' AS f1_other \gset
SELECT public.evidence_open_run(:'ua','daily','time_rule_gate','script:v10','sha','{}') AS g1 \gset
SELECT public.evidence_close_run(:'g1', 'done', '{"batches":{"v10b24":{"joined":80,"agreement":0.996,"offset_seconds":86400}}}'::jsonb);
SELECT public.confirm_capture_times_by_rule(:'g1', ARRAY(SELECT id FROM public.image_capture_time_claims WHERE image_id = :'i4' AND superseded_by IS NULL))->>'confirmed' AS f1_gate \gset
SELECT t_assert(:'f1_other' = '1' AND :'f1_gate' = '1', 'V10-4 F1: a claim on another day is proposed and the gate confirms it (his no is about its own day)');
-- the race the writer cannot see is race_f1.sh (a claim written on that day while his no commits: the gate skips it)

-- ------------------------------------------------------------------------------------------------ V10-5 (trucks F2)
-- I5, I6 are filed on V1; V1 is merged into V3 (live merge_into_primary: the photos move to V3 stamped merged_from V1,
-- V1 is soft-deleted). A pass names the survivor V3 for I5 and the old id V1 for I6. He confirms I5, rejects I6. Then the
-- live unmerge returns the photos to V1.
:ADMIN
UPDATE public.vehicle_images SET vehicle_id = :'v1' WHERE id IN (:'i5', :'i6');
UPDATE public.vehicle_images SET merged_from_vehicle_id = :'v1', vehicle_id = :'v3' WHERE vehicle_id = :'v1';
UPDATE public.vehicles SET merged_into_vehicle_id = :'v3', deleted_at = now(), status = 'merged' WHERE id = :'v1';
:JOB
SELECT public.propose_image_candidates(:'rc', ('[' ||
  '{"image_id":"' || :'i5' || '","vehicle_id":"' || :'v3' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-05"},' ||
  '{"image_id":"' || :'i6' || '","vehicle_id":"' || :'v1' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-06"}]')::jsonb)->>'proposed' AS f2_n \gset
SELECT (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'i5' AND superseded_by IS NULL) AS c5,
       (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'i6' AND superseded_by IS NULL) AS c6 \gset
SELECT t_assert(:'f2_n' = '2' AND (SELECT bool_and(vehicle_id = :'v1') FROM public.image_vehicle_candidates WHERE id IN (:'c5', :'c6')),
  'V10-5 F2: a candidate stores the photo''s own vehicle row (the row a merge moved it from), never the survivor');
:OWNER
SELECT public.decide_evidence('image_candidate', ARRAY[:'c5']::uuid[], 'confirmed', 'yes', 'app:v10-5a', 'owner_app', NULL, jsonb_build_object(:'c5', :'v3'))->'items'->0->>'result' AS f2_yes \gset
SELECT public.decide_evidence('image_candidate', ARRAY[:'c6']::uuid[], 'rejected', 'not this truck', 'app:v10-5b', 'owner_app', NULL, jsonb_build_object(:'c6', :'v3'))->'items'->0->>'result' AS f2_no \gset
:ADMIN
UPDATE public.vehicle_images SET vehicle_id = :'v1', merged_from_vehicle_id = NULL WHERE vehicle_id = :'v3' AND merged_from_vehicle_id = :'v1';
UPDATE public.vehicles SET status = 'active', merged_into_vehicle_id = NULL, deleted_at = NULL WHERE id = :'v1';
:JOB
SELECT public.evidence_open_run(:'ua','pilot','combined','script:v10','sha2','{}','{}',NULL,NULL,:'loop') AS rc2 \gset
SELECT public.propose_image_candidates(:'rc2', ('[' ||
  '{"image_id":"' || :'i5' || '","vehicle_id":"' || :'v1' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-05"},' ||
  '{"image_id":"' || :'i6' || '","vehicle_id":"' || :'v1' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-06"}]')::jsonb) AS f2_after \gset
:OWNER
SELECT t_assert(:'f2_yes' = 'confirmed' AND :'f2_no' = 'rejected'
                AND (:'f2_after'::jsonb->'items'->0->>'result') = 'already_decided' AND (:'f2_after'::jsonb->'items'->1->>'result') = 'already_decided'
                AND public.evidence_candidate_status(:'c5') = 'confirmed' AND public.evidence_candidate_status(:'c6') = 'rejected'
                AND (SELECT own_photos_confirmed FROM public.get_vehicle_day_records(:'v1', NULL, NULL, :'ua') WHERE day = '2024-06-05') = 1
                AND NOT EXISTS (SELECT 1 FROM public.get_vehicle_day_records(:'v1', NULL, NULL, :'ua') WHERE day = '2024-06-06' AND own_photos > 0)
                AND NOT EXISTS (SELECT 1 FROM public.get_vehicle_day_records(:'v3', NULL, NULL, :'ua') WHERE own_photos > 0),
  'V10-5 F2: after the unmerge his yes and his no are on the photos'' own truck, and the next pass finds them there');

-- ------------------------------------------------------------------------------------------------ V10-6 (trucks F3)
-- he confirms I7 is the truck with no row vin:<V>; a pass names the stranger's private truck, which carries V
:JOB
SELECT public.propose_image_candidates(:'rc', ('[{"image_id":"' || :'i7' || '","subject_key":"vin:' || :'vinb' || '","verdict":"is_vehicle","join_key":"plate","confidence":0.7,"evidence":[{"kind":"vin"}],"pass_captured_on":"2024-06-07"}]')::jsonb)->'items'->0->>'candidate_id' AS c7 \gset
:OWNER
SELECT public.decide_evidence('image_candidate', ARRAY[:'c7']::uuid[], 'confirmed', 'that truck', 'app:v10-6', 'owner_app', NULL, jsonb_build_object(:'c7', NULL))->'items'->0->>'result' AS f3_yes \gset
:JOB
SELECT public.evidence_open_run(:'ua','pilot','paid_vision','script:v10','sha','{}') AS rpv \gset
SELECT public.propose_image_candidates(:'rpv', ('[{"image_id":"' || :'i7' || '","vehicle_id":"' || :'vbp' || '","verdict":"is_vehicle","join_key":"vision","confidence":0.7,"evidence":[{"kind":"vision"}],"pass_captured_on":"2024-06-07"}]')::jsonb)->'items'->0->>'candidate_id' AS c7b \gset
SELECT status AS f3_job FROM public.evidence_candidates_for_images(ARRAY[:'i7']::uuid[], :'ua') WHERE id = :'c7b' \gset
SELECT status AS f3_jobview FROM public.v_image_candidates_current WHERE id = :'c7b' \gset
:OWNER
SELECT status AS f3_app FROM public.evidence_candidates_for_images(ARRAY[:'i7']::uuid[], :'ua') WHERE id = :'c7b' \gset
SELECT status AS f3_appview FROM public.v_image_candidates_current WHERE id = :'c7b' \gset
SELECT t_assert(:'f3_yes' = 'confirmed' AND :'f3_app' = 'proposed' AND :'f3_job' = :'f3_app' AND :'f3_jobview' = :'f3_app' AND :'f3_appview' = :'f3_app'
                AND public.evidence_candidate_status(:'c7b') = :'f3_app',
  'V10-6 F3: a row naming another user''s private truck carrying the VIN he confirmed reads the same in his app and for the job');
-- no VIN oracle: the stranger asks, with the right VIN and with a wrong one, whether the private truck carries it
:STRANGER
\set ON_ERROR_STOP off
SELECT public.evidence_places_distinct(:'vbp'::text, 'vin:' || :'vinb');
\set ON_ERROR_STOP on
SELECT :'SQLSTATE' AS f3_right_state, :'LAST_ERROR_MESSAGE' AS f3_right_msg \gset
\set ON_ERROR_STOP off
SELECT public.evidence_places_distinct(:'vbp'::text, 'vin:' || :'vinx');
\set ON_ERROR_STOP on
SELECT :'SQLSTATE' AS f3_wrong_state, :'LAST_ERROR_MESSAGE' AS f3_wrong_msg \gset
SELECT t_refused('V10-6 F3: no API role compares a vehicle''s VIN (the stranger, the right VIN)', :'f3_right_state', :'f3_right_msg', '42501', 'permission denied for function evidence_places_distinct');
SELECT t_assert(:'f3_right_state' = :'f3_wrong_state' AND :'f3_right_msg' = :'f3_wrong_msg',
  'V10-6 F3: the right VIN and a wrong one get the same answer (42501)');
SELECT t_assert((SELECT count(*) FROM public.evidence_answered_elsewhere(ARRAY[:'i7']::uuid[], :'ua')) = 0
                AND (SELECT count(*) FROM public.evidence_answered_elsewhere(ARRAY[:'i7']::uuid[], :'ub')) = 0,
  'V10-6 F3: the reader''s definer helper answers a stranger nothing about another user''s photos');

-- ------------------------------------------------------------------------------------------------ V10-7 (money: never summed)
-- verify-F1 case A: an 800000 purchase paid as a deposit and a balance; he says he paid it (his statement); the ledger
-- pass places both bank lines on the truck, and an unrelated parts line
:JOB
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'va','claim_domain','custody','kind','acquisition','occurred_from','2024-01-10',
  'occurred_to','2024-01-18','amount_cents',800000,'summary','bought','confidence',0.8), '[]'::jsonb) AS k0 \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v10','sha', jsonb_build_object('sheet_sha256','v10-wp','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','change_claim','id',:'k0')))))) AS swp \gset
SELECT public.evidence_close_run(:'swp', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'swp', 'v10:wp-' || :'tag', '{"1":{"verbatim":"I paid","answer":{"decision":"confirmed","entity_key":"owner"}}}'::jsonb, 'script:v10', 'sha', clock_timestamp()) AS awp \gset
:OWNER
SELECT public.decide_evidence('change_claim', ARRAY[:'k0']::uuid[], 'confirmed', 'I paid', 'review:' || :'swp' || '#1', 'owner_app', NULL, NULL, NULL, NULL,
  'answers:' || :'awp' || '#1', '{"entity_key":"owner"}'::jsonb)->'items'->0->>'result' AS wp \gset
:JOB
SELECT public.propose_evidence_links(:'rl', ('[' ||
  '{"vehicle_id":"' || :'va' || '","source_kind":"bank_line","external_ref":"bank:v10-dep","occurred_on":"2024-01-11","direction":"out","amount_cents":200000,"role":"payment_out","payment_key":"bank:v10-dep","cost_category":"purchase","from_account_ref":"bank_account:v10.main","join_key":"x","confidence":0.9,"evidence":[{"kind":"bank"}]},' ||
  '{"vehicle_id":"' || :'va' || '","source_kind":"bank_line","external_ref":"bank:v10-bal","occurred_on":"2024-01-18","direction":"out","amount_cents":600000,"role":"payment_out","payment_key":"bank:v10-bal","cost_category":"purchase","from_account_ref":"bank_account:v10.main","join_key":"x","confidence":0.9,"evidence":[{"kind":"bank"}]},' ||
  '{"vehicle_id":"' || :'va' || '","source_kind":"bank_line","external_ref":"bank:v10-parts","occurred_on":"2024-01-15","direction":"out","amount_cents":4500,"role":"payment_out","payment_key":"bank:v10-parts","cost_category":"parts","from_account_ref":"bank_account:v10.main","join_key":"x","confidence":0.9,"evidence":[{"kind":"bank"}]}]')::jsonb)->>'proposed' AS lb_n \gset
:OWNER
SELECT public.vehicle_accounting_evidence(:'va') AS vae \gset
SELECT t_assert(:'wp' = 'statement_recorded' AND :'lb_n' = '3'
                AND (SELECT sum((v->>'cents')::bigint) FROM jsonb_each(:'vae'::jsonb->'costs') x(k, v) WHERE v ? 'payments') = 804500
                AND NOT EXISTS (SELECT 1 FROM jsonb_each(:'vae'::jsonb->'costs') x(k, v), jsonb_array_elements(coalesce(v->'payments', '[]'::jsonb)) p
                                 WHERE p->>'payment_key' LIKE 'owner:%'),
  'V10-7 money: sums come only from keyed payments, each once (deposit, balance, parts); his statement is in no band');
SELECT t_assert(NOT (:'vae'::jsonb->'stated' ? 'cents_out') AND NOT (:'vae'::jsonb->'stated' ? 'cents_in')
                AND jsonb_array_length(:'vae'::jsonb->'stated'->'statements') = 1
                AND (:'vae'::jsonb->'stated'->'statements'->0->>'cents')::bigint = 800000
                AND (:'vae'::jsonb->'stated'->'statements'->0->>'direction') = 'out'
                AND (:'vae'::jsonb->'stated'->'statements'->0->>'payer') = 'owner'
                AND (:'vae'::jsonb->'stated'->'statements'->0->'answers'->>'kind') = 'claim'
                AND (:'vae'::jsonb->'stated'->'statements'->0->'answers'->>'id') = :'k0'
                AND (:'vae'::jsonb->'stated'->'statements'->0->>'covered_cents')::bigint = 800000
                AND (:'vae'::jsonb->'stated'->'statements'->0->'covered_by') = '["bank:v10-bal", "bank:v10-dep"]'::jsonb,
  'V10-7 money: his statement is listed under stated (cents, direction, payer, the claim it answers), covered by the deposit and the balance (not the parts line)');
SELECT t_assert(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(:'vae'::jsonb->'open_questions') q WHERE q->>'q' IN ('who_paid','acquisition_conflict')),
  'V10-7 money: his statement still closes who_paid');
-- verify-F1 case B on truck S: one wire of 802500 (800000 and a 2500 fee), no category: summed once, as paid
:JOB
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'vs','claim_domain','custody','kind','acquisition','occurred_from','2024-02-01',
  'occurred_to','2024-02-03','amount_cents',800000,'summary','bought','confidence',0.8), '[]'::jsonb) AS ks \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v10','sha', jsonb_build_object('sheet_sha256','v10-wps','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','change_claim','id',:'ks')))))) AS swps \gset
SELECT public.evidence_close_run(:'swps', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'swps', 'v10:wps-' || :'tag', '{"1":{"verbatim":"I paid that too","answer":{"decision":"confirmed","entity_key":"owner"}}}'::jsonb, 'script:v10', 'sha', clock_timestamp()) AS awps \gset
:OWNER
SELECT public.decide_evidence('change_claim', ARRAY[:'ks']::uuid[], 'confirmed', 'I paid', 'review:' || :'swps' || '#1', 'owner_app', NULL, NULL, NULL, NULL,
  'answers:' || :'awps' || '#1', '{"entity_key":"owner"}'::jsonb)->'items'->0->>'result' AS wps \gset
:JOB
SELECT public.propose_evidence_links(:'rl', ('[{"vehicle_id":"' || :'vs' || '","source_kind":"bank_line","external_ref":"bank:v10-wire","occurred_on":"2024-02-02","direction":"out","amount_cents":802500,"role":"payment_out","payment_key":"bank:v10-wire","from_account_ref":"bank_account:v10.main","join_key":"x","confidence":0.9,"evidence":[{"kind":"bank"}]}]')::jsonb)->>'proposed' AS lw \gset
:OWNER
SELECT public.vehicle_accounting_evidence(:'vs') AS vaes \gset
SELECT t_assert(:'wps' = 'statement_recorded' AND :'lw' = '1'
                AND (SELECT sum((v->>'cents')::bigint) FROM jsonb_each(:'vaes'::jsonb->'costs') x(k, v) WHERE v ? 'payments') = 802500
                AND (:'vaes'::jsonb->'stated'->'statements'->0->>'cents')::bigint = 800000
                AND (:'vaes'::jsonb->'stated'->'statements'->0->>'covered_cents')::bigint = 800000,
  'V10-7 money: a wire with a fee and no category is summed once as paid; his statement is listed beside it, covered');
-- money-ship-v9 m2: a pass cannot re-write the claim he answered, so its corrected reading is a second claim
:JOB
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'va','claim_domain','custody','kind','acquisition','occurred_from','2024-01-10',
  'occurred_to','2024-01-18','amount_cents',820000,'summary','bought (page 2)','confidence',0.9), '[]'::jsonb) AS k1 \gset
:OWNER
SELECT public.vehicle_accounting_evidence(:'va') AS vae2 \gset
SELECT t_assert(EXISTS (SELECT 1 FROM jsonb_array_elements(:'vae2'::jsonb->'open_questions') q
                         WHERE q->>'q' = 'acquisition_conflict' AND q->>'kind' = 'acquisition'
                           AND q->'claim_ids' = (SELECT jsonb_agg(x ORDER BY x) FROM (VALUES (:'k0'::uuid), (:'k1'::uuid)) v(x)))
                AND (SELECT sum((v->>'cents')::bigint) FROM jsonb_each(:'vae2'::jsonb->'costs') x(k, v) WHERE v ? 'payments') = 804500
                AND jsonb_array_length(:'vae2'::jsonb->'stated'->'statements') = 1,
  'V10-7 money F4: two current acquisition claims raise acquisition_conflict; nothing is summed twice');

-- ------------------------------------------------------------------------------------------------ V10-8 (money F3, F5)
-- money-ship-v9 m3: a journal entry is a payment source (no who-paid row on it); a receipt is not: his statement on it
-- is listed, answering the link, and the bank line of the same money is summed once
:JOB
SELECT public.propose_evidence_links(:'rl', ('[' ||
  '{"vehicle_id":"' || :'va' || '","source_kind":"journal_entry","external_ref":"journal:v10-1","anchor":"line:1","occurred_on":"2024-03-01","direction":"out","amount_cents":4500,"role":"payment_out","cost_category":"parts","join_key":"x","confidence":0.9,"evidence":[{"kind":"journal"}]},' ||
  '{"vehicle_id":"' || :'va' || '","source_kind":"pnl_line","external_ref":"pnl:v10-7","occurred_on":"2024-03-02","direction":"out","amount_cents":3000,"role":"payment_out","cost_category":"parts","join_key":"x","confidence":0.9,"evidence":[{"kind":"pnl"}]},' ||
  '{"vehicle_id":"' || :'vs' || '","source_kind":"receipt","external_ref":"receipt:v10-9","occurred_on":"2024-04-02","direction":"out","amount_cents":12000,"role":"payment_out","cost_category":"parts","join_key":"x","confidence":0.9,"evidence":[{"kind":"receipt"}]}]')::jsonb) AS lj \gset
SELECT (:'lj'::jsonb->'items'->0->>'link_id') AS l_journal, (:'lj'::jsonb->'items'->1->>'link_id') AS l_pnl, (:'lj'::jsonb->'items'->2->>'link_id') AS l_rcpt \gset
\set ON_ERROR_STOP off
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v10','sha', jsonb_build_object('sheet_sha256','v10-j','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','evidence_link','id',:'l_journal'))))));
\set ON_ERROR_STOP on
SELECT t_refused('V10-8 money F3: a journal entry is a payment source: no who-paid row on it', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'sheet row 1: this money is a payment source line%');
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v10','sha', jsonb_build_object('sheet_sha256','v10-p','items',2,'rows',jsonb_build_object(
  '1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','evidence_link','id',:'l_pnl'))),
  '2', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','evidence_link','id',:'l_rcpt')))))) AS s_pr \gset
SELECT t_assert(:'s_pr' <> '' AND public.evidence_is_payment_source('journal_entry') AND NOT public.evidence_is_payment_source('pnl_line')
                AND NOT public.evidence_is_payment_source('receipt') AND public.evidence_is_payment_source('bank_line')
                AND NOT public.evidence_is_payment_source(NULL),
  'V10-8 money F5: a P&L line is not a payment source, so who paid it can be asked (and a receipt''s)');
SELECT public.evidence_close_run(:'s_pr', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'s_pr', 'v10:pr-' || :'tag', '{"2":{"verbatim":"mine","answer":{"decision":"confirmed","entity_key":"owner"}}}'::jsonb, 'script:v10', 'sha', clock_timestamp()) AS apr \gset
:OWNER
SELECT public.decide_evidence('evidence_link', ARRAY[:'l_rcpt']::uuid[], 'confirmed', 'I paid', 'review:' || :'s_pr' || '#2', 'owner_app', NULL, NULL, NULL, NULL,
  'answers:' || :'apr' || '#2', '{"entity_key":"owner"}'::jsonb)->'items'->0->>'result' AS rcpt \gset
:JOB
SELECT public.propose_evidence_links(:'rl', ('[{"vehicle_id":"' || :'vs' || '","source_kind":"bank_line","external_ref":"bank:v10-0402","occurred_on":"2024-04-03","direction":"out","amount_cents":12000,"role":"payment_out","payment_key":"bank:v10-0402","cost_category":"parts","from_account_ref":"bank_account:v10.main","join_key":"x","confidence":0.92,"evidence":[{"kind":"bank"}]}]')::jsonb)->>'proposed' AS lr2 \gset
:OWNER
SELECT public.vehicle_accounting_evidence(:'vs') AS vaes2 \gset
SELECT t_assert(:'rcpt' = 'statement_recorded' AND :'lr2' = '1'
                AND (SELECT sum((v->>'cents')::bigint) FROM jsonb_each(:'vaes2'::jsonb->'costs') x(k, v) WHERE v ? 'payments') = 802500 + 12000
                AND EXISTS (SELECT 1 FROM jsonb_array_elements(:'vaes2'::jsonb->'stated'->'statements') s
                             WHERE s->'answers'->>'kind' = 'link' AND s->'answers'->>'id' = :'l_rcpt' AND (s->>'cents')::bigint = 12000
                               AND (s->>'covered_cents')::bigint = 12000 AND s->'covered_by' = '["bank:v10-0402"]'::jsonb),
  'V10-8 money F3: a statement answering a link is listed, never summed; the bank line of that money is summed once');

-- ------------------------------------------------------------------------------------------------ V10-9 (shape)
:ADMIN
SELECT t_assert(NOT has_function_privilege('authenticated', 'public.evidence_places_distinct(text,text)', 'EXECUTE')
                AND NOT has_function_privilege('service_role', 'public.evidence_places_distinct(text,text)', 'EXECUTE')
                AND NOT has_function_privilege('anon', 'public.evidence_places_distinct(text,text)', 'EXECUTE')
                AND has_function_privilege('authenticated', 'public.evidence_answered_elsewhere(uuid[],uuid)', 'EXECUTE')
                AND has_function_privilege('service_role', 'public.evidence_answered_elsewhere(uuid[],uuid)', 'EXECUTE')
                AND NOT has_function_privilege('anon', 'public.evidence_answered_elsewhere(uuid[],uuid)', 'EXECUTE')
                AND (SELECT prosecdef FROM pg_proc WHERE oid = 'public.evidence_answered_elsewhere(uuid[],uuid)'::regprocedure)
                AND has_function_privilege('authenticated', 'public.evidence_is_payment_source(text)', 'EXECUTE')
                AND NOT has_function_privilege('authenticated', 'public.evidence_answer_fits(jsonb,text,uuid,uuid,timestamptz,jsonb,text)', 'EXECUTE')
                AND NOT has_function_privilege('service_role', 'public.evidence_answer_fits(jsonb,text,uuid,uuid,timestamptz,jsonb,text)', 'EXECUTE')
                AND to_regprocedure('public.evidence_answer_fits(jsonb,text,uuid,uuid,timestamptz)') IS NULL
                AND (SELECT pg_get_function_result('public.evidence_answers_to_confirm(uuid)'::regprocedure)) LIKE '%message_at timestamp with time zone, question_key text, replaced_by text)'
                AND (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace
                      AND p.proname IN ('evidence_answered_elsewhere','evidence_is_payment_source','evidence_answer_fits')) = 3
                AND (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace
                      AND p.proname IN ('evidence_answered_elsewhere','evidence_is_payment_source','evidence_answer_fits')
                      AND NOT coalesce(p.proconfig::text LIKE '%search_path=public, pg_temp%', false)) = 0,
  'V10-9 shape: no API role compares VINs; the reader''s helpers are granted, pin search_path, and the old citation signature is gone');
SELECT t_assert((SELECT count(*) FROM public.evidence_decisions WHERE decided_by LIKE 'agent:%') = 0, 'V10 end: no agent decision exists');
\echo 'scenario_v10: all checks passed'

RESET ROLE; RESET SESSION AUTHORIZATION;
\pset format aligned
\pset tuples_only off
SELECT coalesce(nullif(current_setting('t.passed', true), ''), '0') AS g_passed \gset
SELECT t_assert(:g_passed = 29, 'group v10: every one of its 29 checks ran and passed');
\echo 'group v10: 29 checks passed'
SELECT :passed_total + :g_passed + 1 AS passed_total \gset
\c :main_db
DROP DATABASE :"grp_db" WITH (FORCE);

-- ================================================================================================ group v11
-- scenario_v11.sql: already written as assertions (t_assert / t_refused)
SELECT left(:'main_db', 48) || '_v11' AS grp_db \gset
DROP DATABASE IF EXISTS :"grp_db" WITH (FORCE);
CREATE DATABASE :"grp_db" TEMPLATE :"tmpl_db" STRATEGY FILE_COPY;   -- a file copy, not the whole template through WAL
\c :grp_db
SET TimeZone = 'America/Los_Angeles'; SET DateStyle = 'ISO, MDY';
\set ON_ERROR_STOP on
-- Local scratch only. scenario_v11.sql: one check per v11 change of block M1w (DESIGN-v11 "Changes from v10", V11-1 ..
-- V11-8), each the verify-v10 case it answers, written as PR-1's contract test is: ON_ERROR_STOP on; t_assert(<boolean>,
-- label), or after a statement that must fail (run at top level between \set ON_ERROR_STOP off / on) t_refused(label,
-- :'SQLSTATE', :'LAST_ERROR_MESSAGE', <state>, <message LIKE>). Every id is generated; every actor is a PostgREST-shaped
-- session; message ids carry a run tag. Needs: stubs (or the contract's live-shaped tables), M1a, M1w. Fixture rows
-- (profiles, vehicles, vehicle_images, and the column changes live merge_into_primary / unmerge_vehicle make) are
-- written by the admin session. The R1 race needs two sessions: it is race_r1.sh (contract-adjacent), not a check here.
-- Cases: R2 verify-R2/r2_merge_unmoved; F1 verify-F1/f1 (A); M2 money-ship-v10/m5 (cover_many, cover_rejected);
-- F2 verify-F2/f2; R3 answers-trucks-v10/r3_question_key [d]; M1 money-ship-v10/k2_conflict (D).
-- ALLOW_RAW_TESTIMONY_WRITE (fixture rows in the stub tables of a throwaway database)
\set ON_ERROR_STOP on
\pset pager off
\pset format unaligned
\pset tuples_only on
SET client_min_messages = notice;
\set VERBOSITY terse
RESET ROLE; RESET SESSION AUTHORIZATION;
-- (scenario_v11.sql defines t_assert and t_refused here; the template's, with the same signatures, are used)

SELECT replace(gen_random_uuid()::text, '-', '') AS tag \gset
SELECT gen_random_uuid() AS ua, gen_random_uuid() AS sa, gen_random_uuid() AS v1, gen_random_uuid() AS v3,
       gen_random_uuid() AS vf, gen_random_uuid() AS vw, gen_random_uuid() AS vb, gen_random_uuid() AS vc,
       gen_random_uuid() AS pa, gen_random_uuid() AS pb, gen_random_uuid() AS pm, gen_random_uuid() AS iq \gset
SELECT auth.t_seed_session(:'sa', :'ua');
\set JOB 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE service_role; SET request.jwt.claim.role = ''service_role''; RESET request.jwt.claim.sub; SET request.jwt.claims = ''{"role":"service_role"}'';'
\set OWNER 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; SET request.jwt.claim.sub = ''' :ua '''; SET request.jwt.claims = ''{"sub":"' :ua '","role":"authenticated","aal":"aal2","session_id":"' :sa '","amr":[{"method":"totp","timestamp":1700000100}]}'';'
\set ADMIN 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET request.jwt.claim.role; RESET request.jwt.claim.sub; RESET request.jwt.claims;'
:ADMIN
INSERT INTO public.profiles(id) VALUES (:'ua');
INSERT INTO public.vehicles(id, owner_id) VALUES (:'v1', :'ua'), (:'v3', :'ua'), (:'vf', :'ua'), (:'vw', :'ua'), (:'vb', :'ua'), (:'vc', :'ua');
-- PA is filed on V3 from the start; PB and PM on V1; IQ is unfiled (the re-ask rows)
INSERT INTO public.vehicle_images(id, vehicle_id, user_id, taken_at) VALUES
  (:'pa', :'v3', :'ua', '2024-06-10 18:00+00'), (:'pb', :'v1', :'ua', '2024-06-11 18:00+00'),
  (:'pm', :'v1', :'ua', '2024-06-12 18:00+00'), (:'iq', NULL, :'ua', '2024-06-13 18:00+00');
:JOB
SELECT public.evidence_open_run(:'ua','pilot','loop','script:v11','sha','{}') AS loop \gset
SELECT public.evidence_open_run(:'ua','pilot','combined','script:v11','sha','{}','{}',NULL,NULL,:'loop') AS rc \gset
SELECT public.evidence_open_run(:'ua','pilot','deal_document','script:v11','sha','{}') AS rd \gset
SELECT public.evidence_open_run(:'ua','pilot','ledger_vendor_date','script:v11','sha','{"coverage_to":"2025-12-31","covers_accounts":["bank_account:v11.main"]}') AS rl \gset

-- ------------------------------------------------------------------------------------------------ V11-1 (R1)
:ADMIN
SELECT t_assert((SELECT position('PERFORM 1 FROM image_capture_time_claims' in p.prosrc) BETWEEN 1 AND position('(v9, W1) the instant he rejected' in p.prosrc)
                   FROM pg_proc p WHERE p.oid = 'public.propose_capture_time_claims(uuid,jsonb)'::regprocedure),
  'V11-1 R1: a capture-time proposal takes the photo''s current claim lock before its day check (the race itself: race_r1.sh)');

-- ------------------------------------------------------------------------------------------------ V11-2 (R2)
-- V1 is merged into V3 as live merge_into_primary does: PM moves to V3 stamped merged_from V1; PB stays on V1 (the
-- survivor already holds its file); PA was on V3 all along. A pass names V1 for PA and the survivor V3 for PB and PM.
:ADMIN
UPDATE public.vehicle_images SET merged_from_vehicle_id = :'v1', vehicle_id = :'v3' WHERE id = :'pm';
UPDATE public.vehicles SET merged_into_vehicle_id = :'v3', deleted_at = now(), status = 'merged' WHERE id = :'v1';
:JOB
SELECT public.propose_image_candidates(:'rc', ('[' ||
  '{"image_id":"' || :'pa' || '","vehicle_id":"' || :'v1' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-10"},' ||
  '{"image_id":"' || :'pb' || '","vehicle_id":"' || :'v3' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-11"},' ||
  '{"image_id":"' || :'pm' || '","vehicle_id":"' || :'v3' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-12"}]')::jsonb)->>'proposed' AS r2_n \gset
SELECT (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'pa' AND superseded_by IS NULL) AS ca,
       (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'pb' AND superseded_by IS NULL) AS cb,
       (SELECT id FROM public.image_vehicle_candidates WHERE image_id = :'pm' AND superseded_by IS NULL) AS cm \gset
SELECT t_assert(:'r2_n' = '3'
                AND (SELECT vehicle_id FROM public.image_vehicle_candidates WHERE id = :'ca') = :'v3'
                AND (SELECT vehicle_id FROM public.image_vehicle_candidates WHERE id = :'cb') = :'v1'
                AND (SELECT vehicle_id FROM public.image_vehicle_candidates WHERE id = :'cm') = :'v1'
                AND (SELECT evidence @> jsonb_build_array(jsonb_build_object('kind','named_by_pass','id',:'v1')) FROM public.image_vehicle_candidates WHERE id = :'ca'),
  'V11-2 R2: each candidate stores the row its photo is filed on (or was moved from), whatever id of the truck the pass named');
:OWNER
SELECT public.decide_evidence('image_candidate', ARRAY[:'ca']::uuid[], 'confirmed', 'yes', 'app:v11-2a', 'owner_app', NULL, jsonb_build_object(:'ca', :'v3'))->'items'->0->>'result' AS r2_a \gset
SELECT public.decide_evidence('image_candidate', ARRAY[:'cb']::uuid[], 'confirmed', 'yes', 'app:v11-2b', 'owner_app', NULL, jsonb_build_object(:'cb', :'v1'))->'items'->0->>'result' AS r2_b \gset
SELECT public.decide_evidence('image_candidate', ARRAY[:'cm']::uuid[], 'confirmed', 'yes', 'app:v11-2m', 'owner_app', NULL, jsonb_build_object(:'cm', :'v3'))->'items'->0->>'result' AS r2_m \gset
-- the live unmerge returns the photos the merge moved
:ADMIN
UPDATE public.vehicle_images SET vehicle_id = :'v1', merged_from_vehicle_id = NULL WHERE vehicle_id = :'v3' AND merged_from_vehicle_id = :'v1';
UPDATE public.vehicles SET status = 'active', merged_into_vehicle_id = NULL, deleted_at = NULL WHERE id = :'v1';
:JOB
SELECT public.evidence_open_run(:'ua','pilot','combined','script:v11','sha2','{}','{}',NULL,NULL,:'loop') AS rc2 \gset
SELECT public.propose_image_candidates(:'rc2', ('[' ||
  '{"image_id":"' || :'pa' || '","vehicle_id":"' || :'v3' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-10"},' ||
  '{"image_id":"' || :'pb' || '","vehicle_id":"' || :'v1' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-11"},' ||
  '{"image_id":"' || :'pm' || '","vehicle_id":"' || :'v1' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-12"}]')::jsonb) AS r2_after \gset
:OWNER
SELECT t_assert(:'r2_a' = 'confirmed' AND :'r2_b' = 'confirmed' AND :'r2_m' = 'confirmed'
                AND (SELECT bool_and(i->>'result' = 'already_decided') FROM jsonb_array_elements(:'r2_after'::jsonb->'items') i)
                AND (SELECT string_agg(day::text, ',' ORDER BY day) FROM public.get_vehicle_day_records(:'v1', NULL, NULL, :'ua') WHERE own_photos_confirmed > 0) = '2024-06-11,2024-06-12'
                AND (SELECT string_agg(day::text, ',' ORDER BY day) FROM public.get_vehicle_day_records(:'v3', NULL, NULL, :'ua') WHERE own_photos_confirmed > 0) = '2024-06-10',
  'V11-2 R2: after the unmerge each yes stays on the truck the photo is filed on, and the next pass on that truck finds it (already_decided)');

-- ------------------------------------------------------------------------------------------------ V11-3, V11-4 (F1, M2)
-- verify-F1 case A: he says who paid claim k0 (650000); the pass's corrected reading is a second claim k1 (680000), which
-- he answers too; the bank line of the deal is keyed on the truck
:JOB
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'vf','claim_domain','custody','kind','acquisition','occurred_from','2024-03-01',
  'occurred_to','2024-03-05','amount_cents',650000,'summary','bought','confidence',0.8), '[]'::jsonb) AS k0 \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v11','sha', jsonb_build_object('sheet_sha256','v11-k0','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','change_claim','id',:'k0')))))) AS sk0 \gset
SELECT public.evidence_close_run(:'sk0', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'sk0', 'v11:k0-' || :'tag', '{"1":{"verbatim":"I paid","answer":{"decision":"confirmed","entity_key":"owner"}}}'::jsonb, 'script:v11', 'sha', clock_timestamp()) AS ak0 \gset
:OWNER
SELECT public.decide_evidence('change_claim', ARRAY[:'k0']::uuid[], 'confirmed', 'I paid', 'review:' || :'sk0' || '#1', 'owner_app', NULL, NULL, NULL, NULL,
  'answers:' || :'ak0' || '#1', '{"entity_key":"owner"}'::jsonb)->'items'->0->>'result' AS wk0 \gset
:JOB
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'vf','claim_domain','custody','kind','acquisition','occurred_from','2024-03-01',
  'occurred_to','2024-03-05','amount_cents',680000,'summary','bought (page 2)','confidence',0.9), '[]'::jsonb) AS k1 \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v11','sha', jsonb_build_object('sheet_sha256','v11-k1','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','change_claim','id',:'k1')))))) AS sk1 \gset
SELECT public.evidence_close_run(:'sk1', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'sk1', 'v11:k1-' || :'tag', '{"1":{"verbatim":"I paid","answer":{"decision":"confirmed","entity_key":"owner"}}}'::jsonb, 'script:v11', 'sha', clock_timestamp()) AS ak1 \gset
:OWNER
SELECT public.decide_evidence('change_claim', ARRAY[:'k1']::uuid[], 'confirmed', 'I paid', 'review:' || :'sk1' || '#1', 'owner_app', NULL, NULL, NULL, NULL,
  'answers:' || :'ak1' || '#1', '{"entity_key":"owner"}'::jsonb)->'items'->0->>'result' AS wk1 \gset
:JOB
SELECT public.propose_evidence_links(:'rl', ('[{"vehicle_id":"' || :'vf' || '","source_kind":"bank_line","external_ref":"bank:v11-f1","occurred_on":"2024-03-04","direction":"out","amount_cents":680000,"role":"payment_out","payment_key":"bank:v11-f1","cost_category":"purchase","from_account_ref":"bank_account:v11.main","join_key":"x","confidence":0.9,"evidence":[{"kind":"bank"}]}]')::jsonb)->'items'->0->>'link_id' AS lf \gset
:OWNER
SELECT public.vehicle_accounting_evidence(:'vf') AS f_both \gset
SELECT t_assert(:'wk0' = 'statement_recorded' AND :'wk1' = 'statement_recorded'
                AND (SELECT count(*) FROM jsonb_array_elements(:'f_both'::jsonb->'stated'->'statements') s WHERE (s->>'counts')::boolean) = 2
                AND (SELECT count(*) FROM jsonb_array_elements(:'f_both'::jsonb->'stated'->'statements') s WHERE (s->>'covered_cents')::bigint > 0) = 1
                AND (SELECT (s->>'covered_cents')::bigint FROM jsonb_array_elements(:'f_both'::jsonb->'stated'->'statements') s WHERE s->'answers'->>'id' = :'k0') = 650000
                AND EXISTS (SELECT 1 FROM jsonb_array_elements(:'f_both'::jsonb->'open_questions') q WHERE q->>'q' = 'acquisition_conflict'),
  'V11-4 M2: one payment that fits two counting statements covers only one of them (the older), while the conflict is open');
-- he answers the conflict: k0 was the misread
SELECT public.decide_evidence('change_claim', ARRAY[:'k0']::uuid[], 'rejected', 'page 2 is right', 'app:v11-3', 'owner_app')->'items'->0->>'result' AS k0_no \gset
SELECT public.vehicle_accounting_evidence(:'vf') AS f_after \gset
SELECT t_assert(:'k0_no' = 'rejected'
                AND NOT (:'f_after'::jsonb->'stated' ? 'cents_out') AND NOT (:'f_after'::jsonb->'stated' ? 'cents_in')
                AND (SELECT NOT (s->>'counts')::boolean AND s->'answers'->>'status' = 'rejected' AND (s->>'covered_cents')::bigint = 0
                       FROM jsonb_array_elements(:'f_after'::jsonb->'stated'->'statements') s WHERE s->'answers'->>'id' = :'k0')
                AND (SELECT (s->>'counts')::boolean AND (s->>'covered_cents')::bigint = 680000 AND s->'covered_by' = '["bank:v11-f1"]'::jsonb
                       FROM jsonb_array_elements(:'f_after'::jsonb->'stated'->'statements') s WHERE s->'answers'->>'id' = :'k1')
                AND (SELECT sum((v->>'cents')::bigint) FROM jsonb_each(:'f_after'::jsonb->'costs') x(k, v) WHERE v ? 'payments') = 680000
                AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(:'f_after'::jsonb->'open_questions') q WHERE q->>'q' IN ('acquisition_conflict','who_paid')),
  'V11-3 F1: after he rejects k0, its statement is listed as not counting and covers nothing; the bank line covers k1''s statement; no total of statements');
-- he says the bank line is not this truck's
SELECT public.decide_evidence('evidence_link', ARRAY[:'lf']::uuid[], 'rejected', 'not this truck', 'app:v11-4', 'owner_app')->'items'->0->>'result' AS lf_no \gset
SELECT public.vehicle_accounting_evidence(:'vf') AS f_rej \gset
SELECT t_assert(:'lf_no' = 'rejected'
                AND (SELECT bool_and((s->>'covered_cents')::bigint = 0) FROM jsonb_array_elements(:'f_rej'::jsonb->'stated'->'statements') s)
                AND coalesce((SELECT sum((v->>'cents')::bigint) FROM jsonb_each(:'f_rej'::jsonb->'costs') x(k, v) WHERE v ? 'payments'), 0) = 0,
  'V11-4 M2: a keyed payment he rejected covers nothing');

-- ------------------------------------------------------------------------------------------------ V11-5 (F2)
-- a claim whose window is several days (its statement has no date of its own) and a receipt with no date at all
:JOB
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'vw','claim_domain','custody','kind','acquisition','occurred_from','2024-03-01',
  'occurred_to','2024-03-09','amount_cents',500000,'summary','bought','confidence',0.8), '[]'::jsonb) AS kw \gset
SELECT public.propose_evidence_links(:'rl', ('[{"vehicle_id":"' || :'vw' || '","source_kind":"receipt","external_ref":"receipt:v11-nd","direction":"out","amount_cents":12000,"role":"payment_out","cost_category":"parts","join_key":"x","confidence":0.9,"evidence":[{"kind":"receipt"}]}]')::jsonb)->'items'->0->>'link_id' AS lw \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v11','sha', jsonb_build_object('sheet_sha256','v11-w','items',2,'rows',jsonb_build_object(
  '1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','change_claim','id',:'kw'))),
  '2', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','evidence_link','id',:'lw')))))) AS sw \gset
SELECT public.evidence_close_run(:'sw', 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT public.evidence_record_answers(:'ua', :'sw', 'v11:w-' || :'tag', '{"1":{"verbatim":"I paid","answer":{"decision":"confirmed","entity_key":"owner"}},"2":{"verbatim":"me","answer":{"decision":"confirmed","entity_key":"owner"}}}'::jsonb, 'script:v11', 'sha', clock_timestamp()) AS aw \gset
:OWNER
SELECT public.decide_evidence('change_claim', ARRAY[:'kw']::uuid[], 'confirmed', 'I paid', 'review:' || :'sw' || '#1', 'owner_app', NULL, NULL, NULL, NULL,
  'answers:' || :'aw' || '#1', '{"entity_key":"owner"}'::jsonb)->'items'->0->>'result' AS ww1 \gset
SELECT public.decide_evidence('evidence_link', ARRAY[:'lw']::uuid[], 'confirmed', 'I paid', 'review:' || :'sw' || '#2', 'owner_app', NULL, NULL, NULL, NULL,
  'answers:' || :'aw' || '#2', '{"entity_key":"owner"}'::jsonb)->'items'->0->>'result' AS ww2 \gset
SELECT public.vehicle_accounting_evidence(:'vw') AS w_all \gset
SELECT public.vehicle_accounting_evidence(:'vw', '2024-01-01', '2024-12-31') AS w_2024 \gset
SELECT public.vehicle_accounting_evidence(:'vw', '2025-01-01', '2025-12-31') AS w_2025 \gset
SELECT t_assert(:'ww1' = 'statement_recorded' AND :'ww2' = 'statement_recorded'
                AND jsonb_array_length(:'w_all'::jsonb->'stated'->'statements') = 2 AND jsonb_array_length(:'w_all'::jsonb->'stated'->'undated') = 0
                AND (SELECT s->'answers'->>'on' FROM jsonb_array_elements(:'w_all'::jsonb->'stated'->'statements') s WHERE s->'answers'->>'id' = :'kw') = '2024-03-09'
                AND jsonb_array_length(:'w_2024'::jsonb->'stated'->'statements') = 1
                AND (:'w_2024'::jsonb->'stated'->'statements'->0->'answers'->>'id') = :'kw'
                AND jsonb_array_length(:'w_2024'::jsonb->'stated'->'undated') = 1
                AND (:'w_2024'::jsonb->'stated'->'undated'->0->'answers'->>'id') = :'lw'
                AND jsonb_array_length(:'w_2025'::jsonb->'stated'->'statements') = 0
                AND jsonb_array_length(:'w_2025'::jsonb->'stated'->'undated') = 1,
  'V11-5 F2: a statement is dated by what it answers and listed only in the windows that hold that date; one with no date at all is under stated.undated in every windowed read');

-- ------------------------------------------------------------------------------------------------ V11-6 (R3)
:JOB
SELECT public.propose_image_candidates(:'rc', ('[{"image_id":"' || :'iq' || '","vehicle_id":"' || :'vb' || '","verdict":"is_vehicle","join_key":"x","confidence":0.9,"evidence":[{"kind":"x"}],"pass_captured_on":"2024-06-13"}]')::jsonb)->'items'->0->>'candidate_id' AS cq \gset
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v11','sha', jsonb_build_object('sheet_sha256','v11-q','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','image_candidate','id',:'cq')))))) AS sq \gset
SELECT public.evidence_close_run(:'sq', 'done', '{}'::jsonb);
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v11','sha', jsonb_build_object('sheet_sha256','v11-q2','items',1,'rows',jsonb_build_object(
  '1', jsonb_build_object('reask_of', 'review:' || :'sq' || '#1')))) AS sq2 \gset
SELECT public.evidence_close_run(:'sq2', 'done', '{}'::jsonb);
\set ON_ERROR_STOP off
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v11','sha', jsonb_build_object('sheet_sha256','v11-q3','items',2,'rows',jsonb_build_object(
  '1', jsonb_build_object('reask_of', 'review:' || :'sq' || '#1'), '2', jsonb_build_object('reask_of', 'review:' || :'sq' || '#1'))));
\set ON_ERROR_STOP on
SELECT t_refused('V11-6 R3: a sheet that re-asks one row twice is refused', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'a sheet asks a question once%');
\set ON_ERROR_STOP off
SELECT public.evidence_open_run(:'ua','review','review_sheet','script:v11','sha', jsonb_build_object('sheet_sha256','v11-q4','items',2,'rows',jsonb_build_object(
  '1', jsonb_build_object('reask_of', 'review:' || :'sq' || '#1'), '2', jsonb_build_object('reask_of', 'review:' || :'sq2' || '#1'))));
\set ON_ERROR_STOP on
SELECT t_refused('V11-6 R3: so is a sheet that re-asks a row and a re-ask of it (one first asking)', :'SQLSTATE', :'LAST_ERROR_MESSAGE', '22023', 'a sheet asks a question once%');

-- ------------------------------------------------------------------------------------------------ V11-7 (M1)
:JOB
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'vb','claim_domain','custody','kind','acquisition','occurred_from','2023-02-01',
  'occurred_to','2023-02-01','amount_cents',400000,'summary','bought','confidence',0.8), '[]'::jsonb) AS kb1 \gset
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'vb','claim_domain','custody','kind','sale','occurred_from','2024-01-10',
  'occurred_to','2024-01-10','amount_cents',450000,'summary','sold','confidence',0.8), '[]'::jsonb) AS kbs \gset
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'vb','claim_domain','custody','kind','acquisition','occurred_from','2025-02-01',
  'occurred_to','2025-02-01','amount_cents',380000,'summary','bought back','confidence',0.8), '[]'::jsonb) AS kb2 \gset
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'vc','claim_domain','custody','kind','acquisition','occurred_from','2025-02-01',
  'occurred_to','2025-02-01','amount_cents',380000,'summary','bought','confidence',0.8), '[]'::jsonb) AS kc1 \gset
SELECT public.propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'vc','claim_domain','custody','kind','acquisition','occurred_from','2025-02-20',
  'occurred_to','2025-02-20','amount_cents',385000,'summary','bought (deal sheet)','confidence',0.8), '[]'::jsonb) AS kc2 \gset
:OWNER
SELECT t_assert(NOT EXISTS (SELECT 1 FROM jsonb_array_elements(public.vehicle_accounting_evidence(:'vb')->'open_questions') q WHERE q->>'q' = 'acquisition_conflict')
                AND EXISTS (SELECT 1 FROM jsonb_array_elements(public.vehicle_accounting_evidence(:'vc')->'open_questions') q
                             WHERE q->>'q' = 'acquisition_conflict' AND q->'claim_ids' = (SELECT jsonb_agg(x ORDER BY x) FROM (VALUES (:'kc1'::uuid), (:'kc2'::uuid)) v(x))),
  'V11-7 M1: bought, sold and bought back is not a conflict; two purchases 19 days apart are');

-- ------------------------------------------------------------------------------------------------ V11-8 (shape)
SELECT t_assert((SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(public.vehicle_accounting_evidence(:'vf')->'stated') k) = ARRAY['statements','undated']
                AND (SELECT bool_and(s ? 'counts' AND s->'answers' ? 'on' AND s->'answers' ? 'status' AND s->'answers' ? 'current' AND s ? 'covered_cents')
                       FROM jsonb_array_elements(public.vehicle_accounting_evidence(:'vf')->'stated'->'statements') s),
  'V11-8 shape: stated holds two lists (statements, undated) and no total; each statement carries counts and the status, currency and date of what it answers');
SELECT t_assert((SELECT count(*) FROM public.evidence_decisions WHERE decided_by LIKE 'agent:%') = 0, 'V11 end: no agent decision exists');
\echo 'scenario_v11: all checks passed'

-- (re-check of v11, G1) V11-1 above tests only that the lock statement comes before the day check; with its
-- FOR UPDATE dropped it still passes and the race reopens. The re-checker's tighter check also requires the lock:
SELECT t_assert((SELECT position('PERFORM 1 FROM image_capture_time_claims' in p.prosrc) BETWEEN 1 AND position('(v9, W1) the instant he rejected' in p.prosrc)
                        AND p.prosrc ~ 'PERFORM 1 FROM image_capture_time_claims\s+WHERE image_id = \(x->>''image_id''\)::uuid AND user_id = r\.user_id AND superseded_by IS NULL FOR UPDATE;'
                   FROM pg_proc p WHERE p.oid = 'public.propose_capture_time_claims(uuid,jsonb)'::regprocedure),
  'V11-1 R1 (tight): the capture-time proposal locks the photo''s current claim (FOR UPDATE) before its day check');
RESET ROLE; RESET SESSION AUTHORIZATION;
\pset format aligned
\pset tuples_only off
SELECT coalesce(nullif(current_setting('t.passed', true), ''), '0') AS g_passed \gset
SELECT t_assert(:g_passed = 13, 'group v11: every one of its 13 checks ran and passed');
\echo 'group v11: 13 checks passed'
SELECT :passed_total + :g_passed + 1 AS passed_total \gset
