-- the job session: runs, one review sheet of 60 rows and the owner's stored answers to it
:JOB
SELECT evidence_open_run(:'U','pilot','loop','script:loop','sha','{"price_usd_per_input_token":0}') AS loop \gset
SELECT evidence_open_run(:'U','pilot','combined','script:combine','sha','{}','{}',NULL,NULL,:'loop') AS r_comb \gset
SELECT evidence_open_run(:'U','pilot','photos_album','script:album','sha','{}','{}',NULL,NULL,:'loop') AS r_alb \gset
SELECT evidence_open_run(:'U','pilot','audit_sample','script:audit','sha','{}','{}',NULL,NULL,:'loop') AS r_aud \gset
SELECT evidence_open_run(:'U','pilot','ledger_vendor_date','script:ledger','sha','{}','{}',NULL,NULL,:'loop') AS r_led \gset
SELECT evidence_open_run(:'U','pilot','pnl_allocation','script:pnl','sha','{}','{}',NULL,NULL,:'loop') AS r_pnl \gset
SELECT evidence_open_run(:'U','pilot','messages_mention','script:messages','sha','{}','{}',NULL,NULL,:'loop') AS r_msg \gset
SELECT evidence_open_run(:'U','pilot','gmail_order','script:gmail','sha','{}','{}',NULL,NULL,:'loop') AS r_gm \gset
SELECT evidence_open_run(:'U','pilot','deal_document','script:deal','sha','{}','{}',NULL,NULL,:'loop') AS r_deal \gset
SELECT evidence_open_run(:'U','pilot','account_map','script:accounts','sha','{}','{}',NULL,NULL,:'loop') AS r_acct \gset
\set LAST_ERROR_SQLSTATE none
\set ON_ERROR_STOP off
SELECT evidence_open_run(:'U','pilot','owner_review','script:answers','sha','{}','{}',NULL,NULL,:'loop') AS r_own \gset
\set ON_ERROR_STOP on
\set t_state :SQLSTATE
SELECT t_refused($l$human scenario_h.sql:127 === T1c retire cannot be called outside promotion, even by the owner role (expect ERROR 42501)$l$, :'LAST_ERROR_SQLSTATE', :'LAST_ERROR_MESSAGE', $s$42501$s$, $p$owner_answer_missing: owner_review rows are written only by his own decisions (decide_evidence), never by a job run$p$);
\set SQLSTATE :t_state
\set ERROR true
SELECT evidence_open_run(:'U','pilot','identity_compare','script:identity','sha','{}','{}',NULL,NULL,:'loop') AS r_id \gset
SELECT evidence_open_run(:'U','pilot','time_offset','script:time','sha','{}','{}',NULL,NULL,:'loop') AS r_time \gset
SELECT evidence_open_run(:'U','pilot','promote','script:promote','sha','{}','{}',NULL,NULL,:'loop') AS r_prom \gset
SELECT evidence_open_run(:'U','review','review_sheet','script:review','sha',(SELECT jsonb_build_object('sheet_sha256','abc','items',60,'rows',jsonb_object_agg(g::text, jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','change_claim','id',gen_random_uuid()))))) FROM generate_series(1,60) g)) AS rev \gset
