-- ================================================================================================ group guard
-- the guard cases S0-S11 and SG1-SG4 with the writers present (S5 and S7: agent_channel_disabled)
SELECT left(:'main_db', 48) || '_guard' AS grp_db \gset
DROP DATABASE IF EXISTS :"grp_db" WITH (FORCE);
CREATE DATABASE :"grp_db" TEMPLATE :"tmpl_db" STRATEGY FILE_COPY;   -- a file copy, not the whole template through WAL
\c :grp_db
SET TimeZone = 'America/Los_Angeles'; SET DateStyle = 'ISO, MDY';
\set ON_ERROR_STOP on
-- the owner sessions this group uses, in the auth server's records
SELECT auth.t_seed_session('270f15dd-0000-4000-8000-0000000005e5', '6194674c-0000-4000-8000-000000000066', 'ok');
-- ---------------------------------------------------------------------------- scenario_guard_v4.sql
-- v9_adapt: evidence_record_answers takes p_message_at; a sheet is closed done (sent) before answers are stored (by hand here: v9_adapt.py does not parse $d$ quoting)
-- v6_adapt applied (see v6_adapt.py)
-- Local scratch only. Database simns: every block was applied AS dm_contract_evidence_owner, a non-superuser login that owns the objects,
-- as postgres does live. Sessions (superuser harness, emulating the live logins):
--   JOB    = PostgREST with the service-role key: session_user authenticator, SET ROLE service_role, JWT role claim.
--   OWNER  = PostgREST with the owner's JWT (role authenticated).
--   QSH    = the q.sh login: session_user dm_contract_evidence_owner (non-superuser owner), no API role.
--   QSH_R  = the live q.sh state after its own `SET session_replication_role = replica` (allowed live by supautils;
--            emulated: the superuser sets it, then becomes dm_contract_evidence_owner).
-- The attacks are those of sql-apply v3 (S1-S11) and rules-violation v3 (objection 1); every forged write must fail.
\pset pager off
\pset format unaligned
\pset tuples_only on
SET client_min_messages = warning;
\set U6 '6194674c-0000-4000-8000-000000000066'
\set V6 '6626f6fc-0000-4000-8000-000000000001'
\set J1 '000873b0-0000-4000-8000-0000000006a1'
\set J2 '000873b0-0000-4000-8000-0000000006a2'
\set JOB 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET session_replication_role; SET SESSION AUTHORIZATION authenticator; SET ROLE service_role; SET request.jwt.claim.role = ''service_role''; RESET request.jwt.claim.sub; RESET evidence.writer; RESET request.jwt.claims;'
\set OWNER 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET session_replication_role; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; SET request.jwt.claim.sub = ''6194674c-0000-4000-8000-000000000066''; RESET evidence.writer; SET request.jwt.claims = ''{"aal":"aal2","session_id":"270f15dd-0000-4000-8000-0000000005e5","amr":[{"method":"password","timestamp":1},{"method":"totp","timestamp":2}]}'';'
\set QSH 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET session_replication_role; RESET request.jwt.claim.role; RESET request.jwt.claim.sub; SET SESSION AUTHORIZATION dm_contract_evidence_owner; RESET request.jwt.claims;'
\set QSH_R 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET request.jwt.claim.role; RESET request.jwt.claim.sub; SET session_replication_role = replica; SET SESSION AUTHORIZATION dm_contract_evidence_owner; RESET request.jwt.claims;'
\set ADMIN 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET session_replication_role; RESET request.jwt.claim.role; RESET request.jwt.claim.sub; RESET evidence.writer; RESET request.jwt.claims;'

:ADMIN
