CREATE OR REPLACE FUNCTION public.zz_row(i text, v text, k text, f text, d text) RETURNS jsonb LANGUAGE sql AS $$
  SELECT jsonb_strip_nulls(jsonb_build_object('image_id',i,'vehicle_id',v,'subject_key',k,'verdict','is_vehicle','frame_role',f,'join_key','x',
         'confidence',0.9,'evidence','[{"kind":"x"}]'::jsonb,'pass_captured_on',d)) $$;
