CREATE OR REPLACE FUNCTION public.zz_show(i text) RETURNS text LANGUAGE sql AS $$
  SELECT string_agg(r.pass || ':' || r.frame_role || ':' || coalesce(right(r.vehicle_id::text,3), r.subject_key) || '=' || r.status
                    || '/view=' || coalesce((SELECT v.status FROM v_image_candidates_current v WHERE v.id = r.id), '?')
                    || '/fn=' || coalesce(evidence_candidate_status(r.id), '?'), ', ' ORDER BY r.pass, r.frame_role, r.vehicle_id)
    FROM evidence_candidates_for_images(ARRAY[i::uuid], '9490fc96-0000-4000-8000-0000000000a8') r $$;
