-- Actors as PostgREST makes them (session authenticator + role setting + request.jwt.claims). Included by every r*.sql.
\pset pager off
\pset format unaligned
\pset tuples_only on
SET client_min_messages = warning;
\set UA '9490fc96-0000-4000-8000-0000000000a8'
\set UB '962bbddf-0000-4000-8000-0000000000b8'
\set VA '9490fc96-0000-4000-8000-000000000001'
\set VS '9490fc96-0000-4000-8000-000000000002'
\set VB '962bbddf-0000-4000-8000-000000000001'
\set I1 '000873b0-0000-4000-8000-000000000f01'
\set I2 '000873b0-0000-4000-8000-000000000f02'
\set I3 '000873b0-0000-4000-8000-000000000f03'
\set IB '000873b0-0000-4000-8000-000000000fb1'
\set JOB 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE service_role; SET request.jwt.claim.role = ''service_role''; RESET request.jwt.claim.sub; RESET request.jwt.claims;'
\set OWNERA 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; SET request.jwt.claim.sub = ''9490fc96-0000-4000-8000-0000000000a8''; SET request.jwt.claims = ''{"aal":"aal2","session_id":"3bb3c76e-0000-4000-8000-000000000ea8","amr":[{"method":"totp","timestamp":1700000100}]}'';'
\set USERB1 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; SET request.jwt.claim.sub = ''962bbddf-0000-4000-8000-0000000000b8''; SET request.jwt.claims = ''{"aal":"aal1","session_id":"2dc2a0ab-0000-4000-8000-000000000003"}'';'
\set USERB2 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; SET request.jwt.claim.sub = ''962bbddf-0000-4000-8000-0000000000b8''; SET request.jwt.claims = ''{"aal":"aal2","session_id":"3bb3c76e-0000-4000-8000-000000000fb8","amr":[{"method":"totp","timestamp":2}]}'';'
\set ADMIN 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET request.jwt.claim.role; RESET request.jwt.claim.sub; RESET request.jwt.claims;'
:ADMIN
