SELECT evidence_open_run(:'UA','pilot','deal_document','script:deal','sha','{}') AS rd \gset
SELECT evidence_open_run(:'UA','pilot','ledger_vendor_date','script:ledger','sha','{"coverage_to":"2025-12-31","covers_accounts":["bank_account:w.main"]}') AS rl \gset
\echo '=== 1. deposit + balance: two keyed purchase lines (200000 + 600000) placed on the truck; he said he paid 800000'
:JOB
SELECT propose_change_claim(:'rd', jsonb_build_object('vehicle_id',:'V1','claim_domain','custody','kind','acquisition','occurred_from','2024-01-10','occurred_to','2024-01-18','amount_cents',800000,'summary','deal','confidence',0.8), '[]'::jsonb) AS k1 \gset
:JOB
SELECT evidence_open_run(:'UA','review','review_sheet','script:review','sha', jsonb_build_object('sheet_sha256','s1','items',1,'rows',jsonb_build_object('1', jsonb_build_object('asks','party','targets', jsonb_build_array(jsonb_build_object('kind','change_claim','id',:'k1')))))) AS s1 \gset
SELECT evidence_close_run(:'s1', 'done', '{}'::jsonb) \g /dev/null
SELECT evidence_record_answers(:'UA', :'s1', 'chat:m1', jsonb_build_object('1', jsonb_build_object('verbatim','I paid', 'answer', jsonb_build_object('decision','confirmed','entity_key','owner'))), 'script:answers', 'sha', clock_timestamp()) AS a1 \gset
:OWNERA
\o :outf
SELECT '    who-paid on k1: ' || (decide_evidence('change_claim', ARRAY[:'k1']::uuid[], 'confirmed', 'I paid', 'review:'||:'s1'||'#1', 'owner_app', NULL, NULL, NULL, NULL, 'answers:'||:'a1'||'#1', '{"entity_key":"owner"}'::jsonb)->'items'->0->>'result');
\o
\set got `cat :outf`
