-- ================================================================================================ group rp1
-- the R-P1 bound (2,000 answered rows x 2,000 decisions; the confirmation reader under 2 s)
SELECT left(:'main_db', 48) || '_rp1' AS grp_db \gset
DROP DATABASE IF EXISTS :"grp_db" WITH (FORCE);
CREATE DATABASE :"grp_db" TEMPLATE :"tmpl_db" STRATEGY FILE_COPY;   -- a file copy, not the whole template through WAL
\c :grp_db
SET TimeZone = 'America/Los_Angeles'; SET DateStyle = 'ISO, MDY';
\set ON_ERROR_STOP on

-- R-P1: 2,000 candidates, four review sheets of 500 rows sent and answered (evidence_record_answers), then 2,000
-- decisions in the owner's own session (decide_evidence, 200 per call); evidence_answers_to_confirm read in his session
-- and as the job, under 2 s (design sim: 0.25-0.26 s; the defect R-P1 was raised against took 22 s).
\pset format unaligned
\pset tuples_only on
SET client_min_messages = warning;
SET jit = off; SET random_page_cost = 1.1; SET work_mem = '12MB'; SET effective_cache_size = '6GB'; SET max_parallel_workers_per_gather = 1;
SELECT gen_random_uuid() AS ua, gen_random_uuid() AS va, gen_random_uuid() AS sa \gset
SELECT auth.t_seed_session(:'sa', :'ua');
\set JOB 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE service_role; SET request.jwt.claim.role = ''service_role''; RESET request.jwt.claim.sub; SET request.jwt.claims = ''{"role":"service_role"}'';'
\set OWNERA 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; SET request.jwt.claim.sub = ''' :ua '''; SET request.jwt.claims = ''{"aal":"aal2","session_id":"' :sa '","amr":[{"method":"totp","timestamp":1700000100}]}'';'
\set ADMIN 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET request.jwt.claim.role; RESET request.jwt.claim.sub; RESET request.jwt.claims;'
:ADMIN
INSERT INTO profiles VALUES (:'ua');
INSERT INTO vehicles(id, owner_id, label) VALUES (:'va', :'ua', 'perf truck');
CREATE TABLE fx_rp1_img AS SELECT g, gen_random_uuid() AS id FROM generate_series(1, 2000) g;
INSERT INTO vehicle_images(id, vehicle_id, user_id, taken_at, vision_gate_status, label)
  SELECT id, NULL, :'ua', '2024-01-01 18:00+00'::timestamptz + g * interval '1 hour', 'approved', 'p' FROM fx_rp1_img;
CREATE TABLE fx_rp1_ids (k text PRIMARY KEY, id uuid);
GRANT SELECT ON fx_rp1_img TO service_role;
GRANT ALL ON fx_rp1_ids TO service_role, authenticated;
:JOB
INSERT INTO fx_rp1_ids SELECT 'loop', evidence_open_run(:'ua','pilot','loop','script:loop','sha','{}');
INSERT INTO fx_rp1_ids SELECT 'rc', evidence_open_run(:'ua','pilot','combined','script:combine','sha','{}','{}',NULL,NULL,(SELECT id FROM fx_rp1_ids WHERE k='loop'));
\o :outf
SELECT 'proposed ' || sum((propose_image_candidates((SELECT id FROM fx_rp1_ids WHERE k='rc'), b.rows)->>'proposed')::int) FROM (
  SELECT (i.g - 1) / 500 AS bn, jsonb_agg(jsonb_build_object('image_id', i.id, 'vehicle_id', :'va',
           'verdict','is_vehicle','join_key','x','confidence',0.9,'evidence','[{"kind":"x"}]'::jsonb,
           'pass_captured_on', ('2024-01-01'::date + (i.g / 24))::text)) AS rows
    FROM fx_rp1_img i GROUP BY 1) b;
\o
\set got `cat :outf`
SELECT t_out('R-P1: 2,000 candidates proposed through the writer', :'got', 'proposed 2000');
\o :outf
SELECT count(*) || ' sheets answered' FROM generate_series(1, 4) s
  CROSS JOIN LATERAL (
    SELECT evidence_open_run(:'ua','review','review_sheet','script:review','sha', jsonb_build_object('sheet_sha256','v'||s,'items',500,'rows',
             (SELECT jsonb_object_agg(r::text, jsonb_build_object('targets', jsonb_build_array(jsonb_build_object('kind','image_candidate','id',c.id))))
                FROM generate_series(1, 500) r
                JOIN fx_rp1_img i ON i.g = (s - 1) * 500 + r
                JOIN image_vehicle_candidates c ON c.image_id = i.id AND c.superseded_by IS NULL))) AS sheet) sh
  CROSS JOIN LATERAL (SELECT sh.sheet AS sent FROM (SELECT evidence_close_run(sh.sheet, 'done', '{"sent":"contract"}'::jsonb)) x) snt
  CROSS JOIN LATERAL (
    SELECT evidence_record_answers(:'ua', snt.sent, 'contract-msg:' || s,
             (SELECT jsonb_object_agg(r::text, jsonb_build_object('verbatim','yes','answer',jsonb_build_object('decision','confirmed')))
                FROM generate_series(1, 500) r), 'script:answers', 'sha', now()) AS ans) a;
\o
\set got `cat :outf`
SELECT t_out('R-P1: four sheets of 500 rows sent and answered', :'got', '4 sheets answered');
:ADMIN
\o :outf
SELECT 'candidates ' || (SELECT count(*) FROM image_vehicle_candidates) || ', answers runs ' || (SELECT count(*) FROM evidence_runs WHERE run_kind = 'review_answers');
\o
\set got `cat :outf`
SELECT t_out('R-P1: the store holds 2,000 candidates and four answers runs', :'got', 'candidates 2000, answers runs 4');
SET statement_timeout = '60s';
:OWNERA
SELECT clock_timestamp() AS t0 \gset
\o :outf
SELECT count(*), count(last_decided_at) FROM evidence_answers_to_confirm(NULL);
\o
SELECT round(extract(epoch FROM clock_timestamp() - :'t0'::timestamptz) * 1000) AS dt_ms \gset
\echo 'R-P1, before ANALYZE: 2,000 answered rows before his decisions, evidence_answers_to_confirm in his session:' :dt_ms 'ms'
SELECT t_assert(:dt_ms < 2000, 'R-P1, before ANALYZE: 2,000 answered rows before his decisions, evidence_answers_to_confirm in his session under 2 s');
\set got `cat :outf`
SELECT t_out('R-P1: before his decisions, 2,000 stored answers wait for him', :'got', '2000|0');
\o :outf
SELECT count(*) || ' decide calls, ok ' || count(*) FILTER (WHERE r IS NOT NULL) FROM (
  SELECT decide_evidence('image_candidate', array_agg(c.id), 'confirmed', 'yes', 'app:bulk' || ((rn - 1) / 200), 'owner_app', NULL,
                         jsonb_object_agg(c.id::text, NULL)) r
    FROM (SELECT id, row_number() OVER (ORDER BY image_id) rn FROM image_vehicle_candidates WHERE user_id = :'ua' AND superseded_by IS NULL) c
   GROUP BY (rn - 1) / 200) x;
\o
\set got `cat :outf`
SELECT t_out('R-P1: 2,000 decisions in his own session, 200 per call', :'got', '10 decide calls, ok 10');
:ADMIN
\o :outf
SELECT 'decisions ' || count(*) || ' human ' || count(*) FILTER (WHERE decided_by LIKE 'human:%') FROM evidence_decisions;
\o
\set got `cat :outf`
SELECT t_out('R-P1: every decision is his (human:)', :'got', 'decisions 2000 human 2000');
ANALYZE;
:OWNERA
SELECT clock_timestamp() AS t0 \gset
\o :outf
SELECT count(*), count(last_decided_at) FROM evidence_answers_to_confirm(NULL);
\o
SELECT round(extract(epoch FROM clock_timestamp() - :'t0'::timestamptz) * 1000) AS dt_ms \gset
\echo 'R-P1, after ANALYZE: 2,000 answered rows x 2,000 decisions, evidence_answers_to_confirm in his session:' :dt_ms 'ms'
SELECT t_assert(:dt_ms < 2000, 'R-P1, after ANALYZE: 2,000 answered rows x 2,000 decisions, evidence_answers_to_confirm in his session under 2 s');
\set got `cat :outf`
SELECT t_out('R-P1: after his decisions, each answered row shows its decision (his session)', :'got', '2000|2000');
:JOB
SELECT clock_timestamp() AS t0 \gset
\o :outf
SELECT count(*), count(last_decided_at) FROM evidence_answers_to_confirm(:'ua');
\o
SELECT round(extract(epoch FROM clock_timestamp() - :'t0'::timestamptz) * 1000) AS dt_ms \gset
\echo 'R-P1, after ANALYZE: 2,000 answered rows x 2,000 decisions, evidence_answers_to_confirm as the job:' :dt_ms 'ms'
SELECT t_assert(:dt_ms < 2000, 'R-P1, after ANALYZE: 2,000 answered rows x 2,000 decisions, evidence_answers_to_confirm as the job under 2 s');
\set got `cat :outf`
SELECT t_out('R-P1: after his decisions, each answered row shows its decision (the job, naming him)', :'got', '2000|2000');

RESET ROLE; RESET SESSION AUTHORIZATION;
\pset format aligned
\pset tuples_only off
SELECT coalesce(nullif(current_setting('t.passed', true), ''), '0') AS g_passed \gset
SELECT t_assert(:g_passed = 11, 'group rp1: every one of its 11 checks ran and passed');
\echo 'group rp1: 11 checks passed'
SELECT :passed_total + :g_passed + 1 AS passed_total \gset
\c :main_db
DROP DATABASE :"grp_db" WITH (FORCE);

-- ================================================================================================ group f4x10
-- the F4 bound: one vehicle at 10x the pilot volume (gen_scale.py one 10), every read under 3 seconds before the loaded rows are analyzed and under 1 second after
SELECT left(:'main_db', 48) || '_f4x10' AS grp_db \gset
DROP DATABASE IF EXISTS :"grp_db" WITH (FORCE);
CREATE DATABASE :"grp_db" TEMPLATE :"tmpl_db" STRATEGY FILE_COPY;   -- a file copy, not the whole template through WAL
\c :grp_db
SET TimeZone = 'America/Los_Angeles'; SET DateStyle = 'ISO, MDY';
\set ON_ERROR_STOP on
\pset format unaligned
\pset tuples_only on
SET client_min_messages = warning;
SET jit = off; SET random_page_cost = 1.1; SET work_mem = '12MB'; SET effective_cache_size = '6GB'; SET max_parallel_workers_per_gather = 1;
SET statement_timeout = '120s';
SELECT gen_random_uuid() AS own, gen_random_uuid() AS veh, gen_random_uuid() AS sx \gset
SELECT auth.t_seed_session(:'sx', :'own');
\set JOB 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE service_role; SET request.jwt.claim.role = ''service_role''; RESET request.jwt.claim.sub; SET request.jwt.claims = ''{"role":"service_role"}'';'
\set ADMIN 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET request.jwt.claim.role; RESET request.jwt.claim.sub; RESET request.jwt.claims;'
\set OWNERX 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; SET request.jwt.claim.sub = ''' :own '''; SET request.jwt.claims = ''{"aal":"aal2","session_id":"' :sx '"}'';'
:ADMIN
INSERT INTO profiles VALUES (:'own');
INSERT INTO vehicles(id, owner_id) VALUES (:'veh', :'own');
CREATE TABLE fx_sc_img (id uuid, taken_at timestamptz, kind text, n int);
INSERT INTO fx_sc_img SELECT gen_random_uuid(), timestamptz '2024-01-18 18:00:00+00' + ((g % 170) * interval '2 days') + (g * interval '7 seconds'), 'own', g FROM generate_series(1, 1330) g;
INSERT INTO fx_sc_img SELECT gen_random_uuid(), NULL, 'lst', g FROM generate_series(1, 10060) g;
INSERT INTO vehicle_images(id, vehicle_id, user_id, taken_at) SELECT id, :'veh', NULL, taken_at FROM fx_sc_img;
INSERT INTO work_sessions(id, user_id, vehicle_id, session_date) SELECT gen_random_uuid(), :'own', :'veh', date '2024-01-18' + (g % 400) FROM generate_series(1, 220) g;
CREATE INDEX ON fx_sc_img (kind, n);
CREATE TABLE fx_sc_runs (k text PRIMARY KEY, id uuid);
GRANT SELECT ON fx_sc_img TO service_role; GRANT ALL ON fx_sc_runs TO service_role;
ANALYZE;   -- the live-shaped tables have statistics (as gen_scale.py's first ANALYZE); the evidence tables are empty
:JOB
\o /dev/null
INSERT INTO fx_sc_runs SELECT 'loop', evidence_open_run(:'own','backfill','loop','script:s','sim','{}');
INSERT INTO fx_sc_runs SELECT p, evidence_open_run(:'own','backfill',p,'script:s','sim',
   CASE WHEN p = 'ledger_vendor_date' THEN '{"coverage_to":"2025-12-31","covers_accounts":["bank_account:sim.main","bank_account:sim.card"],"closed_accounts":["bank_account:sim.card"]}' ELSE '{}' END::jsonb, '{}'::jsonb, NULL, NULL, (SELECT id FROM fx_sc_runs WHERE k = 'loop'))
  FROM unnest(ARRAY['time_offset','combined','photos_album','listing_class','ledger_vendor_date','deal_document','day_context']) p;
SELECT propose_capture_time_claims((SELECT id FROM fx_sc_runs WHERE k = 'time_offset'), (SELECT jsonb_agg(jsonb_build_object('image_id', id, 'stored_taken_at', taken_at,
   'corrected_taken_at', taken_at, 'offset_seconds', 0, 'captured_on', (taken_at AT TIME ZONE 'America/Los_Angeles')::date, 'rule', 'photos_exif_join',
   'witness', jsonb_build_object('unique_match', true), 'confidence', 0.99)) FROM fx_sc_img WHERE kind = 'own' AND n > 0 AND n <= 500));
SELECT propose_image_candidates((SELECT id FROM fx_sc_runs WHERE k = 'combined'), (SELECT jsonb_agg(jsonb_build_object('image_id', id, 'vehicle_id', :'veh'::uuid,
   'verdict', CASE WHEN n % 10 = 0 THEN 'ambiguous' ELSE 'is_vehicle' END, 'join_key', 'combined', 'confidence', 0.7, 'evidence', '[{"kind":"x"}]'::jsonb,
   'image_class', CASE WHEN n % 50 = 0 THEN 'third_party' WHEN n % 97 = 0 THEN 'document' ELSE 'own' END,
   'pass_captured_on', (taken_at AT TIME ZONE 'America/Los_Angeles')::date)) FROM fx_sc_img WHERE kind = 'own' AND n > 0 AND n <= 500));
SELECT propose_capture_time_claims((SELECT id FROM fx_sc_runs WHERE k = 'time_offset'), (SELECT jsonb_agg(jsonb_build_object('image_id', id, 'stored_taken_at', taken_at,
   'corrected_taken_at', taken_at, 'offset_seconds', 0, 'captured_on', (taken_at AT TIME ZONE 'America/Los_Angeles')::date, 'rule', 'photos_exif_join',
   'witness', jsonb_build_object('unique_match', true), 'confidence', 0.99)) FROM fx_sc_img WHERE kind = 'own' AND n > 500 AND n <= 1000));
SELECT propose_image_candidates((SELECT id FROM fx_sc_runs WHERE k = 'combined'), (SELECT jsonb_agg(jsonb_build_object('image_id', id, 'vehicle_id', :'veh'::uuid,
   'verdict', CASE WHEN n % 10 = 0 THEN 'ambiguous' ELSE 'is_vehicle' END, 'join_key', 'combined', 'confidence', 0.7, 'evidence', '[{"kind":"x"}]'::jsonb,
   'image_class', CASE WHEN n % 50 = 0 THEN 'third_party' WHEN n % 97 = 0 THEN 'document' ELSE 'own' END,
   'pass_captured_on', (taken_at AT TIME ZONE 'America/Los_Angeles')::date)) FROM fx_sc_img WHERE kind = 'own' AND n > 500 AND n <= 1000));
SELECT propose_capture_time_claims((SELECT id FROM fx_sc_runs WHERE k = 'time_offset'), (SELECT jsonb_agg(jsonb_build_object('image_id', id, 'stored_taken_at', taken_at,
   'corrected_taken_at', taken_at, 'offset_seconds', 0, 'captured_on', (taken_at AT TIME ZONE 'America/Los_Angeles')::date, 'rule', 'photos_exif_join',
   'witness', jsonb_build_object('unique_match', true), 'confidence', 0.99)) FROM fx_sc_img WHERE kind = 'own' AND n > 1000 AND n <= 1330));
SELECT propose_image_candidates((SELECT id FROM fx_sc_runs WHERE k = 'combined'), (SELECT jsonb_agg(jsonb_build_object('image_id', id, 'vehicle_id', :'veh'::uuid,
   'verdict', CASE WHEN n % 10 = 0 THEN 'ambiguous' ELSE 'is_vehicle' END, 'join_key', 'combined', 'confidence', 0.7, 'evidence', '[{"kind":"x"}]'::jsonb,
   'image_class', CASE WHEN n % 50 = 0 THEN 'third_party' WHEN n % 97 = 0 THEN 'document' ELSE 'own' END,
   'pass_captured_on', (taken_at AT TIME ZONE 'America/Los_Angeles')::date)) FROM fx_sc_img WHERE kind = 'own' AND n > 1000 AND n <= 1330));
SELECT propose_evidence_links((SELECT id FROM fx_sc_runs WHERE k = 'photos_album'), jsonb_build_array(jsonb_build_object('vehicle_id', :'veh', 'source_kind','photos_album','external_ref','photos_album:SC0','role','context','join_key','album','confidence',0.9,'evidence','[{"kind":"album"}]'::jsonb)));
SELECT propose_image_candidates((SELECT id FROM fx_sc_runs WHERE k = 'photos_album'), (SELECT jsonb_agg(jsonb_build_object('image_id', id, 'vehicle_id', :'veh'::uuid,
   'verdict', 'is_vehicle', 'join_key', 'album', 'confidence', 0.9, 'evidence', '[{"kind":"album"}]'::jsonb,
   'album_link_id', (SELECT l.id FROM evidence_links l WHERE l.source_key = 'photos_album:SC0' AND l.superseded_by IS NULL),
   'pass_captured_on', (taken_at AT TIME ZONE 'America/Los_Angeles')::date)) FROM fx_sc_img WHERE kind = 'own' AND n > 0 AND n <= 500));
SELECT propose_image_candidates((SELECT id FROM fx_sc_runs WHERE k = 'photos_album'), (SELECT jsonb_agg(jsonb_build_object('image_id', id, 'vehicle_id', :'veh'::uuid,
   'verdict', 'is_vehicle', 'join_key', 'album', 'confidence', 0.9, 'evidence', '[{"kind":"album"}]'::jsonb,
   'album_link_id', (SELECT l.id FROM evidence_links l WHERE l.source_key = 'photos_album:SC0' AND l.superseded_by IS NULL),
   'pass_captured_on', (taken_at AT TIME ZONE 'America/Los_Angeles')::date)) FROM fx_sc_img WHERE kind = 'own' AND n > 500 AND n <= 1000));
SELECT propose_image_candidates((SELECT id FROM fx_sc_runs WHERE k = 'photos_album'), (SELECT jsonb_agg(jsonb_build_object('image_id', id, 'vehicle_id', :'veh'::uuid,
   'verdict', 'is_vehicle', 'join_key', 'album', 'confidence', 0.9, 'evidence', '[{"kind":"album"}]'::jsonb,
   'album_link_id', (SELECT l.id FROM evidence_links l WHERE l.source_key = 'photos_album:SC0' AND l.superseded_by IS NULL),
   'pass_captured_on', (taken_at AT TIME ZONE 'America/Los_Angeles')::date)) FROM fx_sc_img WHERE kind = 'own' AND n > 1000 AND n <= 1330));
SELECT propose_image_candidates((SELECT id FROM fx_sc_runs WHERE k = 'listing_class'), (SELECT jsonb_agg(jsonb_build_object('image_id', id, 'vehicle_id', :'veh'::uuid,
