   FROM fx_sc_img WHERE kind = 'lst' AND n > 1500 AND n <= 2000));
SELECT propose_image_candidates((SELECT id FROM fx_sc_runs WHERE k = 'listing_class'), (SELECT jsonb_agg(jsonb_build_object('image_id', id, 'vehicle_id', :'veh'::uuid,
   'verdict', 'listing_evidence', 'join_key', 'url', 'confidence', 0.9, 'evidence', '[{"kind":"bat"}]'::jsonb, 'image_class', 'listing'))
   FROM fx_sc_img WHERE kind = 'lst' AND n > 2000 AND n <= 2500));
SELECT propose_image_candidates((SELECT id FROM fx_sc_runs WHERE k = 'listing_class'), (SELECT jsonb_agg(jsonb_build_object('image_id', id, 'vehicle_id', :'veh'::uuid,
   'verdict', 'listing_evidence', 'join_key', 'url', 'confidence', 0.9, 'evidence', '[{"kind":"bat"}]'::jsonb, 'image_class', 'listing'))
   FROM fx_sc_img WHERE kind = 'lst' AND n > 2500 AND n <= 3000));
