SELECT 'V read: work_days ' || jsonb_array_length(CASE WHEN jsonb_typeof(x->'work_days') = 'array' THEN x->'work_days' ELSE '[]' END)
    || ', bands ' || (SELECT string_agg(k, ',' ORDER BY k COLLATE "C") FROM jsonb_object_keys(x->'costs') k)
    || ', closed ' || (x->'money_sources_closed')::text || ', cover_to ' || coalesce(x->>'money_sources_cover_to', '-')
    || ', open_q ' || jsonb_array_length(x->'open_questions')
  FROM (SELECT public.vehicle_accounting_evidence(:'veh', NULL, NULL, :'own') x OFFSET 0) s;   -- one call, not one per use
\o
\set got `cat :outf`
SELECT t_out('F4 10x: what the vehicle read says (as the design sim measured it)', :'got', 'V read: work_days 153, bands asserted_unpaid,high,low,med, closed ["bank_account:sim.card"], cover_to 2025-12-31, open_q 65');
RESET ROLE; RESET SESSION AUTHORIZATION;
\pset format aligned
\pset tuples_only off
SELECT coalesce(nullif(current_setting('t.passed', true), ''), '0') AS g_passed \gset
SELECT t_assert(:g_passed = 20, 'group f4x10: every one of its 20 checks ran and passed');
\echo 'group f4x10: 20 checks passed'
SELECT :passed_total + :g_passed + 1 AS passed_total \gset
\c :main_db
DROP DATABASE :"grp_db" WITH (FORCE);

-- ================================================================================================ group a4
-- the A4 bound (8,000 slot answer rows over 50,000 candidates; the confirmation reader under 3 s)
SELECT left(:'main_db', 48) || '_a4' AS grp_db \gset
DROP DATABASE IF EXISTS :"grp_db" WITH (FORCE);
CREATE DATABASE :"grp_db" TEMPLATE :"tmpl_db" STRATEGY FILE_COPY;   -- a file copy, not the whole template through WAL
\c :grp_db
SET TimeZone = 'America/Los_Angeles'; SET DateStyle = 'ISO, MDY';
\set ON_ERROR_STOP on

-- A4 (answers-v9, design v10 bound; replay9/answers-v9/a4_perf.sql KIND=image N=50000 R=200 M=10 DREP=10, then
-- a4_perf_more.sql S=3 M=10): 50,000 candidates of his; four review sheets of 200 slot rows ("which truck is this?":
-- each row names the image), each answered by 10 chat messages (8,000 answer rows in 40 answers runs); 2,000 of his
-- decisions. evidence_answers_to_confirm in his session (as live, 15 s limit) and as the job: under 3 s each (design sim
-- 0.70-0.81 s; v9 timed out at 15 s). The load ANALYZEs after its first batch, as a library-scale load does (the PR's
-- operational note).
\pset format unaligned
\pset tuples_only on
SET client_min_messages = warning;
SET jit = off; SET random_page_cost = 1.1; SET work_mem = '12MB'; SET effective_cache_size = '6GB'; SET max_parallel_workers_per_gather = 1;
SELECT gen_random_uuid() AS ua, gen_random_uuid() AS va, gen_random_uuid() AS sa \gset
SELECT auth.t_seed_session(:'sa', :'ua');
\set JOB 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE service_role; SET request.jwt.claim.role = ''service_role''; RESET request.jwt.claim.sub; SET request.jwt.claims = ''{"role":"service_role"}'';'
\set OWNERA 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; SET request.jwt.claim.sub = ''' :ua '''; SET request.jwt.claims = ''{"aal":"aal2","session_id":"' :sa '","amr":[{"method":"totp","timestamp":1700000100}]}'';'
\set ADMIN 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET request.jwt.claim.role; RESET request.jwt.claim.sub; RESET request.jwt.claims;'
:ADMIN
INSERT INTO profiles VALUES (:'ua');
INSERT INTO vehicles(id, owner_id, label) VALUES (:'va', :'ua', 'perf truck');
CREATE TABLE fx_a4_img AS SELECT g, gen_random_uuid() AS id FROM generate_series(1, 50000) g;
CREATE UNIQUE INDEX ON fx_a4_img (g);
INSERT INTO vehicle_images(id, vehicle_id, user_id, taken_at, vision_gate_status, label)
  SELECT id, NULL, :'ua', '2024-01-01 18:00+00'::timestamptz + g * interval '1 hour', 'approved', 'p' FROM fx_a4_img;
CREATE TABLE fx_a4_ids (k text PRIMARY KEY, id uuid);
GRANT SELECT ON fx_a4_img TO service_role, authenticated;
GRANT ALL ON fx_a4_ids TO service_role, authenticated;
ANALYZE;
:JOB
\o /dev/null
INSERT INTO fx_a4_ids SELECT 'rc', evidence_open_run(:'ua','pilot','combined','script:combine','sha','{}');
SELECT sum((propose_image_candidates((SELECT id FROM fx_a4_ids WHERE k='rc'), b.rows)->>'proposed')::int) FROM (
  SELECT (i.g - 1) / 500 AS bn, jsonb_agg(jsonb_build_object('image_id', i.id, 'vehicle_id', :'va',
           'verdict','is_vehicle','join_key','x','confidence',0.9,'evidence','[{"kind":"x"}]'::jsonb)) AS rows
    FROM fx_a4_img i WHERE i.g <= 500 GROUP BY 1) b;
:ADMIN
ANALYZE;
:JOB
SELECT sum((propose_image_candidates((SELECT id FROM fx_a4_ids WHERE k='rc'), b.rows)->>'proposed')::int) FROM (
  SELECT (i.g - 1) / 500 AS bn, jsonb_agg(jsonb_build_object('image_id', i.id, 'vehicle_id', :'va',
           'verdict','is_vehicle','join_key','x','confidence',0.9,'evidence','[{"kind":"x"}]'::jsonb)) AS rows
    FROM fx_a4_img i WHERE i.g > 500 GROUP BY 1) b;
INSERT INTO fx_a4_ids SELECT 'sheet', evidence_open_run(:'ua','review','review_sheet','script:review','sha', jsonb_build_object('sheet_sha256','perf','items',200,'rows',
  (SELECT jsonb_object_agg(r::text, jsonb_build_object('question','image_candidate','targets', jsonb_build_array(jsonb_build_object('kind','image','id',c.image_id))))
     FROM generate_series(1, 200) r
     JOIN fx_a4_img i ON i.g = r
     JOIN image_vehicle_candidates c ON c.image_id = i.id AND c.superseded_by IS NULL)));
SELECT evidence_close_run((SELECT id FROM fx_a4_ids WHERE k='sheet'), 'done', '{}'::jsonb);
SELECT pg_sleep(0.02);
SELECT count(*) FROM generate_series(1, 10) m
  CROSS JOIN LATERAL (SELECT evidence_record_answers(:'ua', (SELECT id FROM fx_a4_ids WHERE k='sheet'), 'perf:m' || m,
     (SELECT jsonb_object_agg(r::text, jsonb_build_object('verbatim','message ' || m || ' row ' || r,
              'answer', jsonb_build_object('decision','confirmed','vehicle_id',:'va')))
        FROM generate_series(1, 200) r), 'script:answers', 'sha', clock_timestamp()) AS a) x;
:ADMIN
SELECT array_agg(c.id)::text AS c200 FROM image_vehicle_candidates c JOIN fx_a4_img i ON i.id = c.image_id
 WHERE i.g <= 200 AND c.superseded_by IS NULL \gset
:OWNERA
SELECT count(*) FROM (
  SELECT decide_evidence('image_candidate', :'c200'::uuid[], CASE WHEN rep % 2 = 0 THEN 'confirmed' ELSE 'rejected' END, 'perf', 'app:perf' || rep, 'owner_app', NULL,
                         (SELECT jsonb_object_agg(x::text, NULL) FROM unnest(:'c200'::uuid[]) x)) r
    FROM generate_series(1, 10) rep) x;
:JOB
SELECT count(*) FROM generate_series(1, 3) s
  CROSS JOIN LATERAL (SELECT evidence_open_run(:'ua','review','review_sheet','script:review','sha', jsonb_build_object('sheet_sha256','more'||s,'items',200,'rows',
     (SELECT jsonb_object_agg(r::text, jsonb_build_object('question','image_candidate','targets', jsonb_build_array(jsonb_build_object('kind','image','id', i.id))))
        FROM generate_series(1, 200) r JOIN fx_a4_img i ON i.g = 200 * s + r))) AS sh) a
  CROSS JOIN LATERAL (SELECT evidence_close_run(a.sh, 'done', '{}'::jsonb)) c;
SELECT pg_sleep(0.02);
SELECT count(*) FROM evidence_runs sh CROSS JOIN generate_series(1, 10) m
  CROSS JOIN LATERAL (SELECT evidence_record_answers(:'ua', sh.id, 'more:' || replace(sh.id::text, '-', '') || 'm' || m,
     (SELECT jsonb_object_agg(r::text, jsonb_build_object('verbatim','m' || m || ' r' || r, 'answer', jsonb_build_object('decision','confirmed','vehicle_id',:'va')))
        FROM generate_series(1, 200) r), 'script:answers', 'sha', clock_timestamp()) AS a) x
 WHERE sh.run_kind = 'review' AND sh.config->>'sheet_sha256' LIKE 'more%';
\o
:ADMIN
\o :outf
SELECT 'candidates ' || (SELECT count(*) FROM image_vehicle_candidates) || ', answers runs ' || (SELECT count(*) FROM evidence_runs WHERE run_kind = 'review_answers')
       || ', answer rows ' || (SELECT sum((counts->>'answers')::int) FROM evidence_runs WHERE run_kind = 'review_answers')
       || ', human decisions ' || (SELECT count(*) FROM evidence_decisions WHERE decided_by LIKE 'human:%');
\o
\set got `cat :outf`
SELECT t_out('A4: the load (50,000 candidates, 40 answers runs, 8,000 answer rows, 2,000 of his decisions)', :'got', 'candidates 50000, answers runs 40, answer rows 8000, human decisions 2000');
:OWNERA
SET statement_timeout = '15s';
SELECT clock_timestamp() AS t0 \gset
\o :outf
SELECT 'his session: rows ' || count(*) || ', answers runs ' || count(DISTINCT answers_run) || ', decided ' || count(last_decided_at) || ', questions ' || count(DISTINCT question_key) || ', replaced ' || count(replaced_by) FROM evidence_answers_to_confirm(NULL);
\o
SELECT round(extract(epoch FROM clock_timestamp() - :'t0'::timestamptz) * 1000) AS dt_ms \gset
\echo 'A4: 8,000 slot answer rows over 50,000 candidates, evidence_answers_to_confirm in his session:' :dt_ms 'ms'
SELECT t_assert(:dt_ms < 3000, 'A4: 8,000 slot answer rows over 50,000 candidates, evidence_answers_to_confirm in his session under 3 s');
\set got `cat :outf`
SELECT t_out('A4: what his session lists (one card per question; the older answers replaced)', :'got', 'his session: rows 8000, answers runs 40, decided 2000, questions 800, replaced 7200');
SELECT clock_timestamp() AS t0 \gset
\o :outf
SELECT 'his session again: rows ' || count(*) FROM evidence_answers_to_confirm(NULL);
\o
SELECT round(extract(epoch FROM clock_timestamp() - :'t0'::timestamptz) * 1000) AS dt_ms \gset
\echo 'A4: 8,000 slot answer rows over 50,000 candidates, evidence_answers_to_confirm in his session, again:' :dt_ms 'ms'
SELECT t_assert(:dt_ms < 3000, 'A4: 8,000 slot answer rows over 50,000 candidates, evidence_answers_to_confirm in his session, again, under 3 s');
\set got `cat :outf`
SELECT t_out('A4: his session again', :'got', 'his session again: rows 8000');
:JOB
SET statement_timeout = '60s';
SELECT clock_timestamp() AS t0 \gset
\o :outf
SELECT 'job: rows ' || count(*) FROM evidence_answers_to_confirm(:'ua');
\o
SELECT round(extract(epoch FROM clock_timestamp() - :'t0'::timestamptz) * 1000) AS dt_ms \gset
\echo 'A4: 8,000 slot answer rows over 50,000 candidates, evidence_answers_to_confirm as the job:' :dt_ms 'ms'
SELECT t_assert(:dt_ms < 3000, 'A4: 8,000 slot answer rows over 50,000 candidates, evidence_answers_to_confirm as the job under 3 s');
\set got `cat :outf`
SELECT t_out('A4: the job naming him', :'got', 'job: rows 8000');

RESET ROLE; RESET SESSION AUTHORIZATION;
\pset format aligned
\pset tuples_only off
SELECT coalesce(nullif(current_setting('t.passed', true), ''), '0') AS g_passed \gset
SELECT t_assert(:g_passed = 7, 'group a4: every one of its 7 checks ran and passed');
\echo 'group a4: 7 checks passed'
SELECT :passed_total + :g_passed + 1 AS passed_total \gset
\c :main_db
DROP DATABASE :"grp_db" WITH (FORCE);

-- ================================================================================================ group race
-- the gate race (trucks F1): his "no" to a day, committing while a pass writes that day
SELECT left(:'main_db', 48) || '_race' AS grp_db \gset
DROP DATABASE IF EXISTS :"grp_db" WITH (FORCE);
CREATE DATABASE :"grp_db" TEMPLATE :"tmpl_db" STRATEGY FILE_COPY;   -- a file copy, not the whole template through WAL
\c :grp_db
SET TimeZone = 'America/Los_Angeles'; SET DateStyle = 'ISO, MDY';
\set ON_ERROR_STOP on

-- The gate race (sim/race_f1.sh; trucks F1, design v10; v11 R1): his "no" to a capture time on day D is still open in
-- his own session while the batch-offset pass writes another instant on day D. (v11) The pass takes the claim's row lock
-- before its day check, so it waits for his "no", reads it committed and returns already_rejected: no day-D claim is
-- written. The gate does not confirm his claim, the readers keep the photo undated, and the next pass on day D is
-- already_rejected. Two real sessions through dblink, ordered by what the server reports (the pass waiting on his
-- lock), not by sleeps.
\pset format unaligned
\pset tuples_only on
SET client_min_messages = warning;
CREATE EXTENSION dblink;
SELECT gen_random_uuid() AS ua, gen_random_uuid() AS va, gen_random_uuid() AS im, gen_random_uuid() AS sa \gset
SELECT auth.t_seed_session(:'sa', :'ua');
\set JOB 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE service_role; SET request.jwt.claim.role = ''service_role''; RESET request.jwt.claim.sub; SET request.jwt.claims = ''{"role":"service_role"}'';'
\set ADMIN 'RESET ROLE; RESET SESSION AUTHORIZATION; RESET request.jwt.claim.role; RESET request.jwt.claim.sub; RESET request.jwt.claims;'
\set OWNER 'RESET ROLE; RESET SESSION AUTHORIZATION; SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = ''authenticated''; SET request.jwt.claim.sub = ''' :ua '''; SET request.jwt.claims = ''{"sub":"' :ua '","role":"authenticated","aal":"aal2","session_id":"' :sa '","amr":[{"method":"totp","timestamp":1700000100}]}'';'
:ADMIN
INSERT INTO profiles(id) VALUES (:'ua');
INSERT INTO vehicles(id, owner_id) VALUES (:'va', :'ua');
INSERT INTO vehicle_images(id, vehicle_id, user_id, taken_at) VALUES (:'im', NULL, :'ua', '2024-06-01 18:00+00');
:JOB
SELECT public.evidence_open_run(:'ua','pilot','combined','script:race','sha','{}') AS rc \gset
SELECT public.propose_image_candidates(:'rc', jsonb_build_array(jsonb_build_object('image_id', :'im', 'vehicle_id', :'va', 'verdict','is_vehicle',
         'join_key','x','confidence',0.9,'evidence','[{"kind":"x"}]'::jsonb,'pass_captured_on','2024-06-01')))->>'proposed' AS p0 \gset
SELECT public.evidence_open_run(:'ua','pilot','time_offset','script:race','sha','{}') AS rt1 \gset
SELECT public.propose_capture_time_claims(:'rt1', jsonb_build_array(jsonb_build_object('image_id', :'im', 'stored_taken_at','2024-06-01 18:00+00',
         'corrected_taken_at','2024-06-01 18:00+00','offset_seconds',0,'captured_on','2024-06-01','rule','batch_offset_v1','batch_key','race0',
         'witness',jsonb_build_object('upload_day','2024-06-02'),'confidence',0.6)))->>'proposed' AS p1 \gset
SELECT public.evidence_open_run(:'ua','pilot','time_offset','script:race','sha2','{}') AS rt2 \gset
:ADMIN
SELECT t_assert(:'p0' = '1' AND :'p1' = '1', 'race: the photo has its candidate and a batch-offset claim on day D (proposed, not gated)');
SELECT id AS t1 FROM image_capture_time_claims WHERE image_id = :'im' AND superseded_by IS NULL \gset
SELECT format('dbname=%s host=%s port=%s user=%s', current_database(), split_part(current_setting('unix_socket_directories'), ',', 1),
              current_setting('port'), current_user) AS conn \gset
SELECT dblink_connect('race_owner', :'conn' || ' application_name=race_owner') \g /dev/null
SELECT dblink_connect('race_pass', :'conn' || ' application_name=race_pass') \g /dev/null
-- his session (the API's shape) opens a transaction and says "no" to day D: the claim's row lock is his until COMMIT
SELECT dblink_exec('race_owner', format('SET SESSION AUTHORIZATION authenticator; SET ROLE authenticated; SET request.jwt.claim.role = %L; '
         'SET request.jwt.claim.sub = %L; SET request.jwt.claims = %L', 'authenticated', :'ua',
         jsonb_build_object('sub', :'ua', 'role', 'authenticated', 'aal', 'aal2', 'session_id', :'sa',
                            'amr', '[{"method":"totp","timestamp":1700000100}]'::jsonb)::text)) \g /dev/null
SELECT dblink_exec('race_owner', 'BEGIN') \g /dev/null
SELECT r AS his_no FROM dblink('race_owner', format('SELECT public.decide_evidence(%L, ARRAY[%L]::uuid[], %L, %L, %L, %L)->''items''->0->>''result''',
         'capture_time_claim', :'t1', 'rejected', 'not that day', 'app:race-f1', 'owner_app')) AS t(r text) \gset
SELECT t_assert(:'his_no' = 'rejected', 'race: his "no" to day D, in his own session, not yet committed');
-- the job's pass on day D, in a second session, while his "no" is open
SELECT dblink_exec('race_pass', 'SET SESSION AUTHORIZATION authenticator; SET ROLE service_role; SET request.jwt.claim.role = ''service_role''; '
         'RESET request.jwt.claim.sub; SET request.jwt.claims = ''{"role":"service_role"}''') \g /dev/null
SELECT dblink_send_query('race_pass', format('SELECT (public.propose_capture_time_claims(%L, %L::jsonb) - ''ids'' - ''decision_ids'' - ''owner_answer_missing_ids'')::text',
         :'rt2', jsonb_build_array(jsonb_build_object('image_id', :'im', 'stored_taken_at','2024-06-01 18:00+00','corrected_taken_at','2024-06-01 14:00+00',
         'offset_seconds',14400,'captured_on','2024-06-01','rule','batch_offset_v1','batch_key','race4',
         'witness',jsonb_build_object('upload_day','2024-06-02'),'confidence',0.6))::text)) \g /dev/null
DO $$ BEGIN   -- until the pass waits on his lock (or has finished without waiting); at most 20 s
  FOR i IN 1..400 LOOP
    EXIT WHEN EXISTS (SELECT 1 FROM pg_stat_activity WHERE application_name = 'race_pass'
                       AND (wait_event_type = 'Lock' OR state = 'idle'));
    PERFORM pg_sleep(0.05);
  END LOOP;
END $$;
SELECT coalesce((SELECT CASE WHEN wait_event_type = 'Lock' THEN 'waiting on his lock' ELSE state END FROM pg_stat_activity
                  WHERE application_name = 'race_pass'), 'gone') AS pass_state \gset
\echo 'race: the pass, before his "no" commits:' :pass_state
SELECT dblink_exec('race_owner', 'COMMIT') \g /dev/null
SELECT r AS pass_result FROM dblink_get_result('race_pass') AS t(r text) \gset
SELECT dblink_disconnect('race_owner'), dblink_disconnect('race_pass') \g /dev/null
SELECT t_assert(:'pass_state' = 'waiting on his lock', 'race: the pass on day D waits on his lock before its day check (v11 R1)');
SELECT t_assert((:'pass_result')::jsonb->>'proposed' = '0' AND (:'pass_result')::jsonb->>'already_rejected' = '1',
  'race: once his "no" commits, the pass reads it: already_rejected, nothing proposed');
SELECT id AS t2 FROM image_capture_time_claims WHERE image_id = :'im' AND superseded_by IS NULL \gset
SELECT t_assert(EXISTS (SELECT 1 FROM evidence_decisions d WHERE d.target_id = :'t1' AND d.decided_by LIKE 'human:%' AND d.decision = 'rejected')
                AND :'t2' = :'t1' AND (SELECT count(*) FROM image_capture_time_claims WHERE image_id = :'im') = 1,
  'race: no day-D claim was written; his human "no" sits on the one claim, still the current one');
:JOB
SELECT public.evidence_open_run(:'ua','daily','time_rule_gate','script:race','sha','{}') AS g \gset
SELECT public.evidence_close_run(:'g', 'done', '{"batches":{"race4":{"joined":80,"agreement":0.996,"offset_seconds":14400}}}'::jsonb) \g /dev/null
\o :outf
SELECT public.confirm_capture_times_by_rule(:'g', ARRAY[:'t2']::uuid[])->>'confirmed';
\o
\set got `cat :outf`
SELECT t_out('race: the gate does not confirm that claim (never on a day he said no to)', :'got', '0');
:OWNER
\o :outf
SELECT string_agg(coalesce(captured_on::text, 'NULL') || ' unverified ' || time_unverified, '; ')
  FROM public.evidence_candidates_for_images(ARRAY[:'im']::uuid[], :'ua');
\o
\set got `cat :outf`
SELECT t_out('race: the readers, his session: the photo stays undated', :'got', 'NULL unverified true');
:JOB
SELECT public.evidence_open_run(:'ua','pilot','time_offset','script:race','sha3','{}') AS rt3 \gset
\o :outf
SELECT public.propose_capture_time_claims(:'rt3', jsonb_build_array(jsonb_build_object('image_id', :'im', 'stored_taken_at','2024-06-01 18:00+00',
         'corrected_taken_at','2024-06-01 15:00+00','offset_seconds',10800,'captured_on','2024-06-01','rule','batch_offset_v1','batch_key','race3',
         'witness',jsonb_build_object('upload_day','2024-06-02'),'confidence',0.6)))->>'already_rejected';
\o
\set got `cat :outf`
SELECT t_out('race: the next pass on day D is already_rejected', :'got', '1');

RESET ROLE; RESET SESSION AUTHORIZATION;
\pset format aligned
\pset tuples_only off
SELECT coalesce(nullif(current_setting('t.passed', true), ''), '0') AS g_passed \gset
SELECT t_assert(:g_passed = 8, 'group race: every one of its 8 checks ran and passed');
\echo 'group race: 8 checks passed'
SELECT :passed_total + :g_passed + 1 AS passed_total \gset
\c :main_db
DROP DATABASE :"grp_db" WITH (FORCE);

-- ================================================================================================ end
DROP DATABASE IF EXISTS :"tmpl_db" WITH (FORCE);
\set rm_scratch `rm -f :outf`
SELECT :passed_total AS checks_passed, 'image evidence writers contract: PASS' AS result;
